# ---- writing TTS: a separate, optional voice that speaks a quick cue for each
# line as you type ("a equals 4"). Own volume + toggle (independent of the tutor
# voice) and it plays through its OWN sequential queue — one cue never cuts off
# the next, so nothing gets disturbed. --------------------------------------------------

_WRITE_VOL = 0.7
_WRITE_MUTED = False
_WRITE_Q = []
_WRITE_COND = threading.Condition()
_WRITE_ALIVE = [True]


def writing_volume() -> float:
    return 0.0 if _WRITE_MUTED else _WRITE_VOL


def set_writing_volume(vol: float) -> None:
    global _WRITE_VOL
    _WRITE_VOL = max(0.0, min(1.0, vol))


def toggle_writing_mute() -> bool:
    global _WRITE_MUTED
    _WRITE_MUTED = not _WRITE_MUTED
    return _WRITE_MUTED


def _writing_tts_loop() -> None:
    """Sequential player: each writing cue waits for the previous one to finish,
    so rapid typing queues the cues in order instead of overlapping."""
    while _WRITE_ALIVE[0]:
        with _WRITE_COND:
            while not _WRITE_Q:
                _WRITE_COND.wait()
            text, rate, main = _WRITE_Q.pop(0)
        vol = voice_volume() if main else writing_volume()
        if _tts_engine() == "espeak":
            amp = int(round(200 * vol))
            if amp <= 0:
                continue
            speed = max(120, int(180 / rate))
            try:
                subprocess.run(["espeak-ng", "-s", str(speed), "-a", str(amp), text],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
        else:
            raw = synthesize(text, rate)
            if not raw:
                continue
            gain = vol
            if gain <= 0.0:
                continue
            raw = _scale_raw(raw, gain)
            try:
                p = subprocess.Popen(["aplay", "-r", "22050", "-f", "S16_LE", "-t", "raw"],
                                     stdin=subprocess.PIPE, stdout=subprocess.DEVNULL,
                                     stderr=subprocess.DEVNULL)
                p.stdin.write(raw)
                p.stdin.close()
                p.wait()   # hold until THIS cue finishes before the next one
            except Exception:
                pass


threading.Thread(target=_writing_tts_loop, daemon=True).start()


def speak_write(text: str, rate: float = 0.85, main: bool = False) -> None:
    """Enqueue a sequential cue. `rate` < 1.0 = faster (piper length_scale).
    `main=True` uses the main VOICE volume (lesson narration); the default uses
    the quieter writing-cue volume (ghost-typing feedback)."""
    clean = _prep_tts(text)
    if not clean:
        return
    with _WRITE_COND:
        _WRITE_Q.append((clean, rate, main))
        _WRITE_COND.notify()


# ---- code → a short spoken "visualization" cue ----------------------------- #
# Turns a line you just wrote into a quick phrase for the writing TTS voice,
# e.g. `a = 4` → "a equals four", `if a > b:` → "if a is greater than b".

_NUM_WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven",
              "eight", "nine", "ten", "eleven", "twelve", "thirteen",
              "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
              "nineteen"]
_NUM_TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
             "eighty", "ninety"]


def _num_words(n: int) -> str:
    if n < 20:
        return _NUM_WORDS[n]
    if n < 100:
        return _NUM_TENS[n // 10] + (" " + _NUM_WORDS[n % 10] if n % 10 else "")
    return str(n)


def _cue_tokens(expr: str) -> str:
    """Replace numeric tokens with words and comparison ops with plain words."""
    out = expr
    out = re.sub(r'\b(\d+)\b', lambda m: _num_words(int(m.group(1))), out)
    out = out.replace(">=", " is at least ").replace("<=", " is at most ")
    out = out.replace("==", " equals ")
    out = out.replace("+=", " increases by ").replace("-=", " decreases by ")
    out = out.replace("*=", " times ").replace("/=", " divided by ")
    out = out.replace(">", " is greater than ").replace("<", " is less than ")
    out = out.replace("+", " plus ").replace("=", " equals ")
    out = out.replace('"', "").replace("'", "")
    return re.sub(r"\s+", " ", out).strip()


def _line_need(line: str) -> list[str]:
    """The syntax tokens a line needs — a per-line 'what's required' hint. Shows
    the keywords, structural symbols, and quote/string marker of the line."""
    line = line.strip()
    if not line:
        return []
    toks = []
    for kw in ("def", "if", "elif", "else", "for", "while", "return",
               "print", "in", "not", "and", "or", "class", "import", "range",
               "len", "input", "append", "with", "open", "as", "yield", "lambda"):
        if re.search(rf"\b{kw}\b", line):
            toks.append(kw)
    for sym in ("(", ")", ":", "[", "]", "{", "}", "=", "+", "-", "*", "/", "%",
                ".", ",", ">", "<", "==", "!="):
        if sym in line:
            toks.append(sym)
    if '"' in line or "'" in line:
        toks.append('""')
    return toks


def _reflow_output(text: str, width: int = 60, min_lines: int = 6) -> str:
    """Reflow a long vertical list of short values (numbers printed one per
    line) into a horizontal grid, so output fills the row and wraps DOWN instead
    of spilling off the bottom of a short console. Prose and long lines pass
    through untouched."""
    lines = text.split("\n")
    if len(lines) < min_lines:
        return text
    if max((len(l) for l in lines), default=0) > 16:
        return text
    width = max(24, width)
    cols = max(1, width // 8)          # ~8 cells per value
    out_lines, row = [], []
    for ln in lines:
        row.append(ln)
        if len(row) >= cols:
            out_lines.append("  ".join(v.ljust(6) for v in row))
            row = []
    if row:
        out_lines.append("  ".join(v.ljust(6) for v in row))
    return "\n".join(out_lines)


def _line_cue(line: str) -> str:
    """A short phrase describing what a code line does, for the writing voice."""
    line = line.strip()
    if not line:
        return ""
    m = re.match(r'^if\s+(.+?)\s*:\s*$', line)
    if m:
        return "if " + _cue_tokens(m.group(1))
    m = re.match(r'^elif\s+(.+?)\s*:\s*$', line)
    if m:
        return "else if " + _cue_tokens(m.group(1))
    m = re.match(r'^while\s+(.+?)\s*:\s*$', line)
    if m:
        return "while " + _cue_tokens(m.group(1))
    m = re.match(r'^for\s+(.+?)\s+in\s+(.+?)\s*:\s*$', line)
    if m:
        return f"for {m.group(1)} in {_cue_tokens(m.group(2))}"
    m = re.match(r'^def\s+(\w+)', line)
    if m:
        return "define function " + m.group(1)
    m = re.match(r'^return\s*(.*)$', line)
    if m:
        return "return" + (" " + _cue_tokens(m.group(1)) + " as the answer"
                           if m.group(1) else "")
    m = re.match(r'^print\((.+)\)\s*$', line)
    if m:
        return "print " + _cue_tokens(m.group(1)) + " to the screen"
    m = re.match(r'^([A-Za-z_]\w*)\s*=\s*(.+)$', line)
    if m and "==" not in line and "<=" not in line and ">=" not in line:
        return f"{m.group(1)} equals {_cue_tokens(m.group(2))}"
    return _cue_tokens(line)


def toggle_sfx_mute() -> bool:
    global _SFX_MUTED
    _SFX_MUTED = not _SFX_MUTED
    return _SFX_MUTED


def _pa_vol(base: int) -> int:
    """Scale a paplay 0..65536 volume by the SFX fader."""
    return int(round(base * sfx_volume()))


def _player_vol(frac: float) -> int:
    """Scale a 0..1 fraction into a 0..100 ffplay/mpv volume (SFX fader)."""
    return int(round(frac * 100 * sfx_volume()))


def _scale_raw(raw: bytes, gain: float) -> bytes:
    """Scale 16-bit mono PCM by `gain` (0..1). Fast path when at full volume."""
    if gain >= 1.0:
        return raw
    arr = array.array("h")
    arr.frombytes(raw)
    for i in range(len(arr)):
        arr[i] = int(arr[i] * gain)
    return arr.tobytes()


SUCCESS_SOUND = "/usr/share/sounds/freedesktop/stereo/complete.oga"

# Vibrant color wheel the command-showcase ghost flashes through (always BOLD),
# so the "what to write" bar visibly vibrates through bright hues instead of
# sitting dim and grey once it finishes typing out.
_GHOST_FLASH = ["#fbbf24", "#f97316", "#fb7185", "#c084fc", "#22d3ee"]


# ---- realistic bash command coloring ------------------------------------- #
# Colors a typed command the way a real fish/zsh prompt does, so the terminal
# reads like an actual shell instead of a flat white line: green command, yellow
# flags, orange strings, blue numbers, light arguments.
def _colorize_command(cmd: str) -> Text:
    t = Text()
    # Split on whitespace but KEEP the spaces (re.split with a capture group).
    # Using .split() here dropped every space, so a trailing space made the
    # cursor look frozen — typing a space must visibly move the cursor.
    token_idx = 0
    for part in re.split(r"(\s+)", cmd):
        if not part:
            continue
        if part.isspace():
            t.append(part)                         # keep the space (cursor position)
            continue
        if token_idx == 0:
            t.append(part, style="bold #7ee787")   # command name — green
        elif part.startswith("-"):
            t.append(part, style="#ffd866")        # flag / option — yellow
        elif '"' in part or "'" in part:
            t.append(part, style="#ffa657")        # (part of a) string — orange
        elif part.isdigit():
            t.append(part, style="#79c0ff")        # number — blue
        else:
            t.append(part, style="#e6edf3")        # argument — light
        token_idx += 1
    return t


def _colorize_output(line: str) -> Text:
    """Color a fake-terminal output line like a real shell: success words green,
    errors red, warnings yellow, paths cyan, numbers blue. The base is a soft,
    slightly smaller-looking gray."""
    t = Text()
    low = line.lower()

    def has_any(words):
        return any(re.search(rf"\b{re.escape(w)}\b", low) for w in words)

    if any(w in low for w in ("error", "failed", "no such", "not found",
                              "refused", "denied", "exception", "traceback")):
        t.append(line, style="#f87171")
        return t
    if (has_any(("running", "up", "success", "created", "deployed",
                 "completed", "passed", "clean"))
            or any(s in low for s in ("up to date", "nothing to commit"))
            or "✓" in line):
        t.append(line, style="#4ade80")
        return t
    if has_any(("warning", "pending", "waiting", "skipping")):
        t.append(line, style="#fbbf24")
        return t
    for part in re.split(r'(/\S+|\./\S+|~\S*|\b\d+\b)', line):
        if not part:
            continue
        if re.match(r'^(/\S+|\./\S+|~\S*)', part):
            t.append(part, style="#7dd3fc")        # path — cyan
        elif part.isdigit():
            t.append(part, style="#93c5fd")        # number — blue
        else:
            t.append(part, style="#aab0bd")        # base — soft gray (smaller look)
    return t


