MUSIC_DIRS = [
    Path.home() / ".learning" / "music",   # bundled install location (install.sh)
    Path.home() / "Music",                 # legacy / the user's own copies
]


def _music_list(*patterns) -> list[Path]:
    """Audio files matching any glob pattern, searched across the bundled dir
    and ~/Music. Deduped by filename so a bundled copy + a local copy never
    double up (and the celebration/fail pools stay the same length)."""
    out: list[Path] = []
    seen: set[str] = set()
    for d in MUSIC_DIRS:
        for p in patterns:
            for f in sorted(d.glob(p)):
                if f.name not in seen:
                    seen.add(f.name)
                    out.append(f)
    return out


CEL_SOUNDS = _music_list("cel*.mp3")
FAIL_SOUNDS = _music_list("fail*.mp3", "fafil*.mp3")


def play_file(path: Path, volume: float = 0.7) -> None:
    """Play a win/fail mp3 at REDUCED volume (70% — 30% below the TTS voice) so
    the celebration/fail sting never drowns out the coach's spoken feedback."""
    if path is None:
        return
    if sfx_volume() <= 0.0:
        return   # sfx muted — no point spawning a silent player
    p = str(path)
    vol100 = _player_vol(volume)                  # ffplay/mpv use 0..100
    vol16 = _pa_vol(int(round(volume * 65536)))   # paplay uses 0..65536
    for cmd in (["ffplay", "-nodisp", "-autoexit", "-loglevel", "quiet",
                 "-volume", str(vol100), p],
                ["mpv", "--no-video", "--really-quiet", f"--volume={vol100}", p],
                ["paplay", f"--volume={vol16}", p],
                ["pw-play", p]):
        if shutil.which(cmd[0]):
            try:
                subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return
            except Exception:
                continue


