SHELL_STAGES = ["Meet the Terminal", "Folders & Paths", "Make & Inspect Files",
                "Write & Read", "Pipes & Search", "Copy, Move, Delete",
                "Run & Build", "Shells & Tools", "Stream Editing",
                "Columns & Fields", "Find & Bundle", "Env & Regex",
                "Permissions & Processes", "Chain & Connect"]

# A tiny, deterministic fake filesystem so the learner can practice REAL bash
# (pwd / ls / mkdir / cd / touch / cat / echo / grep / pipes / chmod / …)
# WITHOUT touching the real disk. Every command is safe to run forever.
def _shell_split(s: str) -> list[str]:
    """Split a command line on whitespace, respecting single/double quotes and
    backslash escapes, and stripping the quotes — like a real shell does."""
    parts = []
    cur = []
    in_single = in_double = False
    i = 0
    while i < len(s):
        c = s[i]
        if in_single:
            if c == "'":
                in_single = False
            else:
                cur.append(c)
        elif in_double:
            if c == '"':
                in_double = False
            elif c == "\\" and i + 1 < len(s):
                cur.append(s[i + 1]); i += 1
            else:
                cur.append(c)
        else:
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c == "\\" and i + 1 < len(s):
                cur.append(s[i + 1]); i += 1
            elif c.isspace():
                if cur:
                    parts.append("".join(cur)); cur = []
            else:
                cur.append(c)
        i += 1
    if cur:
        parts.append("".join(cur))
    return parts


def _shell_split_on(s: str, delim: str) -> list[str]:
    """Split `s` on `delim` only where it appears OUTSIDE single/double quotes,
    so `grep -E 'print|echo'` keeps its literal `|` while a real pipe still
    splits. Quotes are left in the segments (the tokenizer strips them later)."""
    out = []
    cur = []
    in_single = in_double = False
    i = 0
    while i < len(s):
        c = s[i]
        if in_single:
            cur.append(c)
            if c == "'":
                in_single = False
        elif in_double:
            cur.append(c)
            if c == '"':
                in_double = False
        elif c == "'":
            in_single = True
            cur.append(c)
        elif c == '"':
            in_double = True
            cur.append(c)
        elif s.startswith(delim, i):
            out.append("".join(cur))
            cur = []
            i += len(delim) - 1
        else:
            cur.append(c)
        i += 1
    out.append("".join(cur))
    return out


def _shell_split_chain(s: str) -> list:
    """Split a command line on top-level `;` and `&&` (outside quotes) into
    (text, separator_after) pairs, so `mkdir x && cd x` runs as two commands."""
    seps = ["&&", ";"]
    segs = []
    cur = []
    in_single = in_double = False
    i = 0
    while i < len(s):
        c = s[i]
        if in_single:
            cur.append(c)
            if c == "'":
                in_single = False
        elif in_double:
            cur.append(c)
            if c == '"':
                in_double = False
        elif c == "'":
            in_single = True
            cur.append(c)
        elif c == '"':
            in_double = True
            cur.append(c)
        else:
            matched = None
            for sep in seps:
                if s.startswith(sep, i):
                    matched = sep
                    break
            if matched:
                segs.append(("".join(cur), matched))
                cur = []
                i += len(matched) - 1
            else:
                cur.append(c)
        i += 1
    segs.append(("".join(cur), None))
    return segs


class ShellFS:
    """A sandboxed home directory the learner fills up over the course.

    `dirs` is a set of absolute directory paths; `files` maps an absolute path
    to its text content; `executable` marks files that `chmod +x` made runnable.
    `latest` remembers the last changed path so the file tree can highlight it.
    `history` records every command line, so `history` can list them back."""

    def __init__(self):
        self.home = "/home/you"
        self.cwd = self.home
        self.dirs = {"/", "/home", "/home/you"}
        self.files = {}
        self.executable = set()
        self.latest = None
        self.history: list[str] = []
        self.env = {"HOME": "/home/you", "USER": "you", "SHELL": "/bin/bash",
                    "PATH": "/usr/local/bin:/usr/bin:/bin"}
        self.archives = {}   # archive name -> {entry: content} for tar
        self.processes = {1: "init", 42: "bash", 201: "python3 app.py"}   # pid -> cmd
        self.services = {"web": {"state": "running", "enabled": True,
                                 "logs": ["web: listening on :8080",
                                          "web: 200 GET /index.html"]},
                         "db": {"state": "running", "enabled": True,
                                "logs": ["db: accepting connections"]}}
        self.ssh_host = None   # None = local; a string like "user@server" = remote
        self._local_cwd = None  # remembers the cwd across an ssh session

    # -- path helpers ------------------------------------------------------ #
    def _resolve(self, path: str) -> str:
        while path.startswith("./"):
            path = path[2:]
        if path in ("", ".", "~"):
            return self.home
        if path == "..":
            return "/" if self.cwd == "/" else (self.cwd.rsplit("/", 1)[0] or "/")
        if path == "/":
            return "/"
        if path.startswith("/"):
            return path.rstrip("/") or "/"
        return (self.cwd.rstrip("/") + "/" + path).rstrip("/") or "/"

    def _children(self, path: str) -> list:
        base = path.rstrip("/") + "/"
        names = set()
        for d in self.dirs:
            if d.startswith(base) and d != path:
                rest = d[len(base):]
                if "/" not in rest:
                    names.add((rest, "dir"))
        for f in self.files:
            if f.startswith(base):
                rest = f[len(base):]
                if "/" not in rest:
                    names.add((rest, "file"))
        return sorted(names)

    def tree(self):
        """(indent, label, full_path, kind) from home down — for the live tree."""
        out = [(0, self.home + "/", self.home, "dir")]
        def walk(path, depth):
            for name, kind in self._children(path):
                full = path.rstrip("/") + "/" + name
                out.append((depth + 1, name + ("/" if kind == "dir" else ""), full, kind))
                if kind == "dir":
                    walk(full, depth + 1)
        walk(self.home, 0)
        return out

    def _expand(self, args):
        """Expand `*` globs against the cwd's names (no match → keep literal)."""
        out = []
        for a in args:
            if "*" in a:
                rx = "^" + re.escape(a).replace(r"\*", ".*") + "$"
                m = [n for n, _ in self._children(self.cwd) if re.match(rx, n)]
                out.extend(m if m else [a])
            else:
                out.append(a)
        return out

    def _read_lines(self, files, stdin_lines):
        """Read lines from files (glob-expanded) or stdin if no files given.
        Returns None on a missing/unreadable file (caller turns it into an error)."""
        if not files:
            return list(stdin_lines or [])
        lines = []
        for a in self._expand(files):
            p = self._resolve(a)
            if p in self.files:
                lines.extend(self.files[p].rstrip("\n").split("\n"))
            else:
                return None
        return lines

    # -- the public entry point (handles pipes) ---------------------------- #
    def run(self, cmdline: str, stdin_lines=None):
        """Run one line of bash. Returns (out_lines, err_lines)."""
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        self.history.append(cmdline)
        # `cmd1 && cmd2` / `cmd1 ; cmd2` chain top-level commands (quote-aware)
        if "&&" in cmdline or ";" in cmdline:
            chain = _shell_split_chain(cmdline)
            all_out = []
            for text, sep in chain:
                out, err = self.run(text.strip())
                all_out.extend(out)
                if err:
                    all_out.extend(err)
                    if sep == "&&":
                        return all_out, err   # short-circuit: later steps skipped
            return all_out, []
        if "|" in cmdline:
            data = stdin_lines
            for stage in [s.strip() for s in _shell_split_on(cmdline, "|")]:
                out, err = self._run_one(stage, data)
                if err:
                    return out, err
                data = out
            return data, []
        return self._run_one(cmdline, stdin_lines)

    def _run_one(self, cmdline, stdin_lines=None):
        """One command (no pipes), with `>` / `>>` redirect stripped first."""
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        target = None
        append = False
        if ">>" in cmdline:
            segs = _shell_split_on(cmdline, ">>")
            if len(segs) > 1:
                cmdline, target = segs[0], segs[-1].strip()
                append = True
        elif ">" in cmdline:
            segs = _shell_split_on(cmdline, ">")
            if len(segs) > 1:
                cmdline, target = segs[0], segs[-1].strip()
        out, err = self._dispatch(cmdline, stdin_lines)
        if target is not None and not err:
            tp = self._resolve(target.strip())
            if tp in self.dirs:
                return [], [f"bash: {target.strip()}: Is a directory"]
            body = "\n".join(out) + ("\n" if out else "")
            if append:
                self.files[tp] = self.files.get(tp, "") + body
            else:
                self.files[tp] = body
            self.latest = tp
            return [], []
        return out, err

    def _dispatch(self, cmdline, stdin_lines=None):
        parts = _shell_split(cmdline)
        if not parts:
            return [], []
        cmd = parts[0]
        args = parts[1:]
        if cmd == "echo":
            text = cmdline[4:].strip()
            if len(text) >= 2 and text[0] in ('"', "'") and text[-1] == text[0]:
                text = text[1:-1]
            # expand $VAR and ${VAR} against the environment
            text = re.sub(r"\$\{?(\w+)\}?", lambda m: self.env.get(m.group(1), ""), text)
            return [text], []
        if cmd == "pwd":
            return [self.cwd], []
        if cmd == "whoami":
            return ["you"], []
        if cmd == "clear":
            return ["__CLEAR__"], []
        if cmd == "history":
            return [f"{i+1:>3}  {c}" for i, c in enumerate(self.history[-15:])], []
        if cmd == "ls":
            return self._ls(args), []
        if cmd == "mkdir":
            return self._mkdir(args)
        if cmd == "cd":
            return self._cd(args)
        if cmd == "touch":
            return self._touch(args)
        if cmd == "cat":
            return self._cat(args, stdin_lines)
        if cmd in ("head", "tail"):
            return self._head_tail(cmd, args, stdin_lines)
        if cmd == "wc":
            return self._wc(args, stdin_lines)
        if cmd == "grep":
            return self._grep(args, stdin_lines)
        if cmd == "sed":
            return self._sed(args, stdin_lines)
        if cmd == "awk":
            return self._awk(args, stdin_lines)
        if cmd == "find":
            return self._find(args)
        if cmd == "tar":
            return self._tar(args)
        if cmd == "export":
            return self._export(args)
        if cmd in ("env", "printenv"):
            return [f"{k}={v}" for k, v in sorted(self.env.items())], []
        if cmd == "python3":
            return self._python(args)
        if cmd == "mv":
            return self._mv(args)
        if cmd == "cp":
            return self._cp(args)
        if cmd == "rm":
            return self._rm(args)
        if cmd == "chmod":
            return self._chmod(args)
        if cmd == "ps":
            return self._ps(args)
        if cmd == "kill":
            return self._kill(args)
        if cmd == "curl":
            return self._curl(args)
        if cmd == "systemctl":
            return self._systemctl(args)
        if cmd == "journalctl":
            return self._journalctl(args)
        if cmd == "ssh":
            return self._ssh(args)
        if cmd == "ssh-keygen":
            return self._ssh_keygen(args)
        if cmd == "ssh-copy-id":
            return self._ssh_copy_id(args)
        if cmd in ("exit", "logout"):
            return self._exit_ssh(args)
        if cmd in ("man", "help", "--help"):
            return ["commands:  pwd  ls  mkdir  cd  touch  cat  echo  head  tail  wc  grep  sed  "
                    "awk  find  tar  export  env  ps  kill  curl  python3  mv  cp  rm  chmod  "
                    "systemctl  journalctl  ssh  whoami  clear  history  "
                    "(also:  cmd1 && cmd2   and   cmd1 ; cmd2)"], []
        if cmd.startswith("./") or cmd.startswith("/"):
            return self._run_executable(cmd)
        return [], [f"{cmd}: command not found"]

    # -- individual commands ------------------------------------------------ #
    def _human(self, n):
        if n >= 1024:
            return f"{round(n / 1024, 1)}K"
        return f"{n}B"

    def _ls(self, args):
        flags = [a for a in args if a.startswith("-") and len(a) > 1]
        pos = [a for a in args if not (a.startswith("-") and len(a) > 1)]
        show_hidden = any("a" in f for f in flags)
        long = any("l" in f for f in flags)
        human = any("h" in f for f in flags)
        if pos:
            names = set()
            for p in pos:
                if "*" in p:
                    rx = "^" + re.escape(p).replace(r"\*", ".*") + "$"
                    names.update((n, k) for n, k in self._children(self.cwd) if re.match(rx, n))
                else:
                    full = self._resolve(p)
                    if full in self.dirs:
                        names.add((p.rstrip("/") + "/", "dir"))
                    elif full in self.files:
                        names.add((p, "file"))
            names = sorted(names)
        else:
            names = self._children(self.cwd)
        if not show_hidden:
            names = [(n, k) for n, k in names if not n.startswith(".")]
        if not names:
            return []
        if long:
            out = []
            for name, kind in names:
                if kind == "dir":
                    out.append(f"drwxr-xr-x  2 you  you  4096  Sep  7 09:00  {name}/")
                else:
                    size = len(self.files.get(self._resolve(name), ""))
                    mode = "-rwxr-xr-x" if self._resolve(name) in self.executable else "-rw-r--r--"
                    s = self._human(size) if human else f"{size:>5}"
                    out.append(f"{mode}  1 you  you  {s}  Sep  7 09:00  {name}")
            return out
        return [name + ("/" if kind == "dir" else "") for name, kind in names]

    def _mkdir(self, args):
        parents = "-p" in args
        targets = [a for a in args if not a.startswith("-")]
        if not targets:
            return [], ["mkdir: missing operand"]
        out = []
        for a in targets:
            p = self._resolve(a)
            if (p in self.dirs or p in self.files) and not parents:
                out.append(f"mkdir: cannot create directory '{a}': File exists")
                continue
            if parents:
                cur = "/"
                for seg in p.strip("/").split("/"):
                    cur = (cur.rstrip("/") + "/" + seg).rstrip("/") or "/"
                    self.dirs.add(cur)
            else:
                self.dirs.add(p)
            self.latest = p
        return out, []

    def _cd(self, args):
        if not args:
            self.cwd = self.home
            return [], []
        p = self._resolve(args[0])
        if p in self.dirs:
            self.cwd = p
            return [], []
        if p in self.files:
            return [], [f"bash: cd: {args[0]}: Not a directory"]
        return [], [f"bash: cd: {args[0]}: No such file or directory"]

    def _touch(self, args):
        expanded = self._expand(args)
        if not expanded:
            return [], ["touch: missing file operand"]
        for a in expanded:
            p = self._resolve(a)
            if p in self.dirs:
                return [], [f"touch: cannot touch '{a}': Is a directory"]
            self.files.setdefault(p, "")
            self.latest = p
        return [], []

    def _cat(self, args, stdin_lines):
        if not args:
            return list(stdin_lines or []), []
        out = []
        for a in self._expand(args):
            p = self._resolve(a)
            if p in self.files:
                out.extend(self.files[p].rstrip("\n").split("\n"))
            elif p in self.dirs:
                out.append(f"cat: {a}: Is a directory")
            else:
                out.append(f"cat: {a}: No such file or directory")
        return out, []

    def _head_tail(self, cmd, args, stdin_lines):
        n = 10
        files = []
        i = 0
        while i < len(args):
            a = args[i]
            if a == "-n" and i + 1 < len(args):
                n = int(args[i + 1]); i += 2
            elif a.startswith("-n"):
                n = int(a[2:]); i += 1
            elif re.fullmatch(r"-\d+", a):
                n = int(a[1:]); i += 1
            elif a.startswith("-"):
                i += 1
            else:
                files.append(a); i += 1
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], [f"{cmd}: No such file or directory"]
        return (lines[:n] if cmd == "head" else lines[-n:]), []

    def _wc(self, args, stdin_lines):
        count_lines = "-l" in args
        files = [a for a in args if not a.startswith("-")]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["wc: No such file or directory"]
        if count_lines:
            return [str(len(lines))], []
        words = sum(len(l.split()) for l in lines)
        chars = sum(len(l) for l in lines)
        name = (" " + files[0]) if files else ""
        return [f"  {len(lines)}  {words}  {chars}{name}"], []

    def _grep(self, args, stdin_lines):
        flags = [a for a in args if a.startswith("-") and len(a) > 1]
        pos = [a for a in args if not (a.startswith("-") and len(a) > 1)]
        if not pos:
            return [], ["grep: missing pattern"]
        pattern = pos[0]
        files = pos[1:]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["grep: No such file or directory"]
        rx = re.compile(pattern if "-E" in flags else re.escape(pattern),
                        re.IGNORECASE if "-i" in flags else 0)
        show_num = "-n" in flags
        out = []
        for idx, line in enumerate(lines, 1):
            if rx.search(line):
                out.append(f"{idx}:{line}" if show_num else line)
        return out, []

    def _sed(self, args, stdin_lines):
        """Stream editor: s/old/new/[g] substitutions and -n 'N[,M]p' line prints."""
        script = None
        files = []
        print_only = False
        i = 0
        while i < len(args):
            a = args[i]
            if a == "-n":
                print_only = True; i += 1
            elif a.startswith("-"):
                i += 1
            elif script is None:
                script = a; i += 1
            else:
                files.append(a); i += 1
        if script is None:
            return [], ["sed: missing script"]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["sed: No such file or directory"]
        # s/old/new/g  (g = replace every match on the line, not just the first)
        m = re.match(r"s/([^/]*)/([^/]*)/(g?)", script)
        if m:
            old, new, g = m.group(1), m.group(2), m.group(3)
            out = []
            for ln in lines:
                out.append(ln.replace(old, new) if g else ln.replace(old, new, 1))
            return out, []
        # -n 'Np' or -n 'N,Mp'  (print only these line numbers)
        m = re.match(r"(\d+)(?:,(\d+))?p", script)
        if m and print_only:
            lo = int(m.group(1))
            hi = int(m.group(2)) if m.group(2) else lo
            return [ln for idx, ln in enumerate(lines, 1) if lo <= idx <= hi], []
        return [], [f"sed: can't understand '{script}'"]

    def _awk(self, args, stdin_lines):
        """Column printer: awk '{print $N}' or '{print $NF}' (last field), with
        an optional -F delimiter."""
        delim = None
        files = []
        prog = None
        i = 0
        while i < len(args):
            a = args[i]
            if a.startswith("-F") and len(a) > 2:
                delim = a[2:]; i += 1
            elif a == "-F" and i + 1 < len(args):
                delim = args[i + 1]; i += 2
            elif a.startswith("{") and a.endswith("}"):
                prog = a; i += 1
            elif a.startswith("-"):
                i += 1
            else:
                files.append(a); i += 1
        if prog is None:
            return [], ["awk: missing program"]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["awk: No such file or directory"]
        m = re.search(r"\{\s*print\s+\$(\w+)\s*\}", prog)
        if not m:
            return [], [f"awk: can't understand '{prog}'"]
        field = m.group(1)
        out = []
        for ln in lines:
            parts = ln.split(delim) if delim else ln.split()
            if field == "NF":
                out.append(parts[-1] if parts else "")
            else:
                idx = int(field) - 1
                out.append(parts[idx] if idx < len(parts) else "")
        return out, []

    def _find(self, args):
        """find [path] [-name '*.py'] [-type f|d] — search the tree recursively."""
        root = "."
        names = []
        ftype = None
        i = 0
        while i < len(args):
            a = args[i]
            if a == "-name" and i + 1 < len(args):
                names.append(args[i + 1]); i += 2
            elif a == "-type" and i + 1 < len(args):
                ftype = args[i + 1]; i += 2
            elif a.startswith("-"):
                i += 1
            else:
                root = a; i += 1
        base = self._resolve(root).rstrip("/")
        out = []
        for d in sorted(self.dirs):
            if d != base and d.startswith(base + "/"):
                rel = d[len(base) + 1:]
                if ftype in (None, "d") and self._find_match(rel, names):
                    out.append(rel + "/")
        for f in sorted(self.files):
            if f.startswith(base + "/") or f == base:
                rel = f[len(base) + 1:] if f.startswith(base + "/") else f.split("/")[-1]
                if ftype in (None, "f") and self._find_match(rel, names):
                    out.append(rel)
        return out, []

    def _find_match(self, name, patterns):
        if not patterns:
            return True
        return any(re.fullmatch(p.replace("*", ".*"), name) for p in patterns)

    def _tar(self, args):
        """tar -czf out.tgz a b  (create)  -tzf (list)  -xzf (extract)."""
        if not args or not args[0].startswith("-"):
            return [], ["tar: missing operation"]
        flags = args[0]
        rest = args[1:]
        fname = None
        if "f" in flags:
            if not rest:
                return [], ["tar: missing archive name"]
            fname = rest[0]; rest = rest[1:]
        else:
            return [], ["tar: need the f flag with an archive name"]
        if "c" in flags:
            entries = {}
            for a in rest:
                p = self._resolve(a)
                if p in self.files:
                    entries[a] = self.files[p]
                elif p in self.dirs:
                    entries[a.rstrip("/") + "/"] = "<dir>"
                else:
                    return [], [f"tar: {a}: Cannot stat: No such file or directory"]
            self.archives[fname] = entries
            self.latest = fname
            return [], []   # tar -c is quiet on success, like the real thing
        if "t" in flags:
            entries = self.archives.get(fname)
            if entries is None:
                return [], [f"tar: {fname}: Cannot open: No such file or directory"]
            return list(entries.keys()), []
        if "x" in flags:
            entries = self.archives.get(fname)
            if entries is None:
                return [], [f"tar: {fname}: Cannot open: No such file or directory"]
            for name, content in entries.items():
                p = self._resolve(name.rstrip("/"))
                if content == "<dir>":
                    self.dirs.add(p)
                else:
                    self.files[p] = content
            return list(entries.keys()), []
        return [], [f"tar: unsupported flags '{flags}'"]

    def _export(self, args):
        out = []
        for a in args:
            if "=" in a:
                k, v = a.split("=", 1)
                self.env[k] = v
            else:
                out.append(f"export: {a}: not a valid identifier")
        return out, []

    def _python(self, args):
        if not args:
            return [], ["python3: no file given"]
        p = self._resolve(args[0])
        if p not in self.files:
            return [], [f"python3: can't open file '{args[0]}': No such file or directory"]
        stdout, stderr = run_lesson_code(self.files[p])
        lines = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        elines = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return lines, elines

    def _run_executable(self, cmd):
        p = self._resolve(cmd)
        if p not in self.files:
            return [], [f"bash: {cmd}: No such file or directory"]
        if p not in self.executable:
            return [], [f"bash: {cmd}: Permission denied"]
        stdout, stderr = run_lesson_code(self.files[p])
        lines = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        elines = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return lines, elines

    def _mv(self, args):
        if len(args) != 2:
            return [], ["mv: missing file operand"]
        src, dst = self._resolve(args[0]), self._resolve(args[1])
        if src not in self.files and src not in self.dirs:
            return [], [f"mv: cannot stat '{args[0]}': No such file or directory"]
        if src in self.files:
            self.files[dst] = self.files.pop(src)
            if src in self.executable:
                self.executable.discard(src)
        else:
            base = src.rstrip("/") + "/"
            self.dirs = {d for d in self.dirs if not (d == src or d.startswith(base))}
            self.dirs.add(dst)
            remap = {}
            for f, c in self.files.items():
                if f.startswith(base):
                    remap[dst + "/" + f[len(base):]] = c
                else:
                    remap[f] = c
            self.files = remap
        self.latest = dst
        return [], []

    def _cp(self, args):
        if len(args) != 2:
            return [], ["cp: missing file operand"]
        src, dst = self._resolve(args[0]), self._resolve(args[1])
        if src not in self.files:
            return [], [f"cp: cannot stat '{args[0]}': No such file or directory"]
        self.files[dst] = self.files[src]
        self.latest = dst
        return [], []

    def _rm(self, args):
        recursive = any(a in ("-r", "-rf", "-fr") for a in args)
        targets = [a for a in args if not a.startswith("-")]
        if not targets:
            return [], ["rm: missing operand"]
        out = []
        for a in targets:
            p = self._resolve(a)
            if p in self.dirs:
                if recursive:
                    base = p.rstrip("/") + "/"
                    self.dirs = {d for d in self.dirs if not (d == p or d.startswith(base))}
                    self.files = {f: c for f, c in self.files.items() if not f.startswith(base)}
                    self.executable = {f for f in self.executable if not f.startswith(base)}
                else:
                    out.append(f"rm: cannot remove '{a}': Is a directory")
            elif p in self.files:
                del self.files[p]
                self.executable.discard(p)
            else:
                out.append(f"rm: cannot remove '{a}': No such file or directory")
        return out, []

    def _chmod(self, args):
        if not args:
            return [], ["chmod: missing operand"]
        mode = args[0]
        targets = self._expand(args[1:])
        if "+x" in mode or "u+x" in mode or "a+x" in mode:
            for t in targets:
                p = self._resolve(t)
                if p in self.files:
                    self.executable.add(p)
                    self.latest = p
            return [], []
        if "-x" in mode or "u-x" in mode or "a-x" in mode:
            for t in targets:
                p = self._resolve(t)
                if p in self.files:
                    self.executable.discard(p)
                    self.latest = p
            return [], []
        if mode.isdigit() and len(mode) <= 4:
            # numeric octal mode (e.g. 755, 644): any execute bit -> runnable
            make_x = bool(int(mode, 8) & 0o111)
            for t in targets:
                p = self._resolve(t)
                if p in self.files:
                    if make_x:
                        self.executable.add(p)
                    else:
                        self.executable.discard(p)
                    self.latest = p
            return [], []
        return [], [f"chmod: invalid mode: '{mode}'"]

    def _ps(self, args):
        out = ["  PID TTY      TIME CMD"]
        for pid in sorted(self.processes):
            out.append(f"{pid:>5} pts/0    0:00 {self.processes[pid]}")
        return out, []

    def _kill(self, args):
        if not args:
            return [], ["kill: usage: kill <pid>"]
        errs = []
        for a in args:
            if not a.isdigit():
                errs.append(f"bash: kill: {a}: arguments must be process or job IDs")
            elif int(a) in self.processes:
                del self.processes[int(a)]
            else:
                errs.append(f"bash: kill: ({a}) - No such process")
        return [], errs

    def _curl(self, args):
        """Simulated HTTP client (offline): localhost URLs return a running app's
        response; any other URL returns a canned page. `-o file` saves the
        download (a .py URL gets a runnable bootstrap script). Teaches the
        browser -> localhost:port loop and cloud-bootstrap download without a
        real network."""
        if "-o" in args or "--output" in args:
            flag = "-o" if "-o" in args else "--output"
            i = args.index(flag)
            if i + 1 >= len(args):
                return [], ["curl: option requires an argument -- 'o'"]
            fname = args[i + 1]
            url = next((a for a in args if not a.startswith("-") and a != fname), "")
            p = self._resolve(fname)
            if fname.endswith(".py"):
                content = ("print('bootstrap complete: 3 packages installed, '\n"
                           "      'web service configured')\n")
            elif fname.endswith(".html"):
                content = f"<!doctype html><title>{url or 'app'}</title>\n<h1>hello</h1>\n"
            else:
                content = f"# fetched from {url or 'remote'}\n"
            self.files[p] = content
            return [f"  % Total    % Received % Xferd  Average Speed   Time    Time     Time  Current",
                    f"                                 Dload  Upload   Total   Spent    Left  Speed",
                    f"100   512  100   512    0     0    512      0  0:00:01 --:--:--  0:00:01  1024",
                    f"Saved to '{fname}'"], []
        url = next((a for a in args if not a.startswith("-")), "")
        if not url:
            return [], ["curl: try 'curl <url>'"]
        if "localhost" in url or "127.0.0.1" in url:
            return ["HTTP/1.1 200 OK", "Content-Type: text/html", "",
                    "<h1>hello</h1>", "<p>your app is running</p>"], []
        return [f"HTTP/1.1 200 OK", f"Content-Type: text/html", "",
                f"<!doctype html><title>{url}</title>"], []

    # -- services / ssh (Linux-internals drills) ----------------------------- #
    def _systemctl(self, args):
        """A tiny systemd: start/stop/restart/status/enable/disable a fake
        service. `systemctl` alone lists them. Teaches the init layer without a
        real init system."""
        if not args:
            return [], [f"systemctl: try 'systemctl status', or "
                        "start/stop/restart/enable/disable <service>"]
        action = args[0]
        names = [a for a in args[1:] if not a.startswith("-")]
        if action in ("list-units", "list", "status") and not names:
            out = ["UNIT                 LOAD   ACTIVE   SUB"]
            for n, s in sorted(self.services.items()):
                out.append(f"{n}.service  loaded  "
                           f"{s['state']:>8}  {'enabled' if s['enabled'] else 'disabled'}")
            return out, []
        if not names:
            return [], [f"systemctl {action}: missing unit name "
                        "(try 'systemctl {action} web')"]
        out = []
        for n in names:
            base = n[:-8] if n.endswith(".service") else n
            svc = self.services.get(base)
            if svc is None:
                out.append(f"Failed to {action} {n}: Unit not found.")
                continue
            if action == "start":
                svc["state"] = "running"
                out.append(f"Started {base}.service.")
            elif action == "stop":
                svc["state"] = "stopped"
                out.append(f"Stopped {base}.service.")
            elif action == "restart":
                svc["state"] = "running"
                out.append(f"Restarted {base}.service.")
            elif action == "enable":
                svc["enabled"] = True
                out.append(f"Created symlink — {base}.service now starts at boot.")
            elif action == "disable":
                svc["enabled"] = False
                out.append(f"Removed symlink — {base}.service no longer starts at boot.")
            elif action == "status":
                run = "active (running)" if svc["state"] == "running" else "inactive (dead)"
                out.append(f"● {base}.service")
                out.append(f"   Active: {run}")
                out.append(f"   Enabled: {'yes' if svc['enabled'] else 'no'}")
            else:
                return [], [f"systemctl: unknown action '{action}'"]
        return out, []

    def _journalctl(self, args):
        """`journalctl -u <service>` prints a service's fake logs; bare
        `journalctl` prints them all."""
        name = None
        for i, a in enumerate(args):
            if a == "-u" and i + 1 < len(args):
                name = args[i + 1].rstrip(".service")
            elif a.startswith("-u"):
                name = a[2:].rstrip(".service")
        if name and name in self.services:
            return [f"Sep 07 09:00:01 host {l}" for l in self.services[name]["logs"]], []
        if name:
            return [f"-- No entries -- (no journal for '{name}')"], []
        out = []
        for n, s in sorted(self.services.items()):
            for l in s["logs"]:
                out.append(f"Sep 07 09:00:01 host {n}: {l}")
        return out, []

    def _ssh(self, args):
        """`ssh user@host` — a fake remote login. Changes the prompt to the
        remote host and drops you in a fresh home dir; `exit` returns."""
        if not args:
            return [], ["usage: ssh user@host"]
        target = args[0]
        if "@" not in target:
            return [], [f"ssh: Could not resolve hostname '{target}'"]
        user, host = target.split("@", 1)
        self.ssh_host = target
        self._local_cwd = self.cwd
        self.cwd = f"/srv/{user}"
        self.dirs.add(self.cwd)
        return [f"Welcome to {host}. Type `exit` to log out."], []

    def _exit_ssh(self, args):
        """`exit` while ssh'd returns to the local shell; otherwise a no-op."""
        if self.ssh_host is None:
            return [], []
        self.ssh_host = None
        if self._local_cwd:
            self.cwd = self._local_cwd
            self._local_cwd = None
        return ["Connection closed."], []

    def _ssh_keygen(self, args):
        """`ssh-keygen` — generate a (simulated) RSA keypair into ~/.ssh/. No
        crypto: it writes placeholder key material, enough for the secure-login
        flow to work deterministically (ssh-copy-id reads the .pub)."""
        sshdir = self.home + "/.ssh"
        self.dirs.add(sshdir)
        priv = ("-----BEGIN OPENSSH PRIVATE KEY-----\n"
                "b3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAABlwAAAAdzc2gtcn\n"
                "NhAAAAAwEAAQAAAQEAyA9k7hHq3x9vK1mQwVnL8tR2oP5cS6eB4gYx0jZfHw==\n"
                "-----END OPENSSH PRIVATE KEY-----\n")
        pub = ("ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQDIkjfHw== you@box")
        self.files[sshdir + "/id_rsa"] = priv
        self.files[sshdir + "/id_rsa.pub"] = pub
        return [f"Generating public/private rsa key pair.",
                f"Your identification has been saved in {sshdir}/id_rsa",
                f"Your public key has been saved in {sshdir}/id_rsa.pub",
                f"The key fingerprint is:",
                f"SHA256:AbCdEfGhIjKlMnOpQrStUvWxYz0123456789 you@box",
                f"The key's randomart image is:",
                f"+---[RSA 3072]----+",
                f"|   .o++          |",
                f"|  .oo+=          |",
                f"| ...oo+o         |",
                f"|  oo.++o         |",
                f"| o..+=.oS        |",
                f"|...o+=o          |",
                f"| o.++.           |",
                f"|..+o o           |",
                f"+----[SHA256]-----+"], []

    def _ssh_copy_id(self, args):
        """`ssh-copy-id user@host` — copy the local pubkey to the remote's
        authorized_keys (simulated). Requires ssh-keygen first."""
        if not args:
            return [], ["usage: ssh-copy-id user@host"]
        target = args[0]
        if "@" not in target:
            return [], [f"ssh-copy-id: Could not resolve hostname '{target}'"]
        user = target.split("@", 1)[0]
        sshdir = self.home + "/.ssh"
        pub = self.files.get(sshdir + "/id_rsa.pub")
        if not pub:
            return [], ["ssh-copy-id: No public key found — run `ssh-keygen` first"]
        remote_ssh = f"/srv/{user}/.ssh"
        self.dirs.add(remote_ssh)
        self.files[remote_ssh + "/authorized_keys"] = pub + "\n"
        return [f"/usr/bin/ssh-copy-id: INFO: attempting to log in with the new key(s)",
                f"Number of key(s) added: 1",
                f"Now try logging into the machine, with: \"ssh '{target}'\""], []


# ============================================================================
# CLOUD & DEVOPS — a simulated enterprise environment (offline, deterministic)
# ============================================================================
# The learner writes real infrastructure-as-code (Dockerfiles, Ansible
# playbooks, Terraform, boto3 scripts, CI workflows) and these simulators
# EXECUTE it against an in-memory "cloud": fake AWS (S3 + EC2/VPS), a local
# docker daemon, terraform state, an ansible inventory, git, and a CI/CD
# pipeline. Nothing touches the network — everything replays deterministically
# so lessons can be tested and resumed exactly.

# ---- tiny YAML subset parser (two-space indentation) -----------------------

def _yaml_lines(text):
    """Strip comments/blank lines; return (indent, content) pairs."""
    out = []
    for raw in text.splitlines():
        line = raw.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        indent = len(line) - len(line.lstrip(" "))
        content = line.strip()
        # strip a trailing `# comment` (outside quotes) — naive but fits the subset
        i = content.find("#")
        if i > 0 and content[i - 1] == " ":
            content = content[:i].rstrip()
        if not content:
            continue
        out.append((indent, content))
    return out


def _yaml_scalar(s):
    s = s.strip()
    if s in ("", "null", "~", "None"):
        return None
    if s.lower() in ("yes", "true", "on"):
        return True
    if s.lower() in ("no", "false", "off"):
        return False
    if len(s) >= 2 and s[0] == s[-1] and s[0] in ("'", '"'):
        return s[1:-1]
    if s.startswith("[") and s.endswith("]"):
        inner = s[1:-1].strip()
        if not inner:
            return []
        return [x.strip().strip("'\"") for x in inner.split(",")]
    if re.fullmatch(r"-?\d+", s):
        return int(s)
    return s


def yaml_parse(text):
    """Parse the tiny YAML subset we teach into Python lists/dicts."""
    lines = _yaml_lines(text)
    if not lines:
        return None
    root_is_list = lines[0][1].startswith("- ")
    root = [] if root_is_list else {}
    stack = [(-1, root, None)]  # (indent, container, key)

    def down_to(indent):
        while stack and stack[-1][0] >= indent:
            stack.pop()

    i, n = 0, len(lines)
    while i < n:
        indent, content = lines[i]
        if content.startswith("- "):
            down_to(indent)
            parent = stack[-1][1]
            if not isinstance(parent, list):
                parent = root
            rest = content[2:].strip()
            if ":" in rest and rest.split(":", 1)[0].strip():
                k, _, v = rest.partition(":")
                item = {k.strip(): _yaml_scalar(v) if v.strip() else None}
                parent.append(item)
                stack.append((indent, item, None))
            else:
                parent.append(_yaml_scalar(rest))
            i += 1
            continue
        if ":" in content:
            k, _, v = content.partition(":")
            k = k.strip()
            down_to(indent)
            parent = stack[-1][1]
            if not isinstance(parent, dict):
                parent = root
            if v.strip():
                parent[k] = _yaml_scalar(v)
            else:
                nxt = i + 1
                if nxt < n and lines[nxt][0] > indent:
                    child = [] if lines[nxt][1].startswith("- ") else {}
                    parent[k] = child
                    stack.append((indent, child, None))
                else:
                    parent[k] = None
            i += 1
            continue
        i += 1
    return root


def ini_parse(text):
    """Parse a tiny INI inventory (`[group]` then one host per line)."""
    groups = {}
    cur = None
    for raw in text.splitlines():
        s = raw.strip()
        if not s or s.startswith("#") or s.startswith(";"):
            continue
        if s.startswith("[") and s.endswith("]"):
            cur = s[1:-1]
            groups.setdefault(cur, [])
        elif cur is not None:
            groups[cur].append(s)
    return groups


def _hcl_val(v):
    v = v.strip()
    if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
        return v[1:-1]
    if v.lower() in ("true", "false"):
        return v.lower() == "true"
    if re.fullmatch(r"\d+", v):
        return int(v)
    if v.startswith("[") and v.endswith("]"):
        return [x.strip().strip('"') for x in v[1:-1].split(",") if x.strip()]
    return v


def hcl_parse(text):
    """Parse the tiny HCL subset (blocks + `key = value` attrs)."""
    blocks, stack = [], []
    for raw in text.splitlines():
        s = raw.strip()
        if not s or s.startswith("#") or s.startswith("//"):
            continue
        if s.endswith("{") and "=" not in s:
            header = s[:-1].strip()
            parts = header.split()
            block = {"type": parts[0], "labels": [p.strip('"') for p in parts[1:]],
                     "attrs": {}, "blocks": []}
            if stack:
                stack[-1]["blocks"].append(block)
            else:
                blocks.append(block)
            stack.append(block)
        elif s == "}":
            if stack:
                stack.pop()
        elif "=" in s and stack:
            k, _, v = s.partition("=")
            stack[-1]["attrs"][k.strip()] = _hcl_val(v)
    return blocks


# ---- git (simulated) --------------------------------------------------------

class GitRepo:
    def __init__(self, fs):
        self.fs = fs
        self.inited = False
        self.branch = "main"
        self.commits = []              # list of {hash, msg, branch}
        self.staged = {}               # path -> content snapshot at `git add`
        self.committed = {}            # path -> content snapshot at last commit
        self.n = 0

    def _hash(self, msg):
        self.n += 1
        return "a%06d" % self.n

    def _status_lines(self):
        out = []
        if not self.inited:
            return ["fatal: not a git repository (or any of the parent directories)"]
        if self.branch:
            out.append(f"On branch {self.branch}")
        changed = [p for p, c in self.fs.files.items() if self.committed.get(p) != c]
        # untracked = in fs but never committed
        untracked = [p for p in self.fs.files if p not in self.committed]
        staged_names = sorted(self.staged.keys())
        if staged_names:
            out.append("Changes to be committed:")
            for p in staged_names:
                out.append(f"  new file:   {p}")
        if changed:
            out.append("Changes not staged for commit:")
            for p in sorted(changed):
                out.append(f"  modified:   {p}")
        if untracked:
            out.append("Untracked files:")
            for p in sorted(untracked):
                out.append(f"\t{p}")
        if not staged_names and not changed and not untracked:
            out.append("nothing to commit, working tree clean")
        return out

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: git <command>"]
        cmd = parts[0]
        args = parts[1:]
        if cmd == "init":
            self.inited = True
            return [f"Initialized empty Git repository"], []
        if not self.inited:
            return [], ["fatal: not a git repository"]
        if cmd == "add":
            if not args:
                return [], ["Nothing specified, nothing added."]
            added = []
            for a in args:
                if a == "." or a == "-A":
                    for p, c in self.fs.files.items():
                        self.staged[p] = c
                        added.append(p)
                else:
                    p = self.fs._resolve(a)
                    if p in self.fs.files:
                        self.staged[p] = self.fs.files[p]
                        added.append(p)
                    else:
                        return [], [f"fatal: pathspec '{a}' did not match any files"]
            return (["staged: " + ", ".join(added)] if added else []), []
        if cmd == "commit":
            msg = ""
            m = re.search(r'-m\s+["\']([^"\']*)["\']', rest)
            if m:
                msg = m.group(1)
            else:
                m = re.search(r'-m\s+(\S+)', rest)
                if m:
                    msg = m.group(1)
            if not self.staged:
                return [], ["nothing to commit, working tree clean"]
            h = self._hash(msg)
            self.committed.update(self.staged)
            self.commits.append({"hash": h, "msg": msg, "branch": self.branch})
            self.staged = {}
            out = [f"[{self.branch} {h}] {msg}", f" {len(self.commits)} file changed" if len(self.commits) == 1 else f" {len(self.commits)} files changed"]
            # trigger the CI/CD pipeline on every commit (teaches the loop)
            return out, []
        if cmd == "log":
            if not self.commits:
                return [], []
            out = []
            for c in reversed(self.commits):
                out.append(f"commit {c['hash']} ({c['branch']})")
                if c["msg"]:
                    out.append(f"    {c['msg']}")
            return out, []
        if cmd == "status":
            return self._status_lines(), []
        if cmd == "branch":
            if args and not args[0].startswith("-"):
                return [f"branch '{args[0]}' created"], []
            return [f"* {self.branch}"], []
        if cmd in ("checkout", "switch"):
            if args and args[0] == "-b":
                self.branch = args[1] if len(args) > 1 else "feature"
            elif args:
                self.branch = args[0]
            return [f"Switched to branch '{self.branch}'"], []
        if cmd == "merge":
            if args:
                return [f"Merge made by the 'recursive' strategy"], []
            return [], ["fatal: no branch specified"]
        if cmd == "diff":
            changed = [p for p, c in self.fs.files.items() if self.committed.get(p) != c]
            if not changed:
                return [], []
            return ["diff --git a/" + p for p in sorted(changed)], []
        return [], [f"git: '{cmd}' is not a git command"]


# ---- docker (simulated) ------------------------------------------------------

class K8sEnv:
    """A tiny offline Kubernetes: deployments, pods, services, rollouts.
    `run(rest)` behaves like kubectl — desired state, self-healing, rolling
    updates — so the lessons read like a real cluster."""

    def __init__(self, fs):
        self.fs = fs
        self.deployments = {}   # name -> {image, replicas, ready, rev}
        self.pods = {}          # name -> {owner|None, image, status, restarts}
        self.services = {}      # name -> {type, port}
        self.healed = 0         # pods the controller replaced after deletion
        self.next = 1
        self.roles = {}          # name -> {verbs: set, resources: set}
        self.rolebindings = {}   # name -> {role, user}
        self.networkpolicies = {}  # name -> {policy_type}

    def _sync(self, name):
        """Realize the desired state: pods match the deployment's replicas.
        This is the 'self-healing' magic — delete a pod, it comes back."""
        d = self.deployments[name]
        d["ready"] = d["replicas"]
        self.pods = {k: v for k, v in self.pods.items()
                     if v.get("owner") != name}
        for i in range(d["replicas"]):
            pn = f"{name}-{i:02d}"
            self.pods[pn] = {"owner": name, "image": d["image"],
                             "status": "Running", "restarts": 0}

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["kubectl: missing command"]
        cmd = parts[0]
        if cmd == "get":
            return self._get(parts[1:])
        if cmd == "create" and parts[1:2] == ["deployment"]:
            name = parts[2]
            img = "nginx"
            if "--image" in parts:
                img = parts[parts.index("--image") + 1].split("=")[-1]
            self.deployments[name] = {"image": img, "replicas": 1,
                                      "ready": 1, "rev": 1}
            self._sync(name)
            return [f"deployment.apps/{name} created"], []
        if cmd == "run":
            name = parts[1]
            img = "nginx"
            if "--image" in parts:
                img = parts[parts.index("--image") + 1].split("=")[-1]
            self.pods[name] = {"owner": None, "image": img,
                               "status": "Running", "restarts": 0}
            return [f"pod/{name} created"], []
        if cmd == "scale":
            # kubectl scale deployment web --replicas=3
            # kubectl scale deployment/web --replicas=3
            if "/" in parts[1]:
                name = parts[1].split("/")[-1]
            elif parts[1].startswith("deploy"):
                name = parts[2] if len(parts) > 2 else ""
            else:
                name = parts[1].split("/")[-1]
            if name not in self.deployments:
                return [], [f'Error from server (NotFound): deployments.apps '
                            f'"{name}" not found']
            replicas = int(parts[parts.index("--replicas") + 1].split("=")[-1]) \
                if "--replicas" in parts else \
                int(next((p for p in parts if p.startswith("--replicas=")),
                         "--replicas=1").split("=")[-1])
            self.deployments[name]["replicas"] = replicas
            self._sync(name)
            return [f"deployment.apps/{name} scaled"], []
        if cmd == "expose":
            # kubectl expose deployment web --port=80 --type=LoadBalancer
            if "/" in parts[1]:
                name = parts[1].split("/")[-1]
            elif parts[1].startswith("deploy"):
                name = parts[2] if len(parts) > 2 else ""
            else:
                name = parts[1].split("/")[-1]
            port = "80"
            if "--port" in parts:
                port = parts[parts.index("--port") + 1].split("=")[-1]
            elif any(p.startswith("--port=") for p in parts):
                port = next(p for p in parts if p.startswith("--port=")).split("=")[-1]
            stype = "ClusterIP"
            if "--type" in parts:
                stype = parts[parts.index("--type") + 1].split("=")[-1]
            elif any(p.startswith("--type=") for p in parts):
                stype = next(p for p in parts if p.startswith("--type=")).split("=")[-1]
            self.services[name] = {"type": stype, "port": port}
            return [f"service/{name} exposed"], []
        if cmd == "set":
            # kubectl set image deployment web app=img:v2
            # kubectl set image deployment/web app=img:v2
            if "deployment" in parts:
                di = parts.index("deployment")
                if "/" in parts[di]:
                    name = parts[di].split("/")[-1]
                else:
                    name = parts[di + 1] if di + 1 < len(parts) else ""
            else:
                name = parts[2].split("/")[-1]
            img = parts[-1].split("=")[-1]
            d = self.deployments.get(name)
            if not d:
                return [], [f'Error from server (NotFound): deployments.apps '
                            f'"{name}" not found']
            d["image"] = img
            d["rev"] += 1
            self._sync(name)
            return [f"deployment.apps/{name} image updated"], []
        if cmd == "rollout":
            return self._rollout(parts[1:])
        if cmd == "describe":
            return self._describe(parts[1:])
        if cmd == "logs":
            return self._logs(parts[1:])
        if cmd == "delete":
            return self._delete(parts[1:])
        if cmd == "apply":
            return self._apply(parts[1:])
        if cmd == "create" and parts[1:2] == ["role"]:
            name = parts[2]
            v = self._kw(parts, "--verb")
            r = self._kw(parts, "--resource")
            self.roles[name] = {"verbs": set(v.split(",")) if v else set(),
                                "resources": set(r.split(",")) if r else set()}
            return [f"role.rbac.authorization.k8s.io/{name} created"], []
        if cmd == "create" and parts[1:2] == ["rolebinding"]:
            name = parts[2]
            role = self._kw(parts, "--role") or ""
            user = self._kw(parts, "--user") or ""
            self.rolebindings[name] = {"role": role, "user": user}
            return [f"rolebinding.rbac.authorization.k8s.io/{name} created"], []
        if cmd == "auth" and parts[1:2] == ["can-i"]:
            # kubectl auth can-i get pods --as dev
            verb = parts[2] if len(parts) > 2 else ""
            resource = parts[3] if len(parts) > 3 else ""
            user = self._kw(parts, "--as") or ""
            # allowed if any binding maps user -> role with the verb+resource
            allowed = False
            for rb in self.rolebindings.values():
                if user and rb["user"] != user:
                    continue
                role = self.roles.get(rb["role"])
                if role and verb in role["verbs"] and resource in role["resources"]:
                    allowed = True
                    break
            return ([f"yes"] if allowed else [f"no - access denied"]), []
        return [], [f"kubectl: '{cmd}' is not supported in this lab"]

    def _kw(self, parts, name):
        """Extract `--name value` or `--name=value` from a token list (or None)."""
        if name in parts:
            i = parts.index(name)
            return parts[i + 1] if i + 1 < len(parts) else ""
        for p in parts:
            if p.startswith(name + "="):
                return p.split("=", 1)[1]
        return None

    def _get(self, args):
        kind = args[0] if args else "pods"
        if kind == "nodes":
            return ["NAME        STATUS   ROLES           AGE   VERSION",
                    "minikube    Ready    control-plane   3d    v1.31.0"], []
        if kind == "pods":
            if not self.pods:
                return ["No resources found in default namespace."], []
            out = ["NAME                    READY   STATUS    RESTARTS   AGE"]
            for pn in sorted(self.pods):
                p = self.pods[pn]
                out.append(f"{pn:<24} 1/1     {p['status']:<9} "
                           f"{p['restarts']}          12m")
            return out, []
        if kind in ("deployments", "deploy"):
            if not self.deployments:
                return ["No resources found in default namespace."], []
            out = ["NAME   READY   UP-TO-DATE   AVAILABLE   AGE"]
            for n in sorted(self.deployments):
                d = self.deployments[n]
                out.append(f"{n:<7} {d['ready']}/{d['replicas']}     "
                           f"{d['replicas']}            {d['ready']}          "
                           f"13m")
            return out, []
        if kind in ("services", "svc"):
            if not self.services:
                return ["No resources found in default namespace."], []
            out = ["NAME   TYPE           CLUSTER-IP   EXTERNAL-IP   "
                   "PORT(S)   AGE"]
            for n in sorted(self.services):
                s = self.services[n]
                ext = "<pending>" if s["type"] == "LoadBalancer" else "<none>"
                out.append(f"{n:<7} {s['type']:<15} 10.96.0.1    {ext:<13} "
                           f"{s['port']}/TCP   10m")
            return out, []
        if kind in ("roles", "role"):
            if not self.roles:
                return ["No resources found in default namespace."], []
            out = ["NAME   AGE"]
            for n in sorted(self.roles):
                out.append(f"{n}   5m")
            return out, []
        if kind in ("rolebindings", "rolebinding"):
            if not self.rolebindings:
                return ["No resources found in default namespace."], []
            out = ["NAME   ROLE   USERS"]
            for n in sorted(self.rolebindings):
                rb = self.rolebindings[n]
                out.append(f"{n}   {rb['role']}   {rb['user']}")
            return out, []
        if kind in ("networkpolicies", "networkpolicy", "netpol"):
            if not self.networkpolicies:
                return ["No resources found in default namespace."], []
            out = ["NAME   POD-SELECTOR"]
            for n in sorted(self.networkpolicies):
                out.append(f"{n}   <all>")
            return out, []
        return [], [f'error: the server doesn\'t have a resource type '
                    f'"{kind}"']

    def _rollout(self, args):
        if not args:
            return [], ["kubectl rollout: use status | undo | history"]
        kind = args[0]
        # kubectl rollout status deployment web
        # kubectl rollout status deployment/web
        if len(args) > 1 and "/" in args[1]:
            name = args[1].split("/")[-1]
        else:
            name = args[2] if len(args) > 2 else ""
        d = self.deployments.get(name)
        if not d:
            return [], [f'Error from server (NotFound): deployments.apps '
                        f'"{name}" not found']
        if kind == "status":
            return [f'Waiting for deployment "{name}" rollout to finish: '
                    f'{d["replicas"]} out of {d["replicas"]} new replicas '
                    f'have been updated...',
                    f'deployment "{name}" successfully rolled out'], []
        if kind == "undo":
            d["rev"] = max(1, d["rev"] - 1)
            d["ready"] = d["replicas"]
            return [f"deployment.apps/{name} rolled back"], []
        if kind == "history":
            out = [f"deployment.apps/{name}", "REVISION  CHANGE-CAUSE"]
            for r in range(d["rev"], 0, -1):
                out.append(f"{r}         <none>")
            return out, []
        return [], ["kubectl rollout: use status | undo | history"]

    def _describe(self, args):
        if len(args) < 2:
            return [], ["kubectl describe: provide deployment/NAME"]
        name = args[1].split("/")[-1]
        d = self.deployments.get(name)
        if not d:
            return [], [f'Error from server (NotFound): deployments.apps '
                        f'"{name}" not found']
        return [f"Name:                   {name}",
                "Namespace:              default",
                f"Replicas:               {d['replicas']} desired | "
                f"{d['ready']} updated | {d['ready']} available",
                f"Image:                  {d['image']}",
                f"Revision:               {d['rev']}",
                "Conditions:",
                "  Type           Status  Reason",
                "  ----           ------  ------",
                "  Available      True    MinimumReplicasAvailable"], []

    def _logs(self, args):
        name = args[0].split("/")[-1] if args else ""
        d = self.deployments.get(name)
        img = d["image"] if d else "app:latest"
        if "v2" in img:
            return ["[2026-09-09 18:00:01] serving v2 — new feature live",
                    "[2026-09-09 18:00:02] GET / 200 12ms",
                    "[2026-09-09 18:00:03] GET /health 200 2ms"], []
        return ["[2026-09-09 17:59:58] serving v1",
                "[2026-09-09 17:59:59] GET / 200 15ms",
                "[2026-09-09 18:00:00] GET /health 200 2ms"], []

    def _delete(self, args):
        if len(args) < 2:
            return [], ["kubectl delete: provide TYPE NAME"]
        kind = args[0]
        name = args[1].split("/")[-1]
        if kind.startswith("deploy"):
            if name in self.deployments:
                del self.deployments[name]
                self.pods = {k: v for k, v in self.pods.items()
                             if v.get("owner") != name}
                return [f'deployment.apps "{name}" deleted'], []
        elif kind.startswith("service"):
            if name in self.services:
                del self.services[name]
                return [f'service "{name}" deleted'], []
        elif kind.startswith("pod"):
            if name in self.pods:
                owner = self.pods[name].get("owner")
                del self.pods[name]
                if owner:
                    self.healed += 1    # the control loop replaces it
                    self._sync(owner)   # self-healing: the replica returns
                return [f'pod "{name}" deleted'], []
        return [], [f'Error from server (NotFound): {kind} "{name}" not found']

    def _apply(self, args):
        fname = None
        if "-f" in args:
            fname = args[args.index("-f") + 1]
        if not fname:
            return [], ["kubectl apply: provide -f FILE"]
        p = self.fs._resolve(fname)
        content = self.fs.files.get(p)
        if not content:
            return [], [f'error: the path "{fname}" does not exist']
        kind = re.search(r"^kind:\s*(\w+)", content, re.M)
        name = re.search(r"^\s{2}name:\s*(\S+)", content, re.M)
        if not kind or not name:
            return [], ["error: unable to parse the manifest"]
        kind, name = kind.group(1), name.group(1)
        if kind == "Deployment":
            img = re.search(r"image:\s*(\S+)", content)
            reps = re.search(r"replicas:\s*(\d+)", content)
            self.deployments[name] = {
                "image": img.group(1) if img else "nginx",
                "replicas": int(reps.group(1)) if reps else 1,
                "ready": int(reps.group(1)) if reps else 1, "rev": 1}
            self._sync(name)
            return [f"deployment.apps/{name} created"], []
        if kind == "Service":
            port = re.search(r"port:\s*(\d+)", content)
            stype = re.search(r"type:\s*(\w+)", content)
            self.services[name] = {"type": stype.group(1) if stype
                                   else "ClusterIP",
                                   "port": port.group(1) if port else "80"}
            return [f"service/{name} created"], []
        if kind == "Role":
            verbs = set(re.findall(r'-\s*"(get|list|create|delete|update|watch|patch)"', content))
            resources = set(re.findall(r'resources:\s*\[([^\]]*)\]', content))
            self.roles[name] = {"verbs": verbs, "resources": resources}
            return [f"role.rbac.authorization.k8s.io/{name} created"], []
        if kind == "RoleBinding":
            role = re.search(r"name:\s*(\S+)", content)
            self.rolebindings[name] = {"role": role.group(1) if role else "", "user": ""}
            return [f"rolebinding.rbac.authorization.k8s.io/{name} created"], []
        if kind == "NetworkPolicy":
            self.networkpolicies[name] = {"policy_type": "Ingress"}
            return [f"networkpolicy.networking.k8s.io/{name} created"], []
        return [], [f'error: unsupported kind "{kind}" in this lab']


class DockerEnv:
    def __init__(self, fs):
        self.fs = fs
        self.images = {}       # name -> {"id": str, "exposed": [ports]}
        self.containers = {}   # name -> {"image", "running", "ports"}
        self.next = 1

    def _dockerfile(self):
        p = self.fs._resolve("Dockerfile")
        return self.fs.files.get(p, "")

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["docker: missing command"]
        cmd = parts[0]
        if cmd == "build":
            tag = None
            if "-t" in parts:
                ti = parts.index("-t")
                if ti + 1 < len(parts):
                    tag = parts[ti + 1]
            tag = tag or "app:latest"
            df = self._dockerfile()
            if not df:
                return [], ["unable to prepare context: unable to evaluate symlinks in Dockerfile path: lstat Dockerfile: no such file or directory"]
            lines = []
            for ln in df.splitlines():
                s = ln.strip()
                if s.upper().startswith("FROM "):
                    lines.append(f" ---> pulling {s[5:].strip()}")
            lines.append(" ---> build complete")
            self.images[tag] = {"id": "img%03d" % self.next, "exposed": []}
            self.next += 1
            return ["Sending build context to Docker daemon",
                    "Step 1/1 : FROM python:3.11-slim"] + lines + [f"Successfully tagged {tag}"], []
        if cmd == "images":
            if not self.images:
                return ["REPOSITORY  TAG  IMAGE ID  CREATED  SIZE"], []
            out = ["REPOSITORY  TAG  IMAGE ID  CREATED  SIZE"]
            for name, im in self.images.items():
                repo, _, tag = name.partition(":")
                out.append(f"{repo}  {tag or 'latest'}  {im['id']}  2 minutes ago  128MB")
            return out, []
        if cmd == "run":
            name, img = None, None
            ports = []
            detached = "-d" in parts
            if "--name" in parts:
                ni = parts.index("--name")
                if ni + 1 < len(parts):
                    name = parts[ni + 1]
            if "-p" in parts:
                pi = parts.index("-p")
                if pi + 1 < len(parts):
                    ports.append(parts[pi + 1])
            # last positional arg = image
            for a in parts:
                if not a.startswith("-") and a not in ("run", name, *ports):
                    img = a
            if not img:
                return [], ["docker run requires an image"]
            if img not in self.images:
                return [], [f"Unable to find image '{img}' locally: docker: Error response from daemon: pull access denied"]
            name = name or f"container{self.next}"
            cid = "c%03d" % self.next
            self.next += 1
            self.containers[name] = {"image": img, "running": True, "ports": ports, "id": cid}
            out = [cid]
            if not detached:
                # foreground run shows app output (first lines of the image's CMD)
                out += self._fake_logs(img)
            return out, []
        if cmd == "ps":
            if not self.containers:
                return ["CONTAINER ID  IMAGE  STATUS  PORTS  NAMES"], []
            out = ["CONTAINER ID  IMAGE  STATUS  PORTS  NAMES"]
            for name, c in self.containers.items():
                st = "Up 2 minutes" if c["running"] else "Exited (0)"
                out.append(f"{c['id']}  {c['image']}  {st}  {' '.join(c['ports'])}  {name}")
            return out, []
        if cmd == "stop":
            args = parts[1:]
            if not args:
                return [], ["docker stop requires a container name"]
            out, errs = [], []
            for n in args:
                if n in self.containers:
                    self.containers[n]["running"] = False
                    out.append(n)
                else:
                    errs.append(f"Error: No such container: {n}")
            return out, errs
        if cmd == "start":
            for n in parts[1:]:
                if n in self.containers:
                    self.containers[n]["running"] = True
            return parts[1:], []
        if cmd == "rm":
            args = parts[1:]
            if not args:
                return [], ["docker rm requires a container name"]
            out, errs = [], []
            for n in args:
                if n not in self.containers:
                    errs.append(f"Error: No such container: {n}")
                elif self.containers[n]["running"]:
                    errs.append(f"Error response from daemon: You cannot remove "
                                f"a running container {n}. Stop the container "
                                f"before attempting removal")
                else:
                    del self.containers[n]
                    out.append(n)
            return out, errs
        if cmd == "rmi":
            for n in parts[1:]:
                self.images.pop(n, None)
            return [], []
        if cmd == "logs":
            n = parts[1] if len(parts) > 1 else ""
            if n in self.containers:
                return self._fake_logs(self.containers[n]["image"]), []
            return [], [f"Error: No such container: {n}"]
        if cmd == "exec":
            # docker exec <name> <cmd...>
            n = parts[1] if len(parts) > 1 else ""
            if n in self.containers:
                return [f"(inside {n}) ran: {' '.join(parts[2:])}"], []
            return [], [f"Error: No such container: {n}"]
        return [], [f"docker: unknown command '{cmd}'"]

    def _fake_logs(self, img):
        return [" * Serving Flask app", " * Running on http://0.0.0.0:5000"]


# ---- AWS (simulated S3 + EC2/VPS) -------------------------------------------

class AwsEnv:
    def __init__(self, fs):
        self.fs = fs
        self.buckets = {}      # name -> {key: content}
        self.instances = {}    # id -> {"ImageId","InstanceType","State":{...}}
        self.next_inst = 1
        self.lambda_fns = {}      # name -> {"code","runtime","handler"}
        self.dynamo_tables = {}   # name -> list of native item dicts
        self.iam_users = set()    # usernames
        self.iam_roles = {}       # role -> {"policies": []}
        self.iam_policies = {}    # policy name -> arn
        self.sqs_queues = {}          # queue name -> list of {"MessageId","Body"}
        self.cloudwatch_metrics = {}  # "namespace/metric" -> list of value strings
        self.cloudwatch_alarms = {}   # alarm name -> {"metric","threshold","state"}
        self.rds_instances = {}       # identifier -> {"engine","class","status"}
        self.db_snapshots = {}        # snapshot -> {"source","engine"}
        self.elb = {}                 # lb name -> {"arn","targets":[]}
        self.cloudfront = {}          # dist id -> {"origin","domain"}
        self.apigateway = {}          # api name -> {"id","deployed"}
        self.sns_topics = {}          # topic name -> {"arn","messages":[]}
        self.asg = {}                 # asg name -> {"min","max","desired"}
        self.secrets = {}             # secret name -> {"value","arn"}
        self.budgets = {}             # budget name -> {"amount"}
        self.security_groups = {}     # sg name -> {"ingress":[(proto,port,cidr)], "egress":[]}
        self.route_tables = {}        # rtb id -> {"routes":[(dest,target)]}
        self.next_rtb = 1
        self.kms_keys = {}            # key id -> {"arn"}

    def run(self, rest):
        try:
            parts = shlex.split(rest)
        except ValueError:
            parts = rest.split()
        if not parts:
            return [], ["usage: aws <service> <command>"]
        svc = parts[0]
        if svc == "s3":
            return self._s3(parts[1:])
        if svc == "ec2":
            return self._ec2(parts[1:])
        if svc == "lambda":
            return self._lambda(parts[1:])
        if svc == "dynamodb":
            return self._dynamodb(parts[1:])
        if svc == "iam":
            return self._iam(parts[1:])
        if svc == "sqs":
            return self._sqs(parts[1:])
        if svc == "cloudwatch":
            return self._cloudwatch(parts[1:])
        if svc == "rds":
            return self._rds(parts[1:])
        if svc == "elbv2":
            return self._elb(parts[1:])
        if svc == "cloudfront":
            return self._cloudfront(parts[1:])
        if svc == "apigateway":
            return self._apigateway(parts[1:])
        if svc == "sns":
            return self._sns(parts[1:])
        if svc == "autoscaling":
            return self._autoscaling(parts[1:])
        if svc == "secretsmanager":
            return self._secretsmanager(parts[1:])
        if svc == "budgets":
            return self._budgets(parts[1:])
        if svc == "ce":
            return self._ce(parts[1:])
        if svc == "kms":
            return self._kms(parts[1:])
        if svc in ("--version", "version"):
            return ["aws-cli/2.15.0"], []
        return [], [f"aws: error: argument command: Invalid choice, valid choices: s3 | ec2 | lambda | dynamodb | iam | sqs | cloudwatch | rds | elbv2 | cloudfront | apigateway | sns | autoscaling | secretsmanager | budgets | ce"]

    def _s3(self, args):
        if not args:
            return [], ["usage: aws s3 <command>"]
        cmd = args[0]
        if cmd == "mb":
            if len(args) < 2:
                return [], ["usage: aws s3 mb <s3://bucket>"]
            name = args[1].replace("s3://", "")
            if name in self.buckets:
                return [], [f"make_bucket failed: s3://{name} An error occurred (BucketAlreadyOwnedByYou)"]
            self.buckets[name] = {}
            return [f"make_bucket: {name}"], []
        if cmd == "ls":
            if len(args) == 1:
                if not self.buckets:
                    return [], []
                return [f"2026-09-07 09:00:00 {name}" for name in sorted(self.buckets)], []
            name = args[1].replace("s3://", "")
            if name not in self.buckets:
                return [], [f"An error occurred (NoSuchBucket): {name}"]
            return [f"2026-09-07 09:00:00 {len(c):>5} {k}" for k, c in sorted(self.buckets[name].items())], []
        if cmd == "cp":
            src, dst = args[1], args[2]
            if src.startswith("s3://"):
                # download
                b, _, k = src[5:].partition("/")
                if b in self.buckets and k in self.buckets[b]:
                    self.fs.files[self.fs._resolve(dst)] = self.buckets[b][k]
                    return [f"download: s3://{b}/{k} to ./{dst}"], []
                return [], [f"fatal error: An error occurred (404) when calling the HeadObject operation"]
            # upload
            b, _, k = dst[5:].partition("/")
            p = self.fs._resolve(src)
            if b not in self.buckets:
                return [], [f"upload failed: {dst} An error occurred (NoSuchBucket)"]
            body = self.fs.files.get(p, src)
            self.buckets[b][k] = body
            return [f"upload: ./{src} to {dst}"], []
        if cmd == "rm":
            if len(args) < 2:
                return [], ["usage: aws s3 rm <s3://bucket/key>"]
            b, _, k = args[1][5:].partition("/")
            if b in self.buckets:
                self.buckets[b].pop(k, None)
            return [f"delete: s3://{b}/{k}"], []
        if cmd == "rb":
            b = args[1].replace("s3://", "")
            if b in self.buckets and self.buckets[b]:
                return [], [f"remove_bucket failed: s3://{b} An error occurred (BucketNotEmpty)"]
            self.buckets.pop(b, None)
            return [f"remove_bucket: {b}"], []
        return [], [f"aws s3: unknown command '{cmd}'"]

    def _ec2(self, args):
        if not args:
            return [], ["usage: aws ec2 <command>"]
        cmd = args[0]
        if cmd == "run-instances":
            d = dict(zip(args[1::2], args[2::2]))
            ami = d.get("--image-id", "ami-default")
            itype = d.get("--instance-type", "t3.micro")
            iid = "i-%04d" % self.next_inst
            self.next_inst += 1
            self.instances[iid] = {"ImageId": ami, "InstanceType": itype,
                                   "State": {"Name": "running"}}
            return [f"INSTANCE  {iid}  {ami}  {itype}  running"], []
        if cmd == "describe-instances":
            if not self.instances:
                return ["Reservations: []"], []
            out = []
            for iid, inst in self.instances.items():
                out.append(f"{iid}  {inst['ImageId']}  {inst['InstanceType']}  {inst['State']['Name']}")
            return out, []
        if cmd in ("terminate-instances", "stop-instances", "start-instances"):
            state = {"terminate-instances": "terminated",
                     "stop-instances": "stopped",
                     "start-instances": "running"}[cmd]
            ids = []
            if "--instance-ids" in args:
                ids = args[args.index("--instance-ids") + 1:]
            for iid in ids:
                if iid in self.instances:
                    self.instances[iid]["State"]["Name"] = state
            return [f"{iid}: {state}" for iid in ids], []
        if cmd == "create-security-group":
            d = _aws_flags(args[1:])
            name = d.get("group-name", "sg")
            if name in self.security_groups:
                return [], [f"An error occurred (InvalidGroup.Duplicate): {name}"]
            self.security_groups[name] = {"ingress": [], "egress": []}
            return [f"GroupId: sg-{name}"], []
        if cmd in ("authorize-security-group-ingress", "authorize-security-group-egress"):
            d = _aws_flags(args[1:])
            name = d.get("group-name", "")
            if name not in self.security_groups:
                return [], [f"An error occurred (InvalidGroup.NotFound): {name}"]
            key = "ingress" if cmd.endswith("ingress") else "egress"
            rule = (d.get("protocol", "tcp"),
                    d.get("port", d.get("from-port", "")),
                    d.get("cidr", ""))
            self.security_groups[name][key].append(rule)
            return [], []
        if cmd == "describe-security-groups":
            if not self.security_groups:
                return ["SecurityGroups: []"], []
            out = []
            for name, sg in sorted(self.security_groups.items()):
                out.append(f"{name}  ingress={len(sg['ingress'])}  egress={len(sg['egress'])}")
                for proto, port, cidr in sg["ingress"]:
                    out.append(f"    in  {proto} {port}  {cidr}")
                for proto, port, cidr in sg["egress"]:
                    out.append(f"    out {proto} {port}  {cidr}")
            return out, []
        if cmd == "create-route-table":
            rid = "rtb-%04d" % self.next_rtb
            self.next_rtb += 1
            self.route_tables[rid] = {"routes": []}
            return [f"RouteTableId: {rid}"], []
        if cmd == "create-route":
            d = _aws_flags(args[1:])
            rid = d.get("route-table-id", "")
            if rid not in self.route_tables:
                return [], [f"An error occurred (InvalidRouteTableID.NotFound): {rid}"]
            self.route_tables[rid]["routes"].append(
                (d.get("destination-cidr-block", ""), d.get("gateway-id", "")))
            return [], []
        if cmd == "describe-route-tables":
            if not self.route_tables:
                return ["RouteTables: []"], []
            out = []
            for rid, rt in sorted(self.route_tables.items()):
                out.append(f"{rid}  routes={len(rt['routes'])}")
                for dest, target in rt["routes"]:
                    out.append(f"    {dest} -> {target}")
            return out, []
        return [], [f"aws ec2: unknown command '{cmd}'"]

    def _lambda(self, args):
        if not args:
            return [], ["usage: aws lambda <command>"]
        cmd = args[0]
        if cmd == "create-function":
            d = _aws_flags(args[1:])
            name = d.get("function-name", "fn")
            handler = d.get("handler", "lambda_function.handler")
            runtime = d.get("runtime", "python3.11")
            code = ""
            zf = d.get("zip-file", "")
            if zf.startswith("fileb://"):
                p = self.fs._resolve(zf[8:])
                code = self.fs.files.get(p, "")
            self.lambda_fns[name] = {"code": code, "runtime": runtime, "handler": handler}
            return [f"FunctionName: {name}", f"Runtime: {runtime}", f"Handler: {handler}",
                    f"FunctionArn: arn:aws:lambda:us-east-1:123456789012:function:{name}"], []
        if cmd == "invoke":
            d = _aws_flags(args[1:])
            name = d.get("function-name", "")
            if name not in self.lambda_fns:
                return [], [f"An error occurred (ResourceNotFoundException): Function not found: {name}"]
            fn = self.lambda_fns[name]
            func = fn["handler"].split(".")[-1]
            code = fn["code"] + f"\nprint({func}({{}}, None))\n"
            stdout, stderr = run_lesson_code(code)
            out = ["Status: 200", "Execution result:"]
            if stderr.strip():
                out += ["(error)"] + stderr.strip().splitlines()
            else:
                out += stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else ["(no output)"]
            return out, []
        if cmd == "list-functions":
            if not self.lambda_fns:
                return ["Functions: []"], []
            return [f"{n}" for n in sorted(self.lambda_fns)], []
        return [], [f"aws lambda: unknown command '{cmd}'"]

    def _dynamodb(self, args):
        if not args:
            return [], ["usage: aws dynamodb <command>"]
        cmd = args[0]
        if cmd == "create-table":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            self.dynamo_tables.setdefault(name, [])
            return [f"TableDescription: TableName {name} · status ACTIVE"], []
        if cmd == "put-item":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            try:
                item = _ddb_from_json(json.loads(d.get("item", "{}")))
            except Exception:
                return [], ["An error occurred (ValidationException): invalid item JSON"]
            if name not in self.dynamo_tables:
                return [], [f"An error occurred (ResourceNotFoundException): Table not found: {name}"]
            self.dynamo_tables[name].append(item)
            return [], []
        if cmd == "get-item":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            key = _ddb_from_json(json.loads(d.get("key", "{}")))
            for it in self.dynamo_tables.get(name, []):
                if all(it.get(k) == v for k, v in key.items()):
                    return [json.dumps(_ddb_to_json(it))], []
            return ["{}"], []
        if cmd == "scan":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            items = self.dynamo_tables.get(name, [])
            if not items:
                return ["Items: []  Count: 0"], []
            return [json.dumps(_ddb_to_json(it)) for it in items] + [f"Count: {len(items)}"], []
        if cmd == "list-tables":
            return ["TableNames:"] + sorted(self.dynamo_tables), []
        return [], [f"aws dynamodb: unknown command '{cmd}'"]

    def _iam(self, args):
        if not args:
            return [], ["usage: aws iam <command>"]
        cmd = args[0]
        if cmd == "create-user":
            d = _aws_flags(args[1:])
            u = d.get("user-name", "")
            self.iam_users.add(u)
            return [f"User created: {u}"], []
        if cmd == "create-role":
            d = _aws_flags(args[1:])
            r = d.get("role-name", "")
            self.iam_roles[r] = {"policies": []}
            return [f"Role created: {r}"], []
        if cmd == "create-policy":
            d = _aws_flags(args[1:])
            p = d.get("policy-name", "")
            arn = f"arn:aws:iam::123456789012:policy/{p}"
            self.iam_policies[p] = arn
            return [f"Policy created: {arn}"], []
        if cmd == "attach-role-policy":
            d = _aws_flags(args[1:])
            r, arn = d.get("role-name", ""), d.get("policy-arn", "")
            if r in self.iam_roles:
                self.iam_roles[r]["policies"].append(arn)
            return [], []
        if cmd == "list-users":
            return [f"{u}" for u in sorted(self.iam_users)], []
        if cmd == "list-roles":
            return [f"{r} (policies: {len(self.iam_roles[r]['policies'])})" for r in sorted(self.iam_roles)], []
        return [], [f"aws iam: unknown command '{cmd}'"]

    def _sqs(self, args):
        """Queues: create-queue / send-message / receive-message / delete-queue."""
        if not args:
            return [], ["usage: aws sqs <command>"]
        cmd = args[0]
        if cmd == "create-queue":
            d = _aws_flags(args[1:])
            name = d.get("queue-name", "queue")
            url = f"https://sqs.us-east-1.amazonaws.com/123456789012/{name}"
            self.sqs_queues[name] = []
            return [url], []
        if cmd == "send-message":
            d = _aws_flags(args[1:])
            url = d.get("queue-url", "")
            name = url.rstrip("/").split("/")[-1]
            if name not in self.sqs_queues:
                return [], ["An error occurred (AWS.SimpleQueueService.NonExistentQueue)"]
            body = d.get("message-body", "")
            mid = f"msg-{len(self.sqs_queues[name]) + 1}"
            self.sqs_queues[name].append({"MessageId": mid, "Body": body})
            return [f"MessageId: {mid}"], []
        if cmd == "receive-message":
            d = _aws_flags(args[1:])
            url = d.get("queue-url", "")
            name = url.rstrip("/").split("/")[-1]
            if name not in self.sqs_queues:
                return [], ["An error occurred (NonExistentQueue)"]
            q = self.sqs_queues[name]
            if not q:
                return [], []
            msg = q.pop(0)
            return [f"MessageId: {msg['MessageId']}", f"Body: {msg['Body']}"], []
        if cmd == "delete-queue":
            d = _aws_flags(args[1:])
            url = d.get("queue-url", "")
            name = url.rstrip("/").split("/")[-1]
            self.sqs_queues.pop(name, None)
            return [], []
        return [], [f"aws sqs: unknown command '{cmd}'"]

    def _cloudwatch(self, args):
        """Metrics: put-metric-data / get-metric-statistics."""
        if not args:
            return [], ["usage: aws cloudwatch <command>"]
        cmd = args[0]
        if cmd == "put-metric-data":
            d = _aws_flags(args[1:])
            ns = d.get("namespace", "default")
            name = d.get("metric-name", "metric")
            val = d.get("value", "0")
            self.cloudwatch_metrics.setdefault(f"{ns}/{name}", []).append(val)
            # a metric above an alarm's threshold flips that alarm to ALARM
            try:
                num = float(val)
                for a in self.cloudwatch_alarms.values():
                    if a["metric"] == name and num > float(a["threshold"]):
                        a["state"] = "ALARM"
                    elif a["metric"] == name:
                        a["state"] = "OK"
            except ValueError:
                pass
            return [], []
        if cmd == "put-metric-alarm":
            d = _aws_flags(args[1:])
            name = d.get("alarm-name", "alarm")
            self.cloudwatch_alarms[name] = {"metric": d.get("metric-name", "metric"),
                                            "threshold": d.get("threshold", "100"),
                                            "state": "OK"}
            return [], []
        if cmd == "describe-alarms":
            if not self.cloudwatch_alarms:
                return ["MetricAlarms: []"], []
            return [f"{n}  {a['metric']} > {a['threshold']}  [{a['state']}]"
                    for n, a in sorted(self.cloudwatch_alarms.items())], []
        if cmd == "set-alarm-state":
            d = _aws_flags(args[1:])
            name = d.get("alarm-name", "")
            state = d.get("state-value", "OK")
            if name in self.cloudwatch_alarms:
                self.cloudwatch_alarms[name]["state"] = state
            return [], []
        if cmd == "get-metric-statistics":
            d = _aws_flags(args[1:])
            ns = d.get("namespace", "default")
            name = d.get("metric-name", "metric")
            vals = self.cloudwatch_metrics.get(f"{ns}/{name}", [])
            if not vals:
                return ["Datapoints: []"], []
            try:
                nums = [float(v) for v in vals]
                return [f"Datapoints: {len(nums)}  avg {sum(nums)/len(nums):.1f}  "
                        f"max {max(nums):.1f}  min {min(nums):.1f}"], []
            except ValueError:
                return [f"Datapoints: {len(vals)}"], []
        return [], [f"aws cloudwatch: unknown command '{cmd}'"]

    def _rds(self, args):
        """Databases: create-db-instance / describe-db-instances / delete-db-instance."""
        if not args:
            return [], ["usage: aws rds <command>"]
        cmd = args[0]
        if cmd == "create-db-instance":
            d = _aws_flags(args[1:])
            ident = d.get("db-instance-identifier", "db")
            engine = d.get("engine", "postgres")
            klass = d.get("db-instance-class", "db.t3.micro")
            self.rds_instances[ident] = {"engine": engine, "class": klass, "status": "available"}
            return [f"DBInstance {ident}  {engine}  {klass}  creating..."], []
        if cmd == "describe-db-instances":
            if not self.rds_instances:
                return ["DBInstances: []"], []
            return [f"{i}  {d['engine']}  {d['class']}  {d['status']}"
                    for i, d in sorted(self.rds_instances.items())], []
        if cmd == "delete-db-instance":
            d = _aws_flags(args[1:])
            ident = d.get("db-instance-identifier", "")
            self.rds_instances.pop(ident, None)
            return [], []
        if cmd == "create-db-snapshot":
            d = _aws_flags(args[1:])
            snap = d.get("db-snapshot-identifier", "snap")
            src = d.get("db-instance-identifier", "")
            if src not in self.rds_instances:
                return [], [f"An error occurred (DBInstanceNotFound): {src}"]
            self.db_snapshots[snap] = {"source": src, "engine": self.rds_instances[src]["engine"]}
            return [f"DBSnapshot {snap} of {src} creating..."], []
        if cmd == "describe-db-snapshots":
            if not self.db_snapshots:
                return ["DBSnapshots: []"], []
            return [f"{s}  from {d['source']}  {d['engine']}"
                    for s, d in sorted(self.db_snapshots.items())], []
        if cmd == "restore-db-instance-from-db-snapshot":
            d = _aws_flags(args[1:])
            ident = d.get("db-instance-identifier", "db-restored")
            snap = d.get("db-snapshot-identifier", "")
            if snap not in self.db_snapshots:
                return [], [f"An error occurred (DBSnapshotNotFound): {snap}"]
            self.rds_instances[ident] = {"engine": self.db_snapshots[snap]["engine"],
                                          "class": "db.t3.micro", "status": "available",
                                          "restored_from": snap}
            return [f"DBInstance {ident} restoring from snapshot {snap}..."], []
        if cmd == "create-db-instance-read-replica":
            d = _aws_flags(args[1:])
            ident = d.get("db-instance-identifier", "db-replica")
            src = d.get("source-db-instance-identifier", "")
            if src not in self.rds_instances:
                return [], [f"An error occurred (DBInstanceNotFound): {src}"]
            self.rds_instances[ident] = {"engine": self.rds_instances[src]["engine"],
                                          "class": self.rds_instances[src]["class"],
                                          "status": "available", "replica_of": src}
            return [f"DBInstance {ident} read replica of {src} creating..."], []
        if cmd == "modify-db-instance":
            d = _aws_flags(args[1:])
            ident = d.get("db-instance-identifier", "")
            if ident not in self.rds_instances:
                return [], [f"An error occurred (DBInstanceNotFound): {ident}"]
            if "db-instance-class" in d:
                self.rds_instances[ident]["class"] = d["db-instance-class"]
            return [f"DBInstance {ident} modified."], []
        return [], [f"aws rds: unknown command '{cmd}'"]

    def _kms(self, args):
        """Encryption keys: create-key / list-keys (at-rest encryption for
        regulated data)."""
        if not args:
            return [], ["usage: aws kms <create-key|list-keys>"]
        cmd = args[0]
        if cmd == "create-key":
            kid = "key-%04d" % (len(self.kms_keys) + 1)
            self.kms_keys[kid] = {"arn": f"arn:aws:kms:us-east-1:123456789012:key/{kid}"}
            return [f"KeyId: {kid}", f"KeyArn: {self.kms_keys[kid]['arn']}"], []
        if cmd == "list-keys":
            return [k for k in sorted(self.kms_keys)] or ["Keys: []"], []
        return [], [f"aws kms: unknown command '{cmd}'"]

    def _elb(self, args):
        """Load balancers: create-load-balancer / register-targets / describe-load-balancers."""
        if not args:
            return [], ["usage: aws elbv2 <command>"]
        cmd = args[0]
        if cmd == "create-load-balancer":
            d = _aws_flags(args[1:])
            name = d.get("name", "lb")
            arn = f"arn:aws:elasticloadbalancing:us-east-1:123456789012:loadbalancer/app/{name}"
            self.elb[name] = {"arn": arn, "targets": []}
            return [arn], []
        if cmd == "register-targets":
            d = _aws_flags(args[1:])
            name = d.get("target-group-arn", "app/lb").split("/")[-1]
            ids = [a for a in args if a.startswith("i-")]
            if name in self.elb:
                self.elb[name]["targets"].extend(ids)
            return [f"registered {len(ids)} target(s)"], []
        if cmd == "describe-load-balancers":
            if not self.elb:
                return ["LoadBalancers: []"], []
            return [f"{name}  targets: {len(self.elb[name]['targets'])}"
                    for name in sorted(self.elb)], []
        return [], [f"aws elbv2: unknown command '{cmd}'"]

    def _cloudfront(self, args):
        """CDN: create-distribution / list-distributions."""
        if not args:
            return [], ["usage: aws cloudfront <command>"]
        cmd = args[0]
        if cmd == "create-distribution":
            d = _aws_flags(args[1:])
            origin = d.get("origin-domain-name", "bucket.s3.amazonaws.com")
            n = len(self.cloudfront) + 1
            iid = f"E{1000 + n}"
            domain = f"d{1000 + n}.cloudfront.net"
            self.cloudfront[iid] = {"origin": origin, "domain": domain}
            return [f"Distribution {iid}  {domain}  ->  {origin}"], []
        if cmd == "list-distributions":
            if not self.cloudfront:
                return ["Distributions: []"], []
            return [f"{iid}  {d['domain']}  ->  {d['origin']}"
                    for iid, d in sorted(self.cloudfront.items())], []
        return [], [f"aws cloudfront: unknown command '{cmd}'"]

    def _apigateway(self, args):
        """HTTP API: create-rest-api / create-deployment / get-rest-apis."""
        if not args:
            return [], ["usage: aws apigateway <command>"]
        cmd = args[0]
        if cmd == "create-rest-api":
            d = _aws_flags(args[1:])
            name = d.get("name", "api")
            self.apigateway[name] = {"id": f"api{len(self.apigateway) + 1}", "deployed": False}
            return [f"REST API {self.apigateway[name]['id']} ({name})"], []
        if cmd == "create-deployment":
            d = _aws_flags(args[1:])
            rid = d.get("rest-api-id", "")
            for a in self.apigateway.values():
                if a["id"] == rid:
                    a["deployed"] = True
                    return ["Deployed to stage: prod"], []
            return [], ["An error occurred (NotFoundException)"]
        if cmd == "get-rest-apis":
            if not self.apigateway:
                return ["items: []"], []
            return [f"{a['id']}  {n}  {'deployed' if a['deployed'] else 'not deployed'}"
                    for n, a in sorted(self.apigateway.items())], []
        return [], [f"aws apigateway: unknown command '{cmd}'"]

    def _sns(self, args):
        """Notifications: create-topic / publish / list-topics."""
        if not args:
            return [], ["usage: aws sns <command>"]
        cmd = args[0]
        if cmd == "create-topic":
            d = _aws_flags(args[1:])
            name = d.get("name", "topic")
            arn = f"arn:aws:sns:us-east-1:123456789012:{name}"
            self.sns_topics[name] = {"arn": arn, "messages": []}
            return [arn], []
        if cmd == "publish":
            d = _aws_flags(args[1:])
            arn = d.get("topic-arn", "")
            name = arn.split(":")[-1]
            if name not in self.sns_topics:
                return [], ["An error occurred (NotFound)"]
            body = d.get("message", "")
            self.sns_topics[name]["messages"].append(body)
            return [f"MessageId: {len(self.sns_topics[name]['messages'])}"], []
        if cmd == "list-topics":
            if not self.sns_topics:
                return ["Topics: []"], []
            return [a["arn"] for _, a in sorted(self.sns_topics.items())], []
        return [], [f"aws sns: unknown command '{cmd}'"]

    def _autoscaling(self, args):
        """Scale: create-auto-scaling-group / describe-auto-scaling-groups / set-desired-capacity."""
        if not args:
            return [], ["usage: aws autoscaling <command>"]
        cmd = args[0]
        if cmd == "create-auto-scaling-group":
            d = _aws_flags(args[1:])
            name = d.get("auto-scaling-group-name", "asg")
            self.asg[name] = {"min": d.get("min-size", "1"),
                              "max": d.get("max-size", "1"),
                              "desired": d.get("desired-capacity", "1")}
            a = self.asg[name]
            return [f"AutoScalingGroup {name}  min {a['min']}  max {a['max']}  desired {a['desired']}"], []
        if cmd == "describe-auto-scaling-groups":
            if not self.asg:
                return ["AutoScalingGroups: []"], []
            return [f"{n}  min {a['min']}  max {a['max']}  desired {a['desired']}"
                    for n, a in sorted(self.asg.items())], []
        if cmd == "set-desired-capacity":
            d = _aws_flags(args[1:])
            name = d.get("auto-scaling-group-name", "")
            dc = d.get("desired-capacity", "")
            if name in self.asg:
                self.asg[name]["desired"] = dc
            return [], []
        return [], [f"aws autoscaling: unknown command '{cmd}'"]

    def _secretsmanager(self, args):
        """Secrets: create-secret / put-secret-value / get-secret-value / list-secrets / delete-secret."""
        if not args:
            return [], ["usage: aws secretsmanager <command>"]
        cmd = args[0]
        if cmd == "create-secret":
            d = _aws_flags(args[1:])
            name = d.get("name", "secret")
            val = d.get("secret-string", "")
            arn = f"arn:aws:secretsmanager:us-east-1:123456789012:secret:{name}"
            self.secrets[name] = {"value": val, "arn": arn}
            return [f"ARN: {arn}"], []
        if cmd == "put-secret-value":
            d = _aws_flags(args[1:])
            name = d.get("secret-id", "")
            val = d.get("secret-string", "")
            if name in self.secrets:
                self.secrets[name]["value"] = val
            return [], []
        if cmd == "get-secret-value":
            d = _aws_flags(args[1:])
            name = d.get("secret-id", "")
            if name not in self.secrets:
                return [], [f"An error occurred (ResourceNotFoundException): Secrets Manager can't find the specified secret"]
            return [f"SecretString: {self.secrets[name]['value']}"], []
        if cmd == "list-secrets":
            if not self.secrets:
                return ["SecretList: []"], []
            return [f"{n}  {self.secrets[n]['arn']}" for n in sorted(self.secrets)], []
        if cmd == "delete-secret":
            d = _aws_flags(args[1:])
            self.secrets.pop(d.get("secret-id", ""), None)
            return [], []
        return [], [f"aws secretsmanager: unknown command '{cmd}'"]

    def _monthly_cost(self):
        """A deterministic, rough monthly bill from the resources currently up."""
        c = 0.0
        c += len(self.buckets) * 0.023          # S3 storage
        c += sum(1 for i in self.instances.values() if i["State"]["Name"] == "running") * 8.40
        c += len(self.rds_instances) * 14.00    # db.t3.micro-ish
        c += len(self.elb) * 18.00
        c += len(self.cloudfront) * 0.50
        c += len(self.dynamo_tables) * 1.25
        return round(c, 2)

    def _ce(self, args):
        """Cost Explorer: get-cost-and-usage returns the running monthly bill."""
        if not args:
            return [], ["usage: aws ce <command>"]
        cmd = args[0]
        if cmd == "get-cost-and-usage":
            cost = self._monthly_cost()
            return [f"Estimated monthly cost: ${cost:.2f}"], []
        return [], [f"aws ce: unknown command '{cmd}'"]

    def _budgets(self, args):
        """Budgets: create-budget / describe-budgets — alert before the bill surprises you."""
        if not args:
            return [], ["usage: aws budgets <command>"]
        cmd = args[0]
        if cmd == "create-budget":
            d = _aws_flags(args[1:])
            name = d.get("budget-name", "budget")
            amount = d.get("limit-amount", "100")
            self.budgets[name] = {"amount": amount}
            return [f"Budget {name} created with limit ${amount}"], []
        if cmd == "describe-budgets":
            if not self.budgets:
                return ["Budgets: []"], []
            cost = self._monthly_cost()
            out = [f"current monthly cost: ${cost:.2f}"]
            for n, b in sorted(self.budgets.items()):
                over = cost > float(b["amount"])
                out.append(f"{n}  limit ${b['amount']}  {'OVER' if over else 'under'}")
            return out, []
        return [], [f"aws budgets: unknown command '{cmd}'"]


def _aws_flags(args):
    """Parse `--key value --key2 value2 ...` into a dict (bare args dropped)."""
    d = {}
    i = 0
    while i < len(args):
        a = args[i]
        if a.startswith("--") and i + 1 < len(args):
            d[a[2:]] = args[i + 1]
            i += 2
        else:
            i += 1
    return d


class AzEnv:
    """Simulated Azure CLI (offline): resource groups, VMs, storage accounts,
    VNets/subnets, AKS, app services, functions. Mirrors AwsEnv's feel but
    speaks `az group/vm/storage/network/aks/webapp/functionapp`. Deterministic
    ids (vm-0001, vm-0002, …) like the AWS `i-0001` pattern."""

    def __init__(self, fs):
        self.fs = fs
        self.resource_groups = set()     # names
        self.vms = {}                    # name -> {"rg","size","state","id"}
        self.next_vm = 1
        self.storage_accounts = {}       # name -> {"rg","containers":{}}
        self.vnets = {}                  # name -> {"rg","subnets":set(),"address"}
        self.aks = {}                    # name -> {"rg","nodes","kubeconfig"}
        self.webapps = {}                # name -> {"rg","url"}
        self.functions = {}              # name -> {"rg","runtime"}
        self.nsgs = {}                   # nsg name -> {"rules":[(name,port,access)]}
        self.route_tables = {}           # rt name -> {"routes":[(prefix,hop)]}

    def run(self, rest):
        try:
            parts = shlex.split(rest)
        except ValueError:
            parts = rest.split()
        if not parts:
            return [], ["usage: az <service> <command>"]
        svc = parts[0]
        if svc == "group":
            return self._group(parts[1:])
        if svc == "vm":
            return self._vm(parts[1:])
        if svc == "storage":
            return self._storage(parts[1:])
        if svc == "network":
            return self._network(parts[1:])
        if svc == "aks":
            return self._aks(parts[1:])
        if svc == "webapp":
            return self._webapp(parts[1:])
        if svc == "functionapp":
            return self._functionapp(parts[1:])
        if svc in ("--version", "version"):
            return ["azure-cli 2.55.0"], []
        return [], [f"az: error: unrecognized arguments: '{svc}' (try "
                    "group, vm, storage, network, aks, webapp, functionapp)"]

    def _group(self, args):
        if not args:
            return [], ["usage: az group <create|list|delete>"]
        cmd = args[0]
        d = _aws_flags(args[1:])
        if cmd == "create":
            name = d.get("name", "myrg")
            if name in self.resource_groups:
                return [], [f"The resource group '{name}' already exists."]
            self.resource_groups.add(name)
            return [f"Resource group '{name}' created in {d.get('location', 'eastus')}."], []
        if cmd == "list":
            return sorted(self.resource_groups) or ["(no resource groups)"], []
        if cmd == "delete":
            name = d.get("name", "")
            if name not in self.resource_groups:
                return [], [f"The resource group '{name}' was not found."]
            self.resource_groups.discard(name)
            return [], []
        return [], [f"az group: unknown command '{cmd}'"]

    def _vm(self, args):
        if not args:
            return [], ["usage: az vm <create|list|start|stop|delete>"]
        cmd = args[0]
        d = _aws_flags(args[1:])
        if cmd == "create":
            name = d.get("name", "vm")
            rg = d.get("resource-group", "default")
            vid = "vm-%04d" % self.next_vm
            self.next_vm += 1
            self.vms[name] = {"rg": rg, "size": d.get("size", "Standard_B1s"),
                              "state": "running", "id": vid}
            self.resource_groups.add(rg)
            return [f"VM '{name}' created — id {vid}, running ({d.get('image', 'UbuntuLTS')})."], []
        if cmd == "list":
            if not self.vms:
                return ["(no VMs)"], []
            return [f"{n}  {self.vms[n]['state']:<8} {self.vms[n]['size']}"
                    for n in sorted(self.vms)], []
        if cmd in ("start", "stop"):
            name = d.get("name", "")
            if name not in self.vms:
                return [], [f"The VM '{name}' was not found."]
            self.vms[name]["state"] = "running" if cmd == "start" else "stopped"
            return [f"VM '{name}' {'started' if cmd == 'start' else 'stopped'}."], []
        if cmd == "delete":
            name = d.get("name", "")
            if name in self.vms:
                del self.vms[name]
            return [], []
        return [], [f"az vm: unknown command '{cmd}'"]

    def _storage(self, args):
        if not args:
            return [], ["usage: az storage <account|container> ..."]
        sub = args[0]
        if sub == "account":
            if len(args) < 2:
                return [], ["usage: az storage account <create|list|delete>"]
            cmd = args[1]
            d = _aws_flags(args[2:])
            if cmd == "create":
                name = d.get("name", "storage")
                if name in self.storage_accounts:
                    return [], [f"The storage account '{name}' already exists."]
                self.storage_accounts[name] = {"rg": d.get("resource-group", ""), "containers": {}}
                return [f"Storage account '{name}' created."], []
            if cmd == "list":
                if not self.storage_accounts:
                    return ["(no storage accounts)"], []
                return [f"{n}  {self.storage_accounts[n]['rg']}"
                        for n in sorted(self.storage_accounts)], []
            if cmd == "delete":
                name = d.get("name", "")
                if name in self.storage_accounts:
                    del self.storage_accounts[name]
                return [], []
            return [], [f"az storage account: unknown command '{cmd}'"]
        if sub == "container":
            if len(args) < 2:
                return [], ["usage: az storage container <create|list>"]
            cmd = args[1]
            d = _aws_flags(args[2:])
            if cmd == "create":
                acc = d.get("account-name", "")
                name = d.get("name", "container")
                if acc not in self.storage_accounts:
                    return [], [f"The storage account '{acc}' was not found."]
                self.storage_accounts[acc]["containers"][name] = {}
                return [f"Container '{name}' created in account '{acc}'."], []
            if cmd == "list":
                acc = d.get("account-name", "")
                if acc not in self.storage_accounts:
                    return [], [f"The storage account '{acc}' was not found."]
                return (sorted(self.storage_accounts[acc]["containers"])
                        or ["(empty)"]), []
            return [], [f"az storage container: unknown command '{cmd}'"]
        return [], [f"az storage: unknown subcommand '{sub}'"]

    def _network(self, args):
        if not args:
            return [], ["usage: az network <vnet|...> ..."]
        sub = args[0]
        if sub == "vnet":
            if len(args) < 2:
                return [], ["usage: az network vnet <create|list|subnet> ..."]
            cmd = args[1]
            d = _aws_flags(args[2:])
            if cmd == "create":
                name = d.get("name", "vnet")
                self.vnets[name] = {"rg": d.get("resource-group", ""),
                                    "subnets": set(),
                                    "address": d.get("address-prefixes", "10.0.0.0/16")}
                return [f"Virtual network '{name}' created ({self.vnets[name]['address']})."], []
            if cmd == "list":
                if not self.vnets:
                    return ["(no VNets)"], []
                return [f"{n}  {self.vnets[n]['address']}"
                        for n in sorted(self.vnets)], []
            if cmd == "subnet":
                if len(args) < 3:
                    return [], ["usage: az network vnet subnet <create|list> ..."]
                scmd = args[2]
                d = _aws_flags(args[3:])
                vnet = d.get("vnet-name", "")
                if vnet not in self.vnets:
                    return [], [f"Virtual network '{vnet}' was not found."]
                if scmd == "create":
                    self.vnets[vnet]["subnets"].add(d.get("name", "subnet"))
                    return [f"Subnet '{d.get('name', 'subnet')}' created in '{vnet}' "
                            f"({d.get('address-prefix', '')})."], []
                if scmd == "list":
                    return sorted(self.vnets[vnet]["subnets"]) or ["(empty)"], []
                return [], [f"az network vnet subnet: unknown command '{scmd}'"]
            return [], [f"az network vnet: unknown command '{cmd}'"]
        if sub == "nsg":
            if len(args) < 2:
                return [], ["usage: az network nsg <create|list|rule> ..."]
            cmd = args[1]
            d = _aws_flags(args[2:])
            if cmd == "create":
                name = d.get("name", "nsg")
                self.nsgs[name] = {"rules": []}
                return [f"Network security group '{name}' created."], []
            if cmd == "list":
                return ([f"{n}  rules={len(self.nsgs[n]['rules'])}"
                         for n in sorted(self.nsgs)] or ["(no NSGs)"]), []
            if cmd == "rule":
                if len(args) < 3:
                    return [], ["usage: az network nsg rule <create|list> ..."]
                rcmd = args[2]
                d = _aws_flags(args[3:])
                nsg = d.get("nsg-name", "")
                if nsg not in self.nsgs:
                    return [], [f"Network security group '{nsg}' was not found."]
                if rcmd == "create":
                    rule = (d.get("name", "rule"),
                            d.get("destination-port-ranges", ""),
                            d.get("access", "Allow"))
                    self.nsgs[nsg]["rules"].append(rule)
                    return [f"Rule '{d.get('name', 'rule')}' added to '{nsg}' "
                            f"({d.get('access', 'Allow')})."], []
                if rcmd == "list":
                    return ([f"{n}  port {p}  {a}"
                             for n, p, a in self.nsgs[nsg]["rules"]] or ["(no rules)"]), []
                return [], [f"az network nsg rule: unknown command '{rcmd}'"]
            return [], [f"az network nsg: unknown command '{cmd}'"]
        if sub == "route-table":
            if len(args) < 2:
                return [], ["usage: az network route-table <create|list|route> ..."]
            cmd = args[1]
            d = _aws_flags(args[2:])
            if cmd == "create":
                name = d.get("name", "rt")
                self.route_tables[name] = {"routes": []}
                return [f"Route table '{name}' created."], []
            if cmd == "list":
                return ([f"{n}  routes={len(self.route_tables[n]['routes'])}"
                         for n in sorted(self.route_tables)] or ["(no route tables)"]), []
            if cmd == "route":
                if len(args) < 3:
                    return [], ["usage: az network route-table route <create|list> ..."]
                rcmd = args[2]
                d = _aws_flags(args[3:])
                rt = d.get("route-table-name", "")
                if rt not in self.route_tables:
                    return [], [f"Route table '{rt}' was not found."]
                if rcmd == "create":
                    self.route_tables[rt]["routes"].append(
                        (d.get("address-prefix", ""), d.get("next-hop-type", "")))
                    return [f"Route to {d.get('address-prefix', '')} added "
                            f"({d.get('next-hop-type', '')})."], []
                if rcmd == "list":
                    return ([f"{dest} -> {hop}"
                             for dest, hop in self.route_tables[rt]["routes"]]
                            or ["(no routes)"]), []
                return [], [f"az network route-table route: unknown command '{rcmd}'"]
            return [], [f"az network route-table: unknown command '{cmd}'"]
        return [], [f"az network: unknown subcommand '{sub}'"]

    def _aks(self, args):
        if not args:
            return [], ["usage: az aks <create|list|get-credentials>"]
        cmd = args[0]
        d = _aws_flags(args[1:])
        if cmd == "create":
            name = d.get("name", "cluster")
            self.aks[name] = {"rg": d.get("resource-group", ""),
                              "nodes": d.get("node-count", "1"),
                              "kubeconfig": False}
            return [f"AKS cluster '{name}' created ({self.aks[name]['nodes']} node(s))."], []
        if cmd == "list":
            if not self.aks:
                return ["(no clusters)"], []
            return [f"{n}  nodes={self.aks[n]['nodes']}"
                    for n in sorted(self.aks)], []
        if cmd == "get-credentials":
            name = d.get("name", "")
            if name not in self.aks:
                return [], [f"The cluster '{name}' was not found."]
            self.aks[name]["kubeconfig"] = True
            return [f"Merged '{name}' as the current context — kubectl now points at it."], []
        return [], [f"az aks: unknown command '{cmd}'"]

    def _webapp(self, args):
        if not args:
            return [], ["usage: az webapp <create|list>"]
        cmd = args[0]
        d = _aws_flags(args[1:])
        if cmd == "create":
            name = d.get("name", "webapp")
            self.webapps[name] = {"rg": d.get("resource-group", ""),
                                  "url": f"https://{name}.azurewebsites.net"}
            return [f"Web app '{name}' created — {self.webapps[name]['url']}"], []
        if cmd == "list":
            if not self.webapps:
                return ["(no web apps)"], []
            return [f"{n}  {self.webapps[n]['url']}" for n in sorted(self.webapps)], []
        return [], [f"az webapp: unknown command '{cmd}'"]

    def _functionapp(self, args):
        if not args:
            return [], ["usage: az functionapp <create|list>"]
        cmd = args[0]
        d = _aws_flags(args[1:])
        if cmd == "create":
            name = d.get("name", "fn")
            self.functions[name] = {"rg": d.get("resource-group", ""),
                                    "runtime": d.get("runtime", "python")}
            return [f"Function app '{name}' created ({self.functions[name]['runtime']})."], []
        if cmd == "list":
            if not self.functions:
                return ["(no function apps)"], []
            return [f"{n}  {self.functions[n]['runtime']}" for n in sorted(self.functions)], []
        return [], [f"az functionapp: unknown command '{cmd}'"]


def _ddb_from_json(item):
    """DynamoDB low-level JSON ({\"S\": v}) → native Python dict."""
    out = {}
    for k, v in item.items():
        if isinstance(v, dict):
            if "S" in v:
                out[k] = v["S"]
            elif "N" in v:
                out[k] = int(v["N"]) if str(v["N"]).lstrip("-").isdigit() else v["N"]
            elif "BOOL" in v:
                out[k] = v["BOOL"]
            else:
                out[k] = v
        else:
            out[k] = v
    return out


def _ddb_to_json(item):
    """Native Python dict → DynamoDB low-level JSON."""
    out = {}
    for k, v in item.items():
        if isinstance(v, bool):
            out[k] = {"BOOL": v}
        elif isinstance(v, int):
            out[k] = {"N": str(v)}
        else:
            out[k] = {"S": str(v)}
    return out


# ---- terraform (simulated) ---------------------------------------------------

class TerraformEnv:
    def __init__(self, fs):
        self.fs = fs
        self.resources = {}   # "type.name" -> {"attrs": {...}}
        self.plan = []        # ("+"|"~"|"-", key, attrs)
        self.inited = False

    def _config(self):
        cfg = {}
        for path, content in self.fs.files.items():
            if path.endswith(".tf"):
                for b in hcl_parse(content):
                    if b["type"] in ("resource", "data") and b["labels"]:
                        key = ".".join(b["labels"])
                        cfg[key] = {"type": b["type"], "attrs": dict(b["attrs"])}
        return cfg

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["Usage: terraform <command>"]
        cmd = parts[0]
        if cmd == "init":
            self.inited = True
            return ["Initializing the backend...",
                    "Initializing provider plugins...",
                    "Terraform has been successfully initialized!"], []
        if cmd == "plan":
            if not self.inited:
                return [], ["Error: Backend initialization required"]
            cfg = self._config()
            plan = []
            for key, r in cfg.items():
                if key not in self.resources:
                    plan.append(("+", key, r["attrs"]))
                elif self.resources[key]["attrs"] != r["attrs"]:
                    plan.append(("~", key, r["attrs"]))
            for key in list(self.resources):
                if key not in cfg:
                    plan.append(("-", key, {}))
            self.plan = plan
            if not plan:
                return ["No changes. Your infrastructure matches the configuration."], []
            out = ["Terraform will perform the following actions:"]
            for op, key, attrs in plan:
                detail = " " + ", ".join(f"{k}={v!r}" for k, v in attrs.items()) if attrs else ""
                out.append(f"  {op} {key}{detail}")
            a = sum(1 for o, _, _ in plan if o == "+")
            c = sum(1 for o, _, _ in plan if o == "~")
            d = sum(1 for o, _, _ in plan if o == "-")
            out.append(f"Plan: {a} to add, {c} to change, {d} to destroy.")
            return out, []
        if cmd == "apply":
            for op, key, attrs in self.plan:
                if op == "-":
                    self.resources.pop(key, None)
                else:
                    self.resources[key] = {"attrs": attrs}
            n = len(self.plan)
            self.plan = []
            return [f"Apply complete! Resources: {n} added/changed."], []
        if cmd == "destroy":
            self.resources.clear()
            return ["Destroy complete! Resources: 0 remaining."], []
        if cmd == "state":
            if len(parts) > 1 and parts[1] == "list":
                return sorted(self.resources.keys()), []
            return [], []
        if cmd == "show":
            return [f"{k}: {json.dumps(self.resources[k]['attrs'])}" for k in sorted(self.resources)], []
        return [], [f"terraform: unknown command '{cmd}'"]


# ---- ansible (simulated) -----------------------------------------------------

class AnsibleEnv:
    def __init__(self, fs):
        self.fs = fs
        self.hosts = {}        # host -> {"packages": set, "services": {}, "files": {}}
        self.handlers_fired = []

    def _host_state(self, host):
        return self.hosts.setdefault(host, {"packages": set(), "services": {}, "files": {}})

    def _module(self, host, module, params):
        st = self._host_state(host)
        if module == "apt":
            name = params.get("name", "")
            if name in st["packages"]:
                return False, f"{name} is already installed"
            st["packages"].add(name)
            return True, f"installed {name}"
        if module == "service":
            name = params.get("name", "")
            state = params.get("state", "started")
            if st["services"].get(name) == state:
                return False, f"{name} is already {state}"
            st["services"][name] = state
            return True, f"{name} is now {state}"
        if module == "copy":
            dest = params.get("dest", params.get("path", ""))
            content = params.get("content", self.fs.files.get(self.fs._resolve(params.get("src", "")), ""))
            if st["files"].get(dest) == content:
                return False, f"{dest} is unchanged"
            st["files"][dest] = content
            return True, f"copied to {dest}"
        if module in ("file", "template", "user", "shell", "command", "get_url", "debug"):
            # these are "real actions" — always count as changed on first touch,
            # idempotent if the exact same action was already recorded
            key = f"{module}:{json.dumps(params, sort_keys=True)}"
            done = st.setdefault("actions", set())
            if key in done:
                return False, f"{module} already applied"
            done.add(key)
            return True, f"{module}: ok"
        return True, f"ran {module}"

    def _play_hosts(self, hosts_spec):
        # hosts: "web" | "all" | "web,db" | explicit list
        result = []
        for grp in [h.strip() for h in hosts_spec.split(",")]:
            if grp in self.inventory:
                result.extend(self.inventory[grp])
            elif grp == "all":
                for g in self.inventory.values():
                    result.extend(g)
            else:
                result.append(grp)
        return sorted(set(result))

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: ansible-playbook <playbook.yml>"]
        # strip flags like -i <file> / --tags <t>
        playbook = None
        tags = None
        i = 0
        argv = parts
        while i < len(argv):
            a = argv[i]
            if a in ("-i", "--inventory"):
                inv = argv[i + 1] if i + 1 < len(argv) else "hosts.ini"
                self._load_inventory(inv)
                i += 2
                continue
            if a in ("--tags", "-t"):
                tags = argv[i + 1] if i + 1 < len(argv) else None
                i += 2
                continue
            if not a.startswith("-"):
                playbook = a
            i += 1
        if not playbook:
            return [], ["ansible-playbook: no playbook given"]
        p = self.fs._resolve(playbook)
        if p not in self.fs.files:
            return [], [f"ERROR! the playbook: {playbook} could not be found"]
        self._load_inventory("hosts.ini")
        data = yaml_parse(self.fs.files[p])
        if not isinstance(data, list):
            return [], ["ERROR! playbook must be a list of plays"]
        events = []
        self.handlers_fired = []
        for play in data:
            if not isinstance(play, dict):
                continue
            name = play.get("name", "unnamed")
            hosts = self._play_hosts(str(play.get("hosts", "all")))
            tasks = play.get("tasks", [])
            handlers = play.get("handlers", [])
            notify = {}  # handler-name -> set of hosts to run it on
            for task in tasks:
                if not isinstance(task, dict):
                    continue
                tname = task.get("name", "unnamed")
                if tags and tname not in str(tags).split(","):
                    continue
                mod = next((k for k in task if k not in ("name", "notify", "tags")), None)
                if mod is None:
                    continue
                params = task.get(mod, {}) or {}
                for host in hosts:
                    changed, msg = self._module(host, mod, params)
                    events.append({"play": name, "task": tname, "host": host,
                                   "changed": changed, "msg": msg})
                    if changed and task.get("notify"):
                        notify.setdefault(task["notify"], set()).add(host)
            # run handlers on the hosts that notified them
            for hdl in handlers:
                if not isinstance(hdl, dict):
                    continue
                hname = hdl.get("name", "")
                if hname not in notify:
                    continue
                mod = next((k for k in hdl if k != "name"), None)
                if mod is None:
                    continue
                params = hdl.get(mod, {}) or {}
                for host in notify[hname]:
                    changed, msg = self._module(host, mod, params)
                    events.append({"play": name, "task": f"HANDLER: {hname}",
                                   "host": host, "changed": changed, "msg": msg})
                    self.handlers_fired.append(hname)
        return self._render_events(events), []

    def _load_inventory(self, invfile):
        p = self.fs._resolve(invfile)
        if p in self.fs.files:
            groups = ini_parse(self.fs.files[p])
            if groups:
                self.inventory = groups
                return
        self.inventory = {"web": ["web-1", "web-2"], "db": ["db-1"],
                          "all": ["web-1", "web-2", "db-1"]}

    def _render_events(self, events):
        if not events:
            return ["PLAY [no hosts matched] ***************"]
        out = []
        cur_play = None
        cur_task = None
        for e in events:
            if e["play"] != cur_play:
                out.append(f"PLAY [{e['play']}] *******************************")
                cur_play = e["play"]
                cur_task = None
            if e["task"] != cur_task:
                out.append(f"TASK [{e['task']}] ******************************")
                cur_task = e["task"]
            status = "changed" if e["changed"] else "ok"
            out.append(f"{status}: [{e['host']}]  {e['msg']}")
        # recap
        out.append("PLAY RECAP *****************************************")
        hosts = sorted({e["host"] for e in events})
        for h in hosts:
            ok = sum(1 for e in events if e["host"] == h and not e["changed"])
            ch = sum(1 for e in events if e["host"] == h and e["changed"])
            out.append(f"{h} : ok={ok} changed={ch} unreachable=0 failed=0")
        return out


# ---- CI/CD pipeline (simulated) ----------------------------------------------

class Pipeline:
    def __init__(self, fs):
        self.fs = fs
        self.runs = []     # {"id", "commit", "stages": [{"name","status"}], "log": [lines]}

    def _workflow(self):
        p = self.fs._resolve(".github/workflows/ci.yml")
        return self.fs.files.get(p, "")

    def _stages(self):
        wf = self._workflow()
        if not wf:
            return [{"name": "build", "cmd": "echo build"}]
        stages = []
        data = yaml_parse(wf)
        jobs = (data or {}).get("jobs", {}) if isinstance(data, dict) else {}
        for name, job in (jobs.items() if isinstance(jobs, dict) else []):
            steps = job.get("steps", []) if isinstance(job, dict) else []
            for st in steps:
                if isinstance(st, dict) and st.get("run"):
                    stages.append({"name": st.get("name", "run"), "cmd": st["run"]})
                elif isinstance(st, dict) and st.get("uses"):
                    stages.append({"name": st.get("name", st["uses"]), "cmd": "uses:" + st["uses"]})
        return stages or [{"name": "build", "cmd": "echo build"}]

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: ci <run|status|logs>"]
        cmd = parts[0]
        if cmd == "run":
            return self._run_pipeline("manual")
        if cmd == "status":
            if not self.runs:
                return ["no pipeline runs yet"], []
            out = []
            for r in self.runs[-5:]:
                ok = all(s["status"] == "pass" for s in r["stages"])
                out.append(f"#{r['id']}  commit {r['commit']}  {'green' if ok else 'red'}")
            return out, []
        if cmd == "logs":
            rid = parts[1] if len(parts) > 1 else (self.runs[-1]["id"] if self.runs else None)
            for r in self.runs:
                if str(r["id"]) == str(rid):
                    return r["log"], []
            return [], ["no such run"]
        return [], [f"ci: unknown command '{cmd}'"]

    def _run_pipeline(self, commit):
        rid = len(self.runs) + 1
        stages = self._stages()
        log = [f"Run #{rid} — commit {commit}", "=" * 40]
        built = []
        for st in stages:
            name, cmd = st["name"], st["cmd"]
            log.append(f"▶ {name}")
            status = "pass"
            if cmd.startswith("uses:"):
                log.append(f"  → {cmd}")
            elif cmd.startswith("python3") or cmd.startswith("pytest"):
                # actually run the test file so a broken test fails the build
                file = cmd.split()[1] if cmd.startswith("python3") else cmd.split()[1]
                fp = self.fs._resolve(file)
                if fp in self.fs.files:
                    stdout, stderr = run_lesson_code(self.fs.files[fp])
                    if stderr.strip() or "Error" in stdout or "Traceback" in stdout:
                        status = "fail"
                        log += [("  " + l) for l in stderr.strip().splitlines()[:4]]
                    else:
                        log += [("  " + l) for l in stdout.strip().splitlines()[:4]]
                else:
                    status = "fail"
                    log.append(f"  {file}: No such file or directory")
            else:
                log.append(f"  → {cmd}")
            if status == "pass":
                log.append(f"  ✓ {name} passed")
            else:
                log.append(f"  ✗ {name} failed")
            built.append({"name": name, "status": status})
        run = {"id": rid, "commit": commit, "stages": built, "log": log}
        self.runs.append(run)
        ok = all(s["status"] == "pass" for s in built)
        log.append("=" * 40)
        log.append(f"RESULT: {'✓ green' if ok else '✗ red'}")
        return log, []


