_BOTO3_STUB = '''\
"""A tiny offline stand-in for boto3 — enough S3 + EC2 to teach the API.

Reads state from $BOTO3_STATE (JSON), applies the learner's calls, and writes
the result back on exit. No network, no real AWS, deterministic."""
import json, os, atexit

_STATE_PATH = os.environ.get("BOTO3_STATE", "")
_state = None


def _get_state():
    global _state
    if _state is None:
        with open(_STATE_PATH) as f:
            _state = json.load(f)
        atexit.register(_flush)
    return _state


def _flush():
    global _state
    if _state is not None:
        with open(_STATE_PATH, "w") as f:
            json.dump(_state, f)


class _Body:
    def __init__(self, content):
        self._content = content
    def read(self):
        return self._content


class _S3Client:
    def __init__(self, s):
        self.s = s
    def list_buckets(self):
        return {"Buckets": [{"Name": n} for n in self.s["buckets"]]}
    def create_bucket(self, Bucket):
        if Bucket in self.s["buckets"]:
            raise Exception("BucketAlreadyExists: " + Bucket)
        self.s["buckets"][Bucket] = {}
        return {"Location": "/" + Bucket}
    def put_object(self, Bucket, Key, Body=""):
        if Bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + Bucket)
        self.s["buckets"][Bucket][Key] = str(Body)
        return {"ETag": '"abc"'}
    def get_object(self, Bucket, Key):
        if Bucket not in self.s["buckets"] or Key not in self.s["buckets"][Bucket]:
            raise Exception("NoSuchKey: " + Key)
        return {"Body": _Body(self.s["buckets"][Bucket][Key])}
    def list_objects_v2(self, Bucket):
        if Bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + Bucket)
        return {"Contents": [{"Key": k} for k in sorted(self.s["buckets"][Bucket])]}
    def delete_object(self, Bucket, Key):
        self.s["buckets"].get(Bucket, {}).pop(Key, None)
        return {}
    def delete_bucket(self, Bucket):
        if Bucket in self.s["buckets"] and self.s["buckets"][Bucket]:
            raise Exception("BucketNotEmpty: " + Bucket)
        self.s["buckets"].pop(Bucket, None)
        return {}


class _Ec2Client:
    def __init__(self, s):
        self.s = s
    def run_instances(self, ImageId, InstanceType="t3.micro", MinCount=1, MaxCount=1):
        ids = []
        for _ in range(int(MinCount)):
            iid = "i-%04d" % self.s["next_inst"]
            self.s["next_inst"] += 1
            self.s["instances"][iid] = {"ImageId": ImageId, "InstanceType": InstanceType,
                                        "State": {"Name": "running"}}
            ids.append(iid)
        return {"Instances": [{"InstanceId": i, "State": {"Name": "running"}} for i in ids]}
    def describe_instances(self):
        out = []
        for iid, inst in self.s["instances"].items():
            out.append({"InstanceId": iid, "ImageId": inst["ImageId"],
                        "InstanceType": inst["InstanceType"], "State": {"Name": inst["State"]["Name"]}})
        return {"Reservations": [{"Instances": out}]}
    def terminate_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "terminated"
        return {"TerminatingInstances": [{"InstanceId": i} for i in InstanceIds]}
    def stop_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "stopped"
        return {"StoppingInstances": [{"InstanceId": i} for i in InstanceIds]}
    def start_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "running"
        return {"StartingInstances": [{"InstanceId": i} for i in InstanceIds]}


class _Bucket:
    def __init__(self, s, name):
        self.s, self.name = s, name
    def create(self):
        if self.name in self.s["buckets"]:
            raise Exception("BucketAlreadyExists: " + self.name)
        self.s["buckets"][self.name] = {}
        return self
    def put_object(self, Key, Body=""):
        if self.name not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + self.name)
        self.s["buckets"][self.name][Key] = str(Body)
        return {"ETag": '"abc"'}


class _Object:
    def __init__(self, s, bucket, key):
        self.s, self.bucket, self.key = s, bucket, key
    def get(self):
        if self.bucket not in self.s["buckets"] or self.key not in self.s["buckets"][self.bucket]:
            raise Exception("NoSuchKey: " + self.key)
        return {"Body": _Body(self.s["buckets"][self.bucket][self.key])}
    def put(self, Body=""):
        if self.bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + self.bucket)
        self.s["buckets"][self.bucket][self.key] = str(Body)
        return {"ETag": '"abc"'}


class _LambdaClient:
    def __init__(self, s):
        self.s = s
    def create_function(self, FunctionName, Runtime="python3.11", Role="", Handler="", Code=None):
        code = ""
        if Code and "ZipFile" in Code:
            zf = Code["ZipFile"]
            code = zf.decode() if isinstance(zf, bytes) else str(zf)
        self.s["lambda_fns"][FunctionName] = {"code": code, "runtime": Runtime, "handler": Handler}
        return {"FunctionArn": "arn:aws:lambda:us-east-1:123456789012:function:" + FunctionName}
    def invoke(self, FunctionName, Payload="{}"):
        fn = self.s["lambda_fns"].get(FunctionName)
        if not fn:
            raise Exception("ResourceNotFoundException: " + FunctionName)
        func = fn["handler"].split(".")[-1]
        code = fn["code"] + chr(10) + "print(" + func + "({}, None))"
        import subprocess, sys as _sys
        r = subprocess.run([_sys.executable, "-c", code], capture_output=True, text=True, timeout=10)
        return {"StatusCode": 200, "Payload": r.stdout}
    def list_functions(self):
        return {"Functions": [{"FunctionName": n} for n in sorted(self.s["lambda_fns"])]}


class _DynamoClient:
    def __init__(self, s):
        self.s = s
    def create_table(self, TableName, KeySchema=None, AttributeDefinitions=None, BillingMode="PAY_PER_REQUEST"):
        self.s["dynamo_tables"].setdefault(TableName, [])
        return {"TableDescription": {"TableName": TableName, "TableStatus": "ACTIVE"}}
    def put_item(self, TableName, Item):
        self.s["dynamo_tables"].setdefault(TableName, []).append(dict(Item))
        return {}
    def get_item(self, TableName, Key):
        for it in self.s["dynamo_tables"].get(TableName, []):
            if all(it.get(k) == v for k, v in Key.items()):
                return {"Item": dict(it)}
        return {}
    def scan(self, TableName):
        items = self.s["dynamo_tables"].get(TableName, [])
        return {"Items": [dict(it) for it in items], "Count": len(items)}
    def list_tables(self):
        return {"TableNames": list(self.s["dynamo_tables"].keys())}


class _DynamoTable:
    def __init__(self, s, name):
        self.s, self.name = s, name
    def put_item(self, Item):
        self.s["dynamo_tables"].setdefault(self.name, []).append(dict(Item))
        return {}
    def get_item(self, Key):
        for it in self.s["dynamo_tables"].get(self.name, []):
            if all(it.get(k) == v for k, v in Key.items()):
                return {"Item": dict(it)}
        return {}
    def scan(self):
        items = self.s["dynamo_tables"].get(self.name, [])
        return {"Items": [dict(it) for it in items], "Count": len(items)}


class _IamClient:
    def __init__(self, s):
        self.s = s
    def create_user(self, UserName):
        if UserName not in self.s["iam_users"]:
            self.s["iam_users"].append(UserName)
        return {"User": {"UserName": UserName}}
    def create_role(self, RoleName, AssumeRolePolicyDocument="{}"):
        self.s["iam_roles"][RoleName] = {"policies": []}
        return {"Role": {"RoleName": RoleName}}
    def create_policy(self, PolicyName, PolicyDocument="{}"):
        arn = "arn:aws:iam::123456789012:policy/" + PolicyName
        self.s["iam_policies"][PolicyName] = arn
        return {"Policy": {"Arn": arn}}
    def attach_role_policy(self, RoleName, PolicyArn):
        if RoleName in self.s["iam_roles"]:
            self.s["iam_roles"][RoleName]["policies"].append(PolicyArn)
        return {}
    def list_users(self):
        return {"Users": [{"UserName": u} for u in sorted(self.s["iam_users"])]}


class _Resource:
    def __init__(self, s):
        self.s = s
    def Bucket(self, name):
        return _Bucket(self.s, name)
    def Object(self, bucket, key):
        return _Object(self.s, bucket, key)
    def Table(self, name):
        return _DynamoTable(self.s, name)


def client(name, **kw):
    s = _get_state()
    if name == "s3":
        return _S3Client(s)
    if name == "ec2":
        return _Ec2Client(s)
    if name == "lambda":
        return _LambdaClient(s)
    if name == "dynamodb":
        return _DynamoClient(s)
    if name == "iam":
        return _IamClient(s)
    raise Exception("UnknownServiceError: " + name)


def resource(name, **kw):
    s = _get_state()
    if name == "s3":
        return _Resource(s)
    if name == "dynamodb":
        return _Resource(s)
    raise Exception("UnknownServiceError: " + name)
'''


def _run_boto3_script(code, state):
    """Run a learner's boto3 script against the simulated AWS state in a
    subprocess, returning (stdout, stderr, new_state)."""
    with tempfile.TemporaryDirectory() as d:
        with open(os.path.join(d, "boto3.py"), "w") as f:
            f.write(_BOTO3_STUB)
        with open(os.path.join(d, "script.py"), "w") as f:
            f.write(code)
        state_path = os.path.join(d, "state.json")
        with open(state_path, "w") as f:
            json.dump(state, f)
        env = dict(os.environ)
        env["PYTHONPATH"] = d + os.pathsep + env.get("PYTHONPATH", "")
        env["BOTO3_STATE"] = state_path
        try:
            r = subprocess.run([sys.executable, os.path.join(d, "script.py")],
                               capture_output=True, text=True, timeout=10,
                               cwd=d, env=env)
        except subprocess.TimeoutExpired:
            return "", "[timed out]", None
        try:
            with open(state_path) as f:
                new_state = json.load(f)
        except Exception:
            new_state = None
        return r.stdout, r.stderr, new_state


# Real-localhost serving is OFF in headless tests (deterministic, no side
# effects) and ON when the app runs for real — `serve <port>` then writes the
# learner's HTML to a live temp dir, starts a real `python3 -m http.server`, and
# opens the browser so they SEE their deployed site.
_LIVE_SERVE = False


class HelmEnv:
    """A tiny offline Helm: package charts and manage releases. `run(rest)`
    behaves like the helm CLI — install / list / upgrade / rollback / uninstall
    — with a per-release revision counter so rollbacks read like real ones."""

    def __init__(self, fs):
        self.fs = fs
        self.releases = {}   # name -> {"chart","version","revision","status"}

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: helm <command>"]
        cmd = parts[0]
        if cmd == "install":
            name = parts[1] if len(parts) > 1 else ""
            if not name:
                return [], ["Error: must either provide a name or specify --generate-name"]
            chart = parts[2] if len(parts) > 2 else "chart"
            self.releases[name] = {"chart": chart, "version": "1.0.0",
                                   "revision": 1, "status": "deployed"}
            return [f"NAME: {name}", "LAST DEPLOYED: just now", "STATUS: deployed",
                    "REVISION: 1"], []
        if cmd in ("list", "ls"):
            if not self.releases:
                return ["NAME  NAMESPACE  REVISION  STATUS  CHART"], []
            out = ["NAME  NAMESPACE  REVISION  STATUS  CHART"]
            for n, r in sorted(self.releases.items()):
                out.append(f"{n}  default  {r['revision']}  {r['status']}  {r['chart']}-{r['version']}")
            return out, []
        if cmd == "upgrade":
            name = parts[1] if len(parts) > 1 else ""
            if name not in self.releases:
                return [], [f"Error: release: not found"]
            r = self.releases[name]
            r["revision"] += 1
            if "--version" in parts:
                r["version"] = parts[parts.index("--version") + 1]
            r["status"] = "deployed"
            return [f"Release \"{name}\" has been upgraded. Happy Helming!"], []
        if cmd == "rollback":
            name = parts[1] if len(parts) > 1 else ""
            if name not in self.releases:
                return [], [f"Error: release: not found"]
            r = self.releases[name]
            r["revision"] += 1
            r["status"] = "deployed"
            return [f"Rollback was a success! Happy Helming!"], []
        if cmd == "uninstall":
            name = parts[1] if len(parts) > 1 else ""
            if name in self.releases:
                del self.releases[name]
                return [f"release \"{name}\" uninstalled"], []
            return [], [f"Error: uninstall: Release not loaded: {name}"]
        if cmd == "status":
            name = parts[1] if len(parts) > 1 else ""
            if name not in self.releases:
                return [], [f"Error: release: not found"]
            r = self.releases[name]
            return [f"NAME: {name}", f"STATUS: {r['status']}", f"REVISION: {r['revision']}"], []
        return [], [f"helm: unknown command '{cmd}'"]


class GitopsEnv:
    """Offline ArgoCD-style GitOps: an app watches the repo; when the repo gets
    a new commit the app drifts OutOfSync, and `argocd app sync` reconciles the
    cluster back to match the repo. `rollback` reverts a revision. The repo IS
    the source of truth — you change git, never the cluster by hand."""

    def __init__(self, fs, git):
        self.fs = fs
        self.git = git
        self.apps = {}   # name -> {"revision": int, "synced_at": commit-count, "history": []}

    def _synced(self, a):
        return len(self.git.commits) <= a["synced_at"]

    def run(self, rest):
        parts = rest.split()
        if not parts or parts[0] != "app":
            return [], ["usage: argocd app <create|list|sync|rollback>"]
        if len(parts) < 2:
            return [], ["usage: argocd app <create|list|sync|rollback>"]
        cmd = parts[1]
        name = parts[2] if len(parts) > 2 else ""
        if cmd == "create":
            self.apps[name] = {"revision": 1, "synced_at": len(self.git.commits),
                               "history": [1]}
            return [f"application '{name}' created — ArgoCD is watching the repo"], []
        if cmd == "list":
            if not self.apps:
                return ["NAME  SYNC STATUS  HEALTH  REVISION"], []
            out = ["NAME  SYNC STATUS  HEALTH  REVISION"]
            for n, a in sorted(self.apps.items()):
                status = "Synced" if self._synced(a) else "OutOfSync"
                out.append(f"{n}  {status:<12} Healthy  {a['revision']}")
            return out, []
        if cmd == "sync":
            if name not in self.apps:
                return [], [f"application '{name}' not found"]
            a = self.apps[name]
            a["synced_at"] = len(self.git.commits)
            a["revision"] += 1
            a["history"].append(a["revision"])
            return [f"application '{name}' synced — cluster now matches the repo"], []
        if cmd == "rollback":
            if name not in self.apps:
                return [], [f"application '{name}' not found"]
            a = self.apps[name]
            a["revision"] = max(1, a["revision"] - 1)
            a["synced_at"] = len(self.git.commits)
            return [f"application '{name}' rolled back to revision {a['revision']}"], []
        return [], [f"argocd app: unknown command '{cmd}'"]


class PromEnv:
    """Offline Prometheus: deterministic metric series + a PromQL subset
    (rate/sum/avg/max/count). `run(rest)` takes the query AFTER 'promql'.
    http_requests_total has a deliberate spike (40→150) so `rate`/`max` read
    like a real incident."""

    def __init__(self, fs):
        self.fs = fs
        self.metrics = {
            "http_requests_total": [10, 12, 11, 15, 40, 90, 120, 150, 45, 30, 28, 25],
            "cpu_usage": [0.1, 0.2, 0.15, 0.85, 0.92, 0.7, 0.3, 0.12],
            "memory_usage_bytes": [1.2e9, 1.3e9, 1.28e9, 1.8e9, 1.9e9, 1.5e9, 1.3e9, 1.25e9],
            "request_latency_seconds": [0.01, 0.02, 0.01, 0.5, 1.8, 0.03, 0.02, 0.02],
        }

    def run(self, rest):
        q = rest.strip()
        if not q:
            return [], ["usage: promql <metric> | rate(<metric>[5m]) | sum|avg|max|count(<metric>)"]
        m = re.match(r'^(\w+)\(([\w:]+)(?:\[(\w+)\])?\)$', q)
        if m:
            fn, metric, window = m.group(1), m.group(2), m.group(3)
            if metric not in self.metrics:
                return [], [f"promql: metric '{metric}' not found"]
            vals = self.metrics[metric]
            if fn == "rate":
                if not window:
                    return [], ["promql: rate needs a range, e.g. rate(metric[5m])"]
                span = {"1m": 60, "5m": 300, "10m": 600, "1h": 3600}.get(window, 300)
                rate = round((max(vals) - min(vals)) / span, 3)
                return [f"rate({metric}[{window}]) = {rate} /s"], []
            if fn == "sum":
                return [f"sum({metric}) = {round(sum(vals), 3)}"], []
            if fn == "avg":
                return [f"avg({metric}) = {round(sum(vals) / len(vals), 3)}"], []
            if fn == "max":
                return [f"max({metric}) = {max(vals)}"], []
            if fn == "count":
                return [f"count({metric}) = {len(vals)}"], []
            return [], [f"promql: unknown function '{fn}' (rate, sum, avg, max, count)"]
        if q in self.metrics:
            out = [f"{q}:"]
            for i, v in enumerate(self.metrics[q]):
                out.append(f"  t{i:02d}  {v}")
            return out, []
        return [], [f"promql: unknown expression '{q}' (try rate/sum/avg/max/count)"]


class CloudLab:
    """One offline 'developer environment': local bash + git + docker + AWS +
    terraform + ansible + CI/CD. `run(cmdline)` executes one line and returns
    (out_lines, err_lines), exactly like ShellFS.run."""

    def __init__(self):
        self.fs = ShellFS()
        self.git = GitRepo(self.fs)
        self.docker = DockerEnv(self.fs)
        self.aws = AwsEnv(self.fs)
        self.tf = TerraformEnv(self.fs)
        self.ansible = AnsibleEnv(self.fs)
        self.pipeline = Pipeline(self.fs)
        self.k8s = K8sEnv(self.fs)
        self.helm = HelmEnv(self.fs)
        self.az = AzEnv(self.fs)
        self.prom = PromEnv(self.fs)
        self.gitops = GitopsEnv(self.fs, self.git)
        self.history = []

    def run(self, cmdline):
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        self.history.append(cmdline)
        cmd = cmdline.split()[0]
        rest = cmdline[len(cmd):].strip()
        if cmd == "git":
            out, err = self.git.run(rest)
            if cmdline.startswith("git commit"):
                # every commit triggers a CI run (the "push to CI" loop)
                self.pipeline._run_pipeline(self.git.commits[-1]["hash"] if self.git.commits else "HEAD")
            return out, err
        if cmd == "docker":
            return self.docker.run(rest)
        if cmd == "aws":
            return self.aws.run(rest)
        if cmd == "az":
            return self.az.run(rest)
        if cmd == "terraform":
            return self.tf.run(rest)
        if cmd in ("ansible-playbook", "ansible"):
            return self.ansible.run(rest)
        if cmd == "kubectl":
            return self.k8s.run(rest)
        if cmd == "helm":
            return self.helm.run(rest)
        if cmd == "promql":
            return self.prom.run(rest)
        if cmd == "trivy":
            return self._trivy(rest)
        if cmd == "argocd":
            return self.gitops.run(rest)
        if cmd == "ci":
            return self.pipeline.run(rest)
        if cmd == "serve":
            return self._serve(rest)
        if cmd == "python3" and self._uses_boto3(cmdline):
            return self._run_boto3(cmdline)
        return self.fs.run(cmdline)

    def _trivy(self, rest):
        """`trivy image <image>` — a container-vulnerability scan. Deterministic:
        images tagged 1.0/old/unpatched report fixed CVEs; anything else scans clean."""
        parts = rest.split()
        if len(parts) < 2 or parts[0] != "image":
            return [], ["usage: trivy image <image>"]
        img = parts[1]
        if re.search(r"(^|:)(1\.0|old|unpatched)(\s|$|:)", img) or ":1.0" in img or ":old" in img:
            return [f"{img}: CRITICAL CVE-2021-44228 (log4shell — RCE)",
                    f"{img}: HIGH   CVE-2022-0778 (openssl — DoS)",
                    f"{img}: HIGH   CVE-2023-1234 (libssl — info leak)",
                    "3 vulnerabilities found"], []
        return [f"{img}: No vulnerabilities found (clean)"], []

    def _serve(self, rest):
        """`serve [port]` — deploy the learner's HTML to a REAL localhost. In the
        live app it writes the .html files to a temp dir, starts a real
        `python3 -m http.server`, and opens the browser; headless tests get the
        same message without the side effects."""
        port = rest.split()[0] if rest.strip() else "8080"
        html = {p.rsplit("/", 1)[-1]: c for p, c in self.fs.files.items() if p.endswith(".html")}
        if not html:
            return [], ["serve: no .html file found — write an index.html first"]
        if not _LIVE_SERVE:
            return [f"Serving http://localhost:{port}",
                    "(simulated — write an index.html and it really serves it)"], []
        try:
            live = Path(tempfile.gettempdir()) / "tutor-live"
            live.mkdir(exist_ok=True)
            for name, content in html.items():
                (live / name).write_text(content)
            prior = getattr(self, "serve_proc", None)
            if prior is not None:
                try:
                    prior.terminate()
                except Exception:
                    pass
            self.serve_proc = subprocess.Popen(
                ["python3", "-m", "http.server", port, "--directory", str(live)],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            subprocess.Popen(["xdg-open", f"http://localhost:{port}"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return [f"Serving http://localhost:{port}",
                    "a browser window should have opened — that's your site, live."], []
        except Exception as e:
            return [], [f"serve: {e}"]

    def _uses_boto3(self, cmdline):
        parts = cmdline.split()
        if len(parts) < 2:
            return False
        p = self.fs._resolve(parts[1])
        return p in self.fs.files and "boto3" in self.fs.files[p]

    def _run_boto3(self, cmdline):
        parts = cmdline.split()
        p = self.fs._resolve(parts[1])
        code = self.fs.files[p]
        state = {"buckets": self.aws.buckets, "instances": self.aws.instances,
                 "next_inst": self.aws.next_inst,
                 "lambda_fns": self.aws.lambda_fns,
                 "dynamo_tables": self.aws.dynamo_tables,
                 "iam_users": sorted(self.aws.iam_users),
                 "iam_roles": self.aws.iam_roles,
                 "iam_policies": self.aws.iam_policies}
        stdout, stderr, new_state = _run_boto3_script(code, state)
        if new_state is not None:
            self.aws.buckets = new_state["buckets"]
            self.aws.instances = new_state["instances"]
            self.aws.next_inst = new_state["next_inst"]
            self.aws.lambda_fns = new_state["lambda_fns"]
            self.aws.dynamo_tables = new_state["dynamo_tables"]
            self.aws.iam_users = set(new_state["iam_users"])
            self.aws.iam_roles = new_state["iam_roles"]
            self.aws.iam_policies = new_state["iam_policies"]
        out = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        err = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return out, err


# Each lesson = one real command the learner types (or "info" read-along, or a
# "challenge" with no ghost hint).
#   expect    — exact command(s) that count as correct (whitespace-normalised)
#   verify    — optional callable(cmd) -> bool (when quotes make exact match brittle)
#   verify_fs — optional callable(fs) -> bool (challenges: check the filesystem)
#   cmd_hint  — the exact command (the ghost + the "here's the answer" hint)
#   goal      — what to do (on-screen, plain english)
#   say       — the spoken instruction (plain english, NEVER spells the command)
#   why       — the plain-english meaning (TTS reads this too)
#   on_win    — TTS celebration that points out the thing the user just made
