def _cmd_tokens(s):
    """Split a command line into tokens, PRESERVING quotes (echo "a b" stays one
    token that keeps its quotes, so the on-screen command is exactly right)."""
    toks = []
    cur = ""
    q = None
    for ch in s:
        if q:
            cur += ch
            if ch == q:
                q = None
        elif ch in "'\"":
            q = ch
            cur += ch
        elif ch.isspace():
            if cur:
                toks.append(cur)
                cur = ""
        else:
            cur += ch
    if cur:
        toks.append(cur)
    return toks


def _explain_tokens(cmdline):
    """Split a command line into classified, explained tokens.

    Returns a list of dicts: {token, kind, brief, detail, color}. `kind` is
    program|verb|flag|value. `token` keeps its original quoting; classification
    and curated lookups use the quote-stripped `core`.
    """
    raw = _cmd_tokens(cmdline)
    if not raw:
        return []
    prog = raw[0].strip("'\"")
    entry = CMD_EXPLAIN.get(prog, {})
    tokens = []
    for i, tok in enumerate(raw):
        core = tok.strip("'\"")
        if i == 0:
            kind = "program"
        elif core.startswith("--") or (core.startswith("-") and len(core) > 1):
            kind = "flag"
        elif i == 1 and core in entry.get("verbs", {}):
            # the immediate subcommand (docker build, git commit, aws s3)
            kind = "verb"
        elif core in entry.get("verbs_verb", {}):
            # a nested action (aws s3 mb, az vm create)
            kind = "verb"
        else:
            kind = "value"
        brief, detail = _explain_entry(prog, entry, core, kind, i)
        tokens.append({"token": tok, "kind": kind, "brief": brief,
                       "detail": detail, "color": _EXPLAIN_COLORS[kind]})
    return tokens


def _explain_entry(prog, entry, tok, kind, i):
    """Resolve (brief, detail) for one token — curated first, generic fallback."""
    if kind == "program":
        brief = entry.get("summary", f"{prog} is a command-line tool.")
        return brief, brief
    if kind == "flag":
        f = entry.get("flags", {}).get(tok)
        if f:
            return f if isinstance(f, tuple) else (f, "")
        brief = f"{tok} — a flag that changes how {prog} behaves."
        return brief, f"Flags are options you add to tweak what {prog} does. This one is specific to {prog}."
    if kind == "verb":
        v = entry.get("verbs", {}).get(tok) or entry.get("verbs_verb", {}).get(tok)
        if v:
            return v if isinstance(v, tuple) else (v, "")
        brief = f"{tok} — an action {prog} can perform."
        return brief, f"{tok} is the operation: it tells {prog} what to do."
    # value
    brief = f"{tok} — the thing {prog} acts on."
    detail = (f"This is an argument {prog} uses — a name, path, or value. "
              f"What it means depends on the {prog} command you ran.")
    return brief, detail


# =========================================================================== #
# PYTHON EXPLAINER — breaks Python code into keyword/builtin/name/string tokens
# with a clickable manual. `PY_EXPLAIN` is the curated knowledge base; the
# tokenizer uses the stdlib `tokenize` module for exact token boundaries.
# =========================================================================== #

_PY_COLORS = {"keyword": "#f87171", "builtin": "#86efac", "name": "#7dd3fc",
              "string": "#fbbf24", "number": "#c084fc", "op": "#8b949e"}
_PY_KIND_LABEL = {"keyword": "a keyword", "builtin": "a built-in",
                  "name": "a name / variable", "string": "a string",
                  "number": "a number", "op": "an operator / punctuation"}

