def _net_lab_device(spec: dict) -> NetDevice:
    """A fresh NetDevice wired exactly like the lab spec."""
    d = NetDevice()
    d.ifaces = {k: dict(v) for k, v in spec["ifaces"].items()}
    d.routes = list(spec.get("routes", []))
    d.forwarding = spec.get("forwarding", False)
    d.rules = list(spec.get("rules", []))
    return d


# grouped modules for the picker: (name, first_topic, count)
NET_MODULES = []
for _ni, _nt in enumerate(NET_TOPICS):
    _lv = NET_LEVELS[_nt[0]]
    if not NET_MODULES or NET_MODULES[-1]["name"] != _lv:
        NET_MODULES.append({"name": _lv, "first": _ni, "count": 0})
    NET_MODULES[-1]["count"] += 1
# the labs sit at the end of the course, one per level
NET_MODULES.append({"name": "NETWORK LABS", "first": len(NET_TOPICS),
                    "count": len(NET_LABS)})
# EXTRA DRILLS: a repeatable session that re-asks everything you've learned —
# TTS reads question AND answers, wrong answers are retrained instantly and
# come back three more times at random spots, explained differently each time.
NET_MODULES.append({"name": "EXTRA DRILLS", "first": len(NET_TOPICS),
                    "count": 1})
# TODAY'S REVIEW: the spaced-repetition queue — every concept you've answered
# gets a due date (right answers push it days ahead, wrong answers bring it
# back tomorrow).  This module asks whatever is due today.
NET_MODULES.append({"name": "TODAY'S REVIEW", "first": len(NET_TOPICS),
                    "count": 1})


def net_checkpoint_label(p: dict) -> str:
    """One-line 'where am I' for the NETWORK+ resume display."""
    if p.get("net_course_done"):
        return "NETWORK+ — course complete"
    m = p.get("net_module")
    if not isinstance(m, int) or not (0 <= m < len(NET_MODULES)):
        return ""
    name = NET_MODULES[m]["name"]
    if m >= 4:
        return f"NETWORK+ · {name}"
    ti = p.get("net_topic", 0)
    if m < 3:
        topics = [t for t in NET_TOPICS if t[0] == m]
        if 0 <= ti < len(topics):
            return f"NETWORK+ · {name} · {topics[ti][2]}"
    return f"NETWORK+ · {name}"


# Post-ghost vim edit warm-up: a short run of real edits the user must perform in
# the ACTUAL editor (not the demo buffer) so the motions they just learned get
# exercised right before the Python challenge. Each task starts from the same
# base buffer and is done when its verify() sees the edit.
def _build_warmup_tasks(starter: str) -> list[dict]:
    """Build a short, ramping vim-edit warm-up FROM the challenge's own starter
    code, so the practice is directly relevant (you edit the exact lines you're
    about to write) instead of an unrelated scratch buffer. Lightest edit first,
    heavier after — so the warm-up itself ramps like the rest of the course.
    Returns a list of {title, instruction, verify}; empty if there's nothing
    to edit (an empty-starter challenge skips the warm-up cleanly)."""
    lines = [l for l in (starter or "").rstrip("\n").split("\n") if l.strip() != ""]
    if not lines:
        return []
    if len(lines) >= 2:
        first, last = lines[0], lines[-1]
        return [
            # 1 — LIGHT: the cursor is already on the first line; one dd, done.
            {"title": "delete the first line",
             "instruction": "the cursor is on the first line — press dd to delete it",
             "verify": lambda b, first=first: first not in b},
            # 2 — MEDIUM: navigate to the last line, then duplicate it.
            {"title": "duplicate the last line",
             "instruction": "jump to the last line with G, then press yy and p",
             "verify": lambda b, last=last: sum(1 for l in b if l == last) >= 2},
            # 3 — HEAVY: open a fresh line and type a comment.
            {"title": "add a comment",
             "instruction": "press o (opens a line below), type # then any words (e.g. # done), press Esc",
             "verify": lambda b: any(l.strip().startswith("#") for l in b)},
        ]
    line = lines[0]
    return [
        # single-line starter: duplicate it, then annotate it.
        {"title": "duplicate the line",
         "instruction": "copy this line down — press yy then p",
         "verify": lambda b, line=line: sum(1 for l in b if l == line) >= 2},
        {"title": "add a comment",
         "instruction": "press o (opens a line below), type # then any words (e.g. # done), press Esc",
         "verify": lambda b: any(l.strip().startswith("#") for l in b)},
    ]

_VIM_DIR = {"h": "←", "l": "→", "j": "↓", "k": "↑", "w": "→", "b": "←",
            "e": "→", "0": "←", "$": "→", "^": "←", "g": "↑", "G": "↓"}


def _vim_arrow(keys):
    """The direction arrow for a lesson's FIRST motion key (blinking cue)."""
    for k in keys:
        if k in _VIM_DIR:
            return _VIM_DIR[k]
        if k == "gg":
            return "↑"
    return ""


class VimDemoBuffer:
    """A tiny text buffer that actually MOVES and EDITS as the ghost dictates,
    so the trainer shows the real effect of each key instead of a static flashcard."""

    def __init__(self, lines):
        self.lines = list(lines)
        self.row = 0
        self.col = 0
        self.yank = ""
        self.undo = []

    def _clamp(self):
        self.row = max(0, min(len(self.lines) - 1, self.row))
        self.col = max(0, min(len(self.lines[self.row]), self.col))

    def _save(self):
        self.undo.append((list(self.lines), self.row, self.col))

    def _flat_pos(self, r, c):
        return sum(len(self.lines[i]) + 1 for i in range(r)) + c

    def _from_flat(self, pos):
        pos = max(0, pos)
        for r, line in enumerate(self.lines):
            if pos <= len(line):
                return r, pos
            pos -= len(line) + 1
        r = len(self.lines) - 1
        return r, len(self.lines[r])

    def _word_fwd(self):
        flat = "\n".join(self.lines)
        i = self._flat_pos(self.row, self.col)
        n = len(flat)
        if i >= n:
            return
        # skip current word, then spaces, land on next non-space
        while i < n and flat[i] != "\n" and not flat[i].isspace():
            i += 1
        while i < n and flat[i] != "\n" and flat[i].isspace():
            i += 1
        self.row, self.col = self._from_flat(i)
        self._clamp()

    def _word_back(self):
        flat = "\n".join(self.lines)
        i = self._flat_pos(self.row, self.col) - 1
        while i >= 0 and flat[i] != "\n" and flat[i].isspace():
            i -= 1
        while i >= 0 and flat[i] != "\n" and not flat[i].isspace():
            i -= 1
        self.row, self.col = self._from_flat(i + 1)
        self._clamp()

    def _word_end(self):
        flat = "\n".join(self.lines)
        i = self._flat_pos(self.row, self.col)
        n = len(flat)
        while i < n and flat[i] != "\n" and flat[i].isspace():
            i += 1
        while i + 1 < n and flat[i + 1] != "\n" and not flat[i + 1].isspace():
            i += 1
        self.row, self.col = self._from_flat(i)
        self._clamp()

    def apply(self, seq):
        """Apply a completed key sequence. Returns a short message or None."""
        s = tuple(seq)
        if s == ("h",):
            self._save(); self.col -= 1; self._clamp(); return None
        if s == ("l",):
            self._save(); self.col += 1; self._clamp(); return None
        if s == ("j",):
            self._save(); self.row += 1; self._clamp(); return None
        if s == ("k",):
            self._save(); self.row -= 1; self._clamp(); return None
        if s == ("w",):
            self._save(); self._word_fwd(); return None
        if s == ("b",):
            self._save(); self._word_back(); return None
        if s == ("e",):
            self._save(); self._word_end(); return None
        if s == ("0",):
            self._save(); self.col = 0; return None
        if s == ("$",):
            self._save(); self.col = max(0, len(self.lines[self.row]) - 1); return None
        if s == ("^",):
            self._save(); self.col = len(self.lines[self.row]) - len(self.lines[self.row].lstrip()); return None
        if s == ("g", "g"):
            self._save(); self.row = 0; self.col = 0; return None
        if s == ("G",):
            self._save(); self.row = len(self.lines) - 1; self.col = 0; return None
        if s == ("5", "j"):
            self._save(); self.row += 5; self._clamp(); return None
        if s == ("x",):
            self._save()
            line = self.lines[self.row]
            if self.col < len(line):
                self.lines[self.row] = line[:self.col] + line[self.col + 1:]
                self._clamp()
            return None
        if s == ("d", "d"):
            self._save()
            if len(self.lines) > 1:
                del self.lines[self.row]
            else:
                self.lines[self.row] = ""
            self._clamp()
            return None
        if s == ("d", "w"):
            self._save()
            start = self._flat_pos(self.row, self.col)
            self._word_fwd()
            end = self._flat_pos(self.row, self.col)
            flat = "\n".join(self.lines)
            flat = flat[:start] + flat[end:]
            self.lines = flat.split("\n")
            self.row, self.col = self._from_flat(start)
            self._clamp()
            return None
        if s in (("d", "$"), ("D",)):
            self._save()
            self.lines[self.row] = self.lines[self.row][:self.col]
            self._clamp()
            return None
        if s == ("y", "y"):
            self.yank = self.lines[self.row]
            return "yanked the line"
        if s == ("y", "w"):
            start = self._flat_pos(self.row, self.col)
            self._word_fwd()
            end = self._flat_pos(self.row, self.col)
            self.yank = "\n".join(self.lines)[start:end]
            self.row, self.col = self._from_flat(start)
            return "yanked the word"
        if s == ("y", "$"):
            self.yank = self.lines[self.row][self.col:]
            return "yanked to end of line"
        if s in (("p",), ("P",)):
            if not self.yank:
                return "nothing to paste — yank first"
            self._save()
            target = self.row + 1 if s == ("p",) else self.row
            self.lines.insert(target, self.yank)
            self.row = target; self.col = 0
            return "pasted"
        if s == ("y", "y", "p"):
            if not self.yank:
                self.yank = self.lines[self.row]
            self._save()
            self.lines.insert(self.row + 1, self.yank)
            self.row += 1; self.col = 0
            return "duplicated the line"
        if s == ("u",):
            if self.undo:
                self.lines, self.row, self.col = self.undo.pop()
                self._clamp()
                return "undid"
            return "nothing to undo"
        return None  # flashcard lessons — no buffer effect

    def clone(self):
        b = VimDemoBuffer(list(self.lines))
        b.row, b.col = self.row, self.col
        b.yank = self.yank
        b.undo = list(self.undo)
        return b

    def predict(self, seq):
        """(row, col) the cursor would land on after `seq`, without mutating —
        used to show a 'you'll jump here' ghost before the key is pressed."""
        b = self.clone()
        b.apply(list(seq))
        return (b.row, b.col)


class DevVimBuffer:
    """A real-enough vim buffer for the DevOps 'write' lessons. The learner
    `touch`es the file in bash, then `nvim`s into it here: INSERT mode types the
    file, NORMAL mode (Esc) moves with hjkl, and `:wq` saves & quits."""

    def __init__(self, target):
        self.target = target.rstrip("\n")   # the exact file we verify against
        self.lines = [""]                   # the learner's typed buffer
        self.row = 0
        self.col = 0
        self.mode = "insert"                # insert / normal / cmd
        self.cmd = ""                       # the ':' command text
        self.msg = ""                       # status line

    def get_text(self):
        return "\n".join(self.lines)

    def matches(self):
        """Lenient: trailing whitespace and blank lines (anywhere) don't block a
        save — an extra empty line doesn't ruin the file. Content + indentation
        still have to match."""
        def norm(s):
            return [ln.rstrip() for ln in s.split("\n") if ln.strip()]
        return norm(self.get_text()) == norm(self.target)

    def _clamp(self):
        self.row = max(0, min(len(self.lines) - 1, self.row))
        self.col = max(0, min(len(self.lines[self.row]), self.col))

    # ---- insert mode ----------------------------------------------------- #
    def type_char(self, ch):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col] + ch + line[self.col:]
        self.col += 1

    def newline(self):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col]
        self.lines.insert(self.row + 1, line[self.col:])
        self.row += 1
        self.col = 0

    def backspace(self):
        if self.col > 0:
            line = self.lines[self.row]
            self.lines[self.row] = line[:self.col - 1] + line[self.col:]
            self.col -= 1
        elif self.row > 0:
            prev = self.lines[self.row - 1]
            self.col = len(prev)
            self.lines[self.row - 1] = prev + self.lines[self.row]
            del self.lines[self.row]
            self.row -= 1

    def indent(self):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col] + "    " + line[self.col:]
        self.col += 4

    # ---- normal mode ----------------------------------------------------- #
    def move(self, d):
        if d == "h":
            self.col -= 1
        elif d == "l":
            self.col += 1
        elif d == "j":
            self.row += 1
        elif d == "k":
            self.row -= 1
        self._clamp()

    def to_insert(self, after=False):
        if after and self.col < len(self.lines[self.row]):
            self.col += 1
        self.mode = "insert"

    def delete_char(self):
        line = self.lines[self.row]
        if self.col < len(line):
            self.lines[self.row] = line[:self.col] + line[self.col + 1:]

    def delete_line(self):
        if len(self.lines) > 1:
            del self.lines[self.row]
        else:
            self.lines[self.row] = ""
        self._clamp()

    # ---- command mode ---------------------------------------------------- #
    def start_cmd(self):
        self.mode = "cmd"
        self.cmd = ""

    def cmd_type(self, ch):
        self.cmd += ch

    def cmd_backspace(self):
        self.cmd = self.cmd[:-1]

    def cmd_execute(self):
        """Run the ':' command. Returns the command word ('wq','q!','w','q','x')
        or None for an unknown command (message is set on the buffer)."""
        cmd = self.cmd.strip()
        self.cmd = ""
        self.mode = "normal"
        if cmd in ("wq", "x"):
            return "wq"
        if cmd in ("q!", "w", "q"):
            return cmd
        self.msg = f"E492: Not an editor command: {cmd}"
        return None


