class VolumeBar(Static):
    """Docked bottom volume faders: two rows — VOICE (TTS) and SFX (keyboard /
    win-fail sounds) — each with its own mute toggle and clickable level meter.

    Click an icon to mute that channel, click a meter to jump to a level, or use
    the keyboard: ↑/↓ (k/j) switch the active row, ←/→ (h/l) nudge it, m/space
    mutes it. The app auto-closes the bar after a few idle seconds."""

    can_focus = True
    METER_W = 20   # meter width in terminal cells
    ICON_X = 2     # column where the (♪)/(✕) icon starts
    METER_X = 6    # column where the meter starts
    MINUS_X = 32   # [-] button
    PLUS_X = 35    # [+] button

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._active = 0   # 0 = voice row, 1 = sfx row

    def _row_markup(self, row: int, active: bool) -> str:
        if row == 0:
            vol, muted, label = _VOICE_VOL, _VOICE_MUTED, "VOICE"
        elif row == 1:
            vol, muted, label = _SFX_VOL, _SFX_MUTED, "SFX"
        elif row == 2:
            vol, muted, label = _WRITE_VOL, _WRITE_MUTED, "WRITE"
        elif row == 3:
            vol, muted, label = _KEY_VOL, _KEY_MUTED, "KEYS"
        else:
            vol, muted, label = _ANIM_VOL, _ANIM_MUTED, "ANIM"
        filled = int(round(vol * self.METER_W))
        meter = ("█" * filled) + ("░" * (self.METER_W - filled))
        if muted:
            icon = "[bold red](✕)[/]"
            meter = f"[dim]{meter}[/]"
        else:
            icon = "[bold #7dd3fc](♪)[/]"
        pct = f"{int(round(vol * 100)):3d}%"
        marker = "[bold #7dd3fc]>[/]" if active else " "
        minus = "[bold #f9a8d4 on #2a1a1a](-)[/]"
        plus = "[bold #a3f7bf on #1a2a1a](+)[/]"
        return f"{marker} {icon} {meter} [bold]{pct}[/] {minus}{plus} [dim]{label}[/]"

    def _bar_markup(self) -> str:
        voice = self._row_markup(0, self._active == 0)
        sfx = self._row_markup(1, self._active == 1)
        write = self._row_markup(2, self._active == 2)
        keys = self._row_markup(3, self._active == 3)
        anim = self._row_markup(4, self._active == 4)
        hint = "[dim]click ♪ to mute · click meter to jump · [-] [+] to nudge · F4 close[/]"
        return f"{voice}\n{sfx}\n{write}\n{keys}\n{anim}\n{hint}"

    def repaint(self) -> None:
        """Repaint both faders from the current voice/sfx globals."""
        self.update(Text.from_markup(self._bar_markup()))

    def _row_vol(self, row: int) -> float:
        return (_VOICE_VOL if row == 0
                else (_SFX_VOL if row == 1
                      else (_WRITE_VOL if row == 2
                            else (_KEY_VOL if row == 3 else _ANIM_VOL))))

    def _set_row_vol(self, row: int, vol: float) -> None:
        if row == 0:
            set_voice_volume(vol); set_voice_mute(False)
        elif row == 1:
            set_sfx_volume(vol); set_sfx_mute(False)
        elif row == 2:
            set_writing_volume(vol)
            if _WRITE_MUTED:
                toggle_writing_mute()
        elif row == 3:
            set_key_volume(vol)
            if _KEY_MUTED:
                toggle_key_mute()
        else:
            set_anim_volume(vol)
            if _ANIM_MUTED:
                toggle_anim_mute()

    def _toggle_row_mute(self, row: int) -> None:
        if row == 0:
            toggle_voice_mute()
        elif row == 1:
            toggle_sfx_mute()
        elif row == 2:
            toggle_writing_mute()
        elif row == 3:
            toggle_key_mute()
        else:
            toggle_anim_mute()

    def on_click(self, event: events.Click) -> None:
        event.stop()
        x, y = event.x, event.y
        row = 0 if y <= 0 else (1 if y == 1 else (2 if y == 2 else (3 if y == 3 else 4)))
        if self.ICON_X <= x <= self.ICON_X + 2:
            self._toggle_row_mute(row)
        elif self.METER_X <= x < self.METER_X + self.METER_W:
            self._set_row_vol(row, (x - self.METER_X + 0.5) / self.METER_W)
        elif self.MINUS_X <= x <= self.MINUS_X + 2:
            self._set_row_vol(row, self._row_vol(row) - 0.05)
        elif self.PLUS_X <= x <= self.PLUS_X + 2:
            self._set_row_vol(row, self._row_vol(row) + 0.05)
        else:
            return
        self.app._volume_changed(self)

    def on_key(self, event: events.Key) -> None:
        k = event.key
        if k in ("up", "k"):
            self._active = (self._active - 1) % 5
        elif k in ("down", "j"):
            self._active = (self._active + 1) % 5
        elif k in ("left", "h"):
            self._set_row_vol(self._active, self._row_vol(self._active) - 0.05)
        elif k in ("right", "l"):
            self._set_row_vol(self._active, self._row_vol(self._active) + 0.05)
        elif k in ("m", "space"):
            self._toggle_row_mute(self._active)
        else:
            return
        event.stop()
        self.app._volume_changed(self)


