    def on_mount(self):
        self.title = "tutor"
        self.sub_title = "learn Python like it's nvim"
        self.query_one("#topbar", Static).update(
            f"[bold]tutor[/]  ·  LVL {level_for(self.p['xp'])} [yellow]{self.p['xp']} XP[/]"
        )
        self._set_resume_sel()
        self._show_menu()
        if self.voice_on:
            # pre-warm the piper voice in the background while the menu is up,
            # so the first utterance has no model-load delay
            threading.Thread(target=_warmup_server, daemon=True).start()

    # ---- menu -------------------------------------------------------------- #

    def _menu_items(self):
        """Flat list of (group_idx, challenge_idx) in display order."""
        items = []
        for gi, g in enumerate(GROUPS):
            for ci in range(len(g["challenges"])):
                items.append((gi, ci))
        return items

    def _set_resume_sel(self):
        items = self._menu_items()
        idx = None
        if self.p.get("last"):
            for i, (gi, ci) in enumerate(items):
                if GROUPS[gi]["challenges"][ci]["title"] == self.p["last"]:
                    idx = i
                    break
        if idx is None:
            for i, (gi, ci) in enumerate(items):
                st = challenge_stat(self.p, GROUPS[gi]["challenges"][ci]["title"])
                if st["right"] == 0 and st["wrong"] == 0:
                    idx = i
                    break
        if idx is None:
            idx = 0
        gi, ci = items[idx]
        self.series_sel = gi
        self.menu_sel = ci

    def _show_menu(self):
        self.mode = "menu"
        self.menu_level = "series"
        self._stop_demo_timers()
        self._stop_ex_anim()
        self._cancel_celebrate()
        self._cancel_cat()
        self.query_one("#confetti", Confetti).dismiss()
        self.query_one("#gate", Static).remove_class("visible")
        for w in ("#menu-banner", "#menu-body", "#menu-help"):
            self.query_one(w).remove_class("hidden")
        for w in ("#body", "#guide", "#status"):
            self.query_one(w).add_class("hidden")
        self._render_menu()
        self._sync_settings_checkboxes()
        self._sync_name_field()
        self._sync_back_button()
        self._start_menu_anim()

    def _show_challenge(self):
        self.mode = "challenge"
        self._stop_menu_anim()
        for w in ("#menu-banner", "#menu-body", "#menu-help"):
            self.query_one(w).add_class("hidden")
        for w in ("#body", "#guide", "#status"):
            self.query_one(w).remove_class("hidden")
        self._sync_back_button()

    def _sync_back_button(self):
        """Show the ← button anywhere there's a level to go back to; hide it on
        the top-level series menu (there's nothing to go back to there)."""
        show = self.mode == "challenge" or (
            self.mode == "menu"
            and self.menu_level in ("challenges", "dev_modules", "net_modules"))
        btn = self.query_one("#back-btn", BackButton)
        if show:
            btn.remove_class("hidden")
        else:
            btn.add_class("hidden")

    def _sync_continue_button(self):
        """The CONTINUE button unlocks only after a challenge is completed —
        completion never auto-advances, so the student moves on when ready."""
        show = (self.mode == "challenge" and self.started and self.last == "pass")
        try:
            btn = self.query_one("#task-continue", Button)
            if show:
                btn.remove_class("hidden")
            else:
                btn.add_class("hidden")
        except Exception:
            pass

    def _render_menu(self):
        self.query_one("#menu-banner", Static).update(self._banner_text())
        self._render_progress()
        self._sync_back_button()
        # a NEW screen (level change) climbs the list back to the very top
        new_screen = self.menu_level != self._last_menu_level
        self._last_menu_level = self.menu_level
        if self.menu_level == "series":
            self._render_series_list()
        elif self.menu_level == "dev_modules":
            self._render_dev_module_list()
        elif self.menu_level == "net_modules":
            self._render_net_module_list()
        else:
            self._render_challenge_list()
        if new_screen:
            try:
                self.query_one("#menu-list", VerticalScroll).scroll_to(
                    y=0, animate=False)
            except Exception:
                pass
        self._render_menu_preview()
        self._render_menu_help()

    # ---- progress --------------------------------------------------------- #

    def _overall_progress(self):
        total = sum(len(g["challenges"]) for g in GROUPS)
        done = sum(1 for g in GROUPS for c in g["challenges"]
                   if challenge_stat(self.p, c["title"])["right"] > 0)
        return done, total

    def _group_progress(self, gi):
        g = GROUPS[gi]
        total = len(g["challenges"])
        done = sum(1 for c in g["challenges"]
                   if challenge_stat(self.p, c["title"])["right"] > 0)
        return done, total

    def _bar_text(self, done, total, width=18):
        t = Text()
        fill = round(done / total * width) if total else 0
        t.append("▰" * fill, style="green")
        t.append("▱" * (width - fill), style="#333333")
        return t

    def _clip(self, s, w):
        """Truncate with an ellipsis so menu rows never wrap or break."""
        if len(s) <= w:
            return s
        return s[: max(0, w - 1)] + "…"

    # ---- curriculum map ------------------------------------------------- #
    def action_map(self):
        """g — open/close the whole-journey map (from the menu)."""
        if self._map_visible:
            self._hide_map()
        elif self.mode == "menu":
            self._show_map()

    def _show_map(self):
        self._map_visible = True
        self.query_one("#map", Static).update(self._render_map())
        self.query_one("#map", Static).add_class("visible")

    def _hide_map(self):
        self._map_visible = False
        self.query_one("#map", Static).remove_class("visible")
        self._render_menu()

    # ---- Ctrl+Enter JUMP navigator ------------------------------------- #
    # A hidden dev/testing screen: hop straight into any course or any
    # challenge (1-15) without walking the normal flow.

    def action_jump(self):
        if self._jump_visible:
            self._hide_jump()
        else:
            self._show_jump()

    # ---- profile popout (blue ◉ in the corner) ---------------------------- #
    def action_profile(self):
        """Toggle the name/settings popout — reachable from any screen."""
        if self._profile_visible:
            self._hide_profile()
        else:
            self._show_profile()

    def _show_profile(self):
        self._profile_visible = True
        self._sync_profile()
        self.query_one("#profile-popout").add_class("visible")

    def _hide_profile(self):
        self._profile_visible = False
        self.query_one("#profile-popout").remove_class("visible")

    def _sync_profile(self):
        name = (self.p.get("name") or "").strip() or "no name set"
        self.query_one("#profile-popout-title", Static).update(
            Text(f"PROFILE — {name}", style="bold #7dd3fc"))
        self.query_one("#profile-name-hint", Static).update(
            Text("save your name for the tutor to greet you", style="dim"))

    def _show_jump(self):
        self._jump_visible = True
        self._jump_level = 0
        self._jump_sel = max(0, self.series_sel if self.series_sel >= 0 else 0)
        self.query_one("#jump", Static).update(self._render_jump())
        self.query_one("#jump", Static).add_class("visible")

    def _hide_jump(self):
        self._jump_visible = False
        self.query_one("#jump", Static).remove_class("visible")
        if self.mode == "menu":
            self._render_menu()

    def _render_jump(self):
        t = Text()
        w = max(60, self.size.width - 8)
        title = "◤  JUMP  ◥"
        t.append(" " * max(0, (w - len(title)) // 2))
        t.append(title, style="bold magenta")
        t.append("\n\n")
        if self._jump_level == 0:
            t.append("pick a course:\n\n", style="dim")
            for gi, g in enumerate(GROUPS):
                mark = "▶" if gi == self._jump_sel else " "
                style = "bold #f0f0f5" if gi == self._jump_sel else "#c8c8d0"
                t.append(f" {mark} {g['name'].upper()}  ({len(g['challenges'])} challenges)",
                         style=style)
                t.append("\n")
            t.append("\nj/k move   Enter pick   Esc close   Ctrl+Enter close",
                     style="dim")
        else:
            g = GROUPS[self._jump_course]
            t.append(g["name"].upper() + "\n\n", style="bold #7dd3fc")
            for ci, ch in enumerate(g["challenges"]):
                mark = "▶" if ci == self._jump_sel else " "
                style = "bold #f0f0f5" if ci == self._jump_sel else "#c8c8d0"
                t.append(f" {mark} {ci + 1:>2}. {ch['title']}", style=style)
                t.append("\n")
            t.append("\nj/k move   Enter jump   Esc back", style="dim")
        return t

    def _jump_move(self, delta):
        if self._jump_level == 0:
            self._jump_sel = (self._jump_sel + delta) % len(GROUPS)
        else:
            n = len(GROUPS[self._jump_course]["challenges"])
            self._jump_sel = (self._jump_sel + delta) % n
        play_menu_blip(0)
        self.query_one("#jump", Static).update(self._render_jump())

    def _jump_enter(self):
        if self._jump_level == 0:
            self._jump_course = self._jump_sel
            self._jump_level = 1
            self._jump_sel = 0
            play_menu_blip(2)
            self.query_one("#jump", Static).update(self._render_jump())
        else:
            self._jump_to(self._jump_course, self._jump_sel)

    def _jump_back(self):
        if self._jump_level == 1:
            self._jump_level = 0
            self.query_one("#jump", Static).update(self._render_jump())
        else:
            self._hide_jump()

    def _jump_to(self, gi, ci):
        """Hop straight into challenge ci of course gi (for testing)."""
        self._hide_jump()
        self.series_sel = gi
        self.group_idx = gi
        self.ch_idx = ci
        self.menu_sel = ci
        self.p["last"] = self._current()["title"]
        save_progress(self.p)
        self.started = True
        self._show_challenge()
        self._render_challenge()

    def _render_map(self):
        w = max(64, self.size.width - 8)
        t = Text()
        title = "◤  YOUR JOURNEY  ◥"
        t.append(" " * max(0, (w - len(title)) // 2))
        t.append(title, style="bold magenta")
        t.append("\n\n")
        # ---- the four big tracks -----------------------------------------
        t.append("THE BIG TRACKS\n", style="bold #facc15")
        dev_step = self.p.get("dev_step", 0) if isinstance(self.p.get("dev_step"), int) else 0
        dev_done = dev_step >= len(DEV_LESSONS)
        build_step = self.p.get("build_step", 0) if isinstance(self.p.get("build_step"), int) else 0
        build_done = build_step >= len(SHELL_LESSONS)
        net_done = bool(self.p.get("net_course_done"))
        vim_done = self._vim_done

        def _track(name, done, total, color, note=""):
            row = Text()
            row.append("  " + name, style=f"bold {color}")
            row.append(" " * max(0, 24 - len(name)))
            row.append_text(self._bar_text(done, total, 18))
            row.append(f" {done}/{total}" if total > 1 else " " * 6)
            if done >= total and total > 0:
                row.append("  ✓", style="bold green")
            if note:
                row.append("  " + note, style="dim")
            row.append("\n")
            return row

        t.append_text(_track("CLOUD & DEVOPS", dev_step, len(DEV_LESSONS), "#7dd3fc",
                             "resume: " + (self._dev_checkpoint_label() if not dev_done else "done")))
        t.append_text(_track("BUILD STUFF", build_step, len(SHELL_LESSONS), "#7ee787"))
        t.append_text(_track("NETWORK+", 1 if net_done else 0, 1, "#ffa657",
                             "5 modules · 563 questions" if not net_done else "done"))
        t.append_text(_track("VIM / NEOVIM", 1 if vim_done else 0, 1, "#d8b4fe"))
        t.append("\n")
        # ---- the python path --------------------------------------------
        t.append("PYTHON PATH\n", style="bold #facc15")
        for gi, g in enumerate(GROUPS):
            done, total = self._group_progress(gi)
            t.append_text(_track(g["name"], done, total, "#f9a8d4"))
        # ---- footer -----------------------------------------------------
        py_done, py_total = self._overall_progress()
        due = len(self._py_due_topics())
        streak = self.p.get("streak", 0)
        t.append("\n")
        f = Text()
        f.append(f"  python {py_done}/{py_total}  ·  {due} due today  ·  streak {streak}",
                 style="bold #cdd6f4")
        f.append("\n\n")
        f.append("  Enter / Esc — back to the menu", style="dim")
        t.append_text(f)
        return t

    def _render_progress(self):
        done, total = self._overall_progress()
        pct = round(done / total * 100) if total else 0
        width = max(12, self.size.width - 28)
        fill = round(done / total * width) if total else 0
        t = Text()
        t.append("▰" * fill, style="green")
        t.append("▱" * (width - fill), style="#333333")
        t.append(f"  {done}/{total}  {pct}%", style="bold #cdd6f4")
        self.query_one("#menu-progress", Static).update(t)

    # ---- A-vs-B comparison cards for the dual ghost-writing drills ------------ #
    # Each card = two ways to write (near-)equivalent code.  The user ghost-types
    # side A, sees its output, then side B, then the split screen bolds + flashes
    # both and explains WHY a programmer picks one over the other.
    COMPARE_CARDS = {
        "loops": {
            "topic": "loops",
            "a": {"caption": "for — a KNOWN number of times",
                  "code": "for i in range(3):\n    print(i)"},
            "b": {"caption": "while — UNTIL a condition is false",
                  "code": "n = 0\nwhile n < 3:\n    print(n)\n    n += 1"},
            "why": "Both print 0, 1, 2. Programmers pick FOR when they know the count up front — it reads in one line. They pick WHILE when the stopping point depends on something that changes — like user input or a sensor. for is the default; while is for when you can't know how many times.",
            "rules": "RULES: for always pairs with a loop variable (i) and range. while MUST change something inside (n += 1) or it never stops. The colon ends the line and TAB opens the block under it."},
        "functions": {
            "topic": "functions",
            "a": {"caption": "def — a named, reusable recipe",
                  "code": "def double(x):\n    return x * 2\n\nprint(double(5))"},
            "b": {"caption": "lambda — a tiny one-line function",
                  "code": "double = lambda x: x * 2\nprint(double(5))"},
            "why": "Both print 10. def is the real way: it can hold many lines and has a name. lambda is a shortcut for one tiny expression — used where a function is needed for a second, like inside sorted(key=...). If it needs more than one line, lambda is illegal — def wins by default.",
            "rules": "RULES: def needs a name, a colon, and a TAB-indented body. return hands a value back — print only shows things, return lets you USE them."},
        "print_vs_return": {
            "topic": "functions",
            "a": {"caption": "print — shows a value to you",
                  "code": "def add(a, b):\n    print(a + b)\n\nadd(2, 3)\nx = add(2, 3)\nprint(\"x is:\", x)"},
            "b": {"caption": "return — hands the value BACK",
                  "code": "def add(a, b):\n    return a + b\n\nprint(add(2, 3))\nx = add(2, 3)\nprint(\"x is:\", x)"},
            "why": "print just paints text on the screen and gives you nothing back — x ends up as None. return gives the value to whoever called the function, so x becomes 5. Real code is built from return; print is only for the human watching.",
            "rules": "RULES: return stops the function and hands the value back. A function with no return hands back None. print(...) always shows — but never saves."},
        "list_vs_tuple": {
            "topic": "lists",
            "a": {"caption": "list [ ] — can change",
                  "code": "planets = [\"mars\", \"earth\"]\nplanets.append(\"venus\")\nprint(planets)"},
            "b": {"caption": "tuple ( ) — locked forever",
                  "code": "pair = (\"mars\", \"earth\")\nprint(pair)"},
            "why": "Lists can grow and change — append works. Tuples are frozen after creation — you can't append. Programmers use tuples for fixed facts (coordinates, dates) because nothing can accidentally change them, and lists for collections that evolve. Square brackets = changeable, round brackets = fixed.",
            "rules": "RULES: [ ] creates the list AND grabs items by position (planets[0]). ( ) groups things and creates a tuple when it holds values separated by commas."},
        "quotes": {
            "topic": "strings",
            "a": {"caption": "f-string — build text with values inside",
                  "code": "name = \"bean\"\nage = 27\nprint(f\"hi {name}, you are {age}\")"},
            "b": {"caption": "+ joining — glue pieces together",
                  "code": "name = \"bean\"\nage = 27\nprint(\"hi \" + name + \", you are \" + str(age))"},
            "why": "Both print the same sentence. The f-string reads like the real sentence with holes filled in — that's why it's the modern favorite. The + way needs str() around numbers and gets messy fast. Quotes: single and double are identical, but f-strings need the f before the opening quote.",
            "rules": "RULES: f\"...\" = format — {name} pulls the variable's value into the text. + glues strings only — numbers need str() first. \" and ' are the same thing; the f is what makes {} work."},
        "equals": {
            "topic": "variables",
            "a": {"caption": "= assigns — put a value INTO a box",
                  "code": "lives = 3\nlives = lives - 1\nprint(lives)"},
            "b": {"caption": "== compares — are these equal?",
                  "code": "lives = 3\nprint(lives == 3)\nprint(lives == 0)"},
            "why": "One = is a command: put the right side into the left side (lives becomes 2). Two == is a question: is the left equal to the right? It answers True or False. Mixing them up is the most famous beginner bug in programming.",
            "rules": "RULES: = has a variable name on the left, NEVER a comparison. == only appears inside if and while conditions. A variable name is a label: letters, digits, _ — no spaces, and _ joins words (high_score)."},
        "init": {
            "topic": "classes",
            "a": {"caption": "class + __init__ — a template with a setup step",
                  "code": "class Player:\n    def __init__(self, name):\n        self.name = name\n        self.hp = 100\n\np = Player(\"bean\")\nprint(p.name, p.hp)"},
            "b": {"caption": "a plain dict — data without behavior",
                  "code": "p = {\"name\": \"bean\", \"hp\": 100}\nprint(p[\"name\"], p[\"hp\"])"},
            "why": "Both hold the same two facts. __init__ runs automatically when you build the object — it's the setup ritual, and self means THIS object, so every Player gets its own name and hp. Classes win when the data has behavior (methods like p.attack()); a dict is fine when it's pure data.",
            "rules": "RULES: __init__ is always called __init__ (two _ on each side = special). self is the first parameter of every method and is the object itself. Class names start with a Capital; variables start lowercase."},
        "dict_access": {
            "topic": "dicts",
            "a": {"caption": "[key] — direct, but crashes if missing",
                  "code": "menu = {\"tea\": 2, \"cake\": 5}\nprint(menu[\"tea\"])"},
            "b": {"caption": ".get() — safe, gives a fallback",
                  "code": "menu = {\"tea\": 2, \"cake\": 5}\nprint(menu.get(\"tea\"))\nprint(menu.get(\"soup\", \"not on menu\"))"},
            "why": "menu[\"tea\"] is short, but asking for a missing key crashes the program. menu.get(\"soup\", fallback) hands back the fallback instead of crashing. Programmers use [key] when the key must exist, and .get() when it might not — real APIs are full of might-nots, so .get() saves lives.",
            "rules": "RULES: { } builds the dict — every entry is key: value with a comma between entries. [key] looks up by key. .get(key, fallback) = look up, or give me this instead of an error."},
        "elifs": {
            "topic": "conditionals",
            "a": {"caption": "if / elif — ONE winner among choices",
                  "code": "score = 7\nif score >= 9:\n    print(\"A\")\nelif score >= 6:\n    print(\"B\")\nelse:\n    print(\"C\")"},
            "b": {"caption": "if / if — every check runs",
                  "code": "score = 7\nif score >= 9:\n    print(\"A\")\nif score >= 6:\n    print(\"B\")\nif score < 6:\n    print(\"C\")"},
            "why": "With elif, Python stops at the first true branch — exactly one grade prints. With separate ifs, every true branch fires — score 7 would print B only here, but a score of 10 would print A and B. elif = pick ONE; a chain of ifs = each question asked on its own.",
            "rules": "RULES: if starts the chain, elif continues it, else catches the rest. The colon ends each condition, and the TAB-indented block under it is what runs. Only the first matching branch runs in an if/elif/else."},
        "casting": {
            "topic": "casting",
            "a": {"caption": "int() — turn text into a number to do math",
                  "code": "age = \"27\"\nyears_left = 100 - int(age)\nprint(years_left)"},
            "b": {"caption": "str() — turn a number into text to print it",
                  "code": "wins = 3\nprint(\"you have \" + str(wins) + \" wins\")"},
            "why": "input() always hands you TEXT, even if the user typed 27 — and you can't do 100 - \"27\". int() converts text to a number so math works. Going the other way, \"you have \" + 3 crashes too — str() converts a number to text so it can join a sentence. Convert when the two worlds meet.",
            "rules": "RULES: int(\"27\") → the number 27. str(3) → the text \"3\". The quotes are the difference: \"27\" is text, 27 is a number. You can't mix them in math or in + joining."},
        "break_vs_continue": {
            "topic": "loops",
            "a": {"caption": "break — STOP the whole loop",
                  "code": "for i in range(6):\n    if i == 3:\n        break\n    print(i)"},
            "b": {"caption": "continue — skip ONE lap, keep going",
                  "code": "for i in range(6):\n    if i == 3:\n        continue\n    print(i)"},
            "why": "break prints 0, 1, 2 and STOPS — the loop is dead. continue prints 0, 1, 2, 4, 5 — only the 3 is skipped, then the loop keeps running. Programmers break when the answer is found (search is over), and continue when one bad item must be skipped (filter out junk).",
            "rules": "RULES: break = exit the loop now. continue = jump to the next lap now. Both live INSIDE the loop's Tab-indented block, usually guarded by an if."},
        "moddiv": {
            "topic": "math",
            "a": {"caption": "% — the LEFTOVER after division",
                  "code": "print(17 % 5)\nprint(8 % 2)"},
            "b": {"caption": "// — whole-number division",
                  "code": "print(17 // 5)\nprint(8 // 2)"},
            "why": "% prints 2 then 0: 17 = 5×3 with 2 left over, and 8 has no leftover. // prints 3 then 4: it throws the remainder away entirely. Programmers use % to test even/odd (n % 2 == 0), and // when they need exact whole groups — like rows of 5.",
            "rules": "RULES: % rhymes with REMAINDER — the leftover. // floors down to the whole number. 17 % 5 = 2 · 17 // 5 = 3 · and n % 2 == 0 is the classic even-number test."},
        "append_vs_concat": {
            "topic": "lists",
            "a": {"caption": "append() — changes the list IN PLACE",
                  "code": "a = [1, 2]\na.append(3)\nprint(a)"},
            "b": {"caption": "+ — builds a NEW list, old one untouched",
                  "code": "a = [1, 2]\nb = a + [3]\nprint(a)\nprint(b)"},
            "why": "append gives you one list: [1, 2, 3] — a itself changed. The + version prints [1, 2] then [1, 2, 3] — a is untouched, b is the new list. Programmers append when the original should grow (a shopping cart), and use + when the original must stay intact (you need both versions).",
            "rules": "RULES: .append() is a command — it returns nothing, it just changes the list. + makes a brand-new list you usually save into a variable. a stays as it was."},
        "index_vs_enumerate": {
            "topic": "loops",
            "a": {"caption": "range(len(...)) — count positions by hand",
                  "code": "fruits = [\"kiwi\", \"fig\"]\nfor i in range(len(fruits)):\n    print(i, fruits[i])"},
            "b": {"caption": "enumerate() — index and item together",
                  "code": "fruits = [\"kiwi\", \"fig\"]\nfor i, f in enumerate(fruits):\n    print(i, f)"},
            "why": "Both print 0 kiwi then 1 fig. range(len()) is the manual way — you must remember fruits[i] yourself and it's easy to get wrong. enumerate hands you BOTH the position and the item in one step, so there's nothing to forget. Programmers reach for enumerate whenever a loop needs the index.",
            "rules": "RULES: enumerate(list) gives back (index, item) pairs — for i, f in ... unpacks the pair into two names. len() counts how many items, range() counts the numbers."},
        "open_modes": {
            "topic": "files",
            "a": {"caption": "\"w\" — write: wipes and starts fresh",
                  "code": "with open(\"n.txt\", \"w\") as f:\n    f.write(\"new\")\nwith open(\"n.txt\") as f:\n    print(f.read())"},
            "b": {"caption": "\"a\" — append: adds to the end",
                  "code": "with open(\"n.txt\", \"a\") as f:\n    f.write(\"new\")\nwith open(\"n.txt\") as f:\n    print(f.read())"},
            "why": "\"w\" erases whatever was there and writes fresh — the file ends up as just 'new'. \"a\" keeps the old content and tacks 'new' on the end. Programmers use \"w\" for a fresh save and \"a\" for logs, journals, and anything that must never lose its history.",
            "rules": "RULES: open(path, mode) — the second argument is the MODE. \"w\" = wipe then write, \"a\" = append, \"r\" = read (the default). with open(...) as f: auto-closes."},
        "json_loads_dumps": {
            "topic": "json",
            "a": {"caption": "dumps() — dict OUT to JSON text",
                  "code": "import json\ns = json.dumps({\"name\": \"bean\"})\nprint(s)\nprint(type(s).__name__)"},
            "b": {"caption": "loads() — JSON text IN to a dict",
                  "code": "import json\nd = json.loads('{\"name\": \"bean\"}')\nprint(d[\"name\"])\nprint(type(d).__name__)"},
            "why": "dumps takes a Python dict and turns it OUT into a JSON string (you can see it's str). loads takes a JSON string and turns it INto a real dict (so d[\"name\"] works). One direction is for saving/sending, the other for reading/receiving. The 's' in both = 'string'.",
            "rules": "RULES: dumps(dict) → string. loads(string) → dict. JSON strings use double quotes for keys and values. After loads, it's a normal dict — d[\"key\"] works."},
        "assert_vs_if": {
            "topic": "testing",
            "a": {"caption": "assert — PROVE a fact, crash if wrong",
                  "code": "x = 2 + 2\nassert x == 4\nprint(\"still running\")"},
            "b": {"caption": "if — HANDLE a case gracefully",
                  "code": "x = 2 + 2\nif x != 4:\n    print(\"something is off\")\nprint(\"still running\")"},
            "why": "assert is a test: it declares 'this MUST be true' and kills the program if it isn't — that's how you catch bugs early. if is program logic: 'IF this happens, do that' and life goes on. Programmers assert in tests (to prove code correct) and use if in real code (to handle real situations).",
            "rules": "RULES: assert CONDITION — no colon, no indent block. It raises AssertionError if the condition is False. if CONDITION: needs the colon and a Tab-indented block under it."},
        "inheritance": {
            "topic": "classes",
            "a": {"caption": "copy-paste — write speak() twice",
                  "code": "class Dog:\n    def speak(self):\n        print(\"woof\")\n\nclass Cat:\n    def speak(self):\n        print(\"meow\")\n\nDog().speak()\nCat().speak()"},
            "b": {"caption": "inherit — write it once, share it",
                  "code": "class Animal:\n    def speak(self):\n        print(\"sound\")\n\nclass Dog(Animal):\n    pass\n\nclass Cat(Animal):\n    def speak(self):\n        print(\"meow\")\n\nDog().speak()\nCat().speak()"},
            "why": "When two classes do the same thing, copy-paste means every fix must be made twice. Inheritance lets Dog and Cat SHARE the base Animal's speak() for free — and Cat overrides just the one bit it wants to change. A subclass IS-A its parent; it inherits everything, then tweaks what differs.",
            "rules": "RULES: class Child(Parent): makes Child inherit Parent's methods. super().__init__(...) calls the parent's setup. A method the child defines again OVERRIDES the parent's."},
        "loop_vs_comprehension": {
            "topic": "comprehension",
            "a": {"caption": "a for loop — three lines",
                  "code": "out = []\nfor n in [1, 2, 3]:\n    out.append(n * 2)\nprint(out)"},
            "b": {"caption": "a comprehension — one line",
                  "code": "print([n * 2 for n in [1, 2, 3]])"},
            "why": "Both print [2, 4, 6]. The loop builds the list by hand: make an empty list, append each result. The comprehension declares the WHOLE list in one expression — no empty box, no append, no extra bookkeeping. Programmers use comprehensions for the simple transform-a-list case and reach for a loop when the body gets complicated.",
            "rules": "RULES: [RESULT for ITEM in LIST] builds a list. Add `if KEEP` at the end to filter. {K: V for ITEM in LIST} makes a dict, {ITEM for ITEM in LIST} makes a set."},
        "slicing": {
            "topic": "strings",
            "source": "HELLO",
            "variants": [
                {"caption": "s[::] — the whole string",
                 "code": 's = "HELLO"\nprint(s[::])',
                 "result": "HELLO", "picked": [0, 1, 2, 3, 4]},
                {"caption": "s[::-1] — reverse it",
                 "code": 's = "HELLO"\nprint(s[::-1])',
                 "result": "OLLEH", "picked": [0, 1, 2, 3, 4]},
                {"caption": "s[::-2] — every 2nd from the end",
                 "code": 's = "HELLO"\nprint(s[::-2])',
                 "result": "OLH", "picked": [4, 2, 0]},
                {"caption": "s[1:4] — positions 1 up to (not incl) 4",
                 "code": 's = "HELLO"\nprint(s[1:4])',
                 "result": "ELL", "picked": [1, 2, 3]},
            ],
            "why": ("A slice has THREE parts: [START : STOP : STEP]. START = where to "
                    "begin, STOP = where to stop (NOT included), STEP = how many to jump "
                    "— and a NEGATIVE step walks backwards. That's why ::-1 reverses: "
                    "it walks from the end, one letter at a time."),
            "rules": "s[start : stop : step]  ·  start defaults to 0  ·  stop defaults to the end  ·  step defaults to 1  ·  a negative step reverses the walk",
        },
    }

