    def _vim_checkpoint_label(self):
        """A one-line description of the saved VIM checkpoint, or "" if none."""
        cp = self.p.get("vim_checkpoint")
        if not isinstance(cp, dict):
            return ""
        phase = cp.get("phase")
        idx = cp.get("idx")
        if phase == "challenge" and isinstance(idx, int) and 0 <= idx < len(VIM_CHALLENGES):
            return f"challenge {idx + 1} — {VIM_CHALLENGES[idx]['title']}"
        if phase == "lesson" and isinstance(idx, int) and 0 <= idx < len(VIM_LESSONS):
            return f"lesson {idx + 1}"
        return ""

    def _shell_checkpoint_label(self):
        """A one-line description of where the learner is in BUILD STUFF, or \"\"."""
        cp = self.p.get("build_checkpoint")
        if isinstance(cp, dict) and isinstance(cp.get("idx"), int):
            idx = cp["idx"]
            if 0 <= idx < len(SHELL_LESSONS):
                return f"lesson {idx + 1} — {SHELL_LESSONS[idx]['title']}"
        step = self.p.get("build_step")
        if isinstance(step, int) and step > 0 and step < len(SHELL_LESSONS):
            return f"lesson {step + 1} — {SHELL_LESSONS[step]['title']}"
        return ""

    def _dev_checkpoint_label(self):
        """A one-line description of where the learner is in CLOUD & DEVOPS, or \"\"."""
        cp = self.p.get("dev_checkpoint")
        if isinstance(cp, dict) and isinstance(cp.get("idx"), int):
            idx = cp["idx"]
            if 0 <= idx < len(DEV_LESSONS):
                return f"{DEV_LESSONS[idx]['module']} — {DEV_LESSONS[idx]['title']}"
        step = self.p.get("dev_step")
        if isinstance(step, int) and 0 < step < len(DEV_LESSONS):
            return f"{DEV_LESSONS[step]['module']} — {DEV_LESSONS[step]['title']}"
        return ""

    def _dev_resume_first(self):
        """The lesson index to resume from, or None if the course is untouched."""
        cp = self.p.get("dev_checkpoint")
        if isinstance(cp, dict) and isinstance(cp.get("idx"), int):
            if 0 <= cp["idx"] < len(DEV_LESSONS):
                return cp["idx"]
        step = self.p.get("dev_step")
        if isinstance(step, int) and 0 < step < len(DEV_LESSONS):
            return step
        return None

    def _dev_module_done(self, m):
        """How many of a module's lessons are done (for the picker)."""
        step = self.p.get("dev_step", 0)
        if not isinstance(step, int):
            return 0
        done = min(step, m["first"] + m["count"]) - m["first"]
        return max(0, min(done, m["count"]))

    def _dev_module_items(self):
        """The picker list: an optional resume entry, then every module."""
        items = []
        resume = self._dev_resume_first()
        if resume is not None:
            items.append({"name": "Resume where you left off", "first": resume,
                          "resume": True, "count": 0, "done": 0})
        for m in DEV_MODULES:
            items.append({"name": m["name"], "first": m["first"], "resume": False,
                          "count": m["count"], "done": self._dev_module_done(m)})
        return items

    def _dev_enter_module(self):
        items = self._dev_module_items()
        if 0 <= self.menu_sel < len(items):
            play_menu_blip(3)
            self._dev_begin(items[self.menu_sel]["first"])

    def _snap_menu_scroll(self, sel_line: int):
        """Keep the selected row visible in the picker list. The scroll is
        deferred twice: the first post-refresh callback can run before the
        new content height is measured, so the second pass (a tick later)
        catches it. Clamped to max_scroll_y so the bottom rows are always
        reachable."""
        try:
            scroll = self.query_one("#menu-list", VerticalScroll)
        except Exception:
            return

        def snap():
            try:
                scroll.scroll_to(y=min(sel_line, max(0, scroll.max_scroll_y)),
                                 animate=False)
            except Exception:
                pass

        self.call_after_refresh(snap)
        self.call_later(lambda *_a: self.call_after_refresh(snap), 0.05)

    def _render_dev_module_list(self):
        t = Text()
        t.append("── CLOUD & DEVOPS ", style="bold #7dd3fc")
        t.append(f"({len(DEV_MODULES)} modules · {len(DEV_LESSONS)} lessons)", style="dim")
        t.append("\n\n")
        items = self._dev_module_items()
        sel_line = 0
        line_no = 0
        for i, it in enumerate(items):
            sel = i == self.menu_sel
            line = Text()
            line.append("▶ " if sel else "  ")
            if it.get("resume"):
                line.append("⏵ ", style="bold yellow")
                line.append(it["name"], style="bold yellow" if sel else "#fbbf24")
            else:
                if it["done"] >= it["count"] and it["count"] > 0:
                    line.append("✓ ", style="green")
                else:
                    line.append("· ", style="dim")
                line.append(it["name"], style="bold" if sel else "#d5d5d5")
                line.append(f"   {it['done']}/{it['count']}", style="dim")
            if sel:
                line.stylize("reverse")
                sel_line = line_no
            t.append_text(line)
            t.append("\n")
            line_no += 1
        t.append("\nEnter — start · ← back to series · j/k — move", style="dim")
        self.query_one("#menu-list-inner", Static).update(t)
        self._snap_menu_scroll(sel_line)

    def _net_module_items(self):
        """The NETWORK+ picker list: an optional resume entry, then the modules."""
        items = []
        if isinstance(self.p.get("net_module"), int) \
                and not self.p.get("net_course_done"):
            m = min(self.p["net_module"], len(NET_MODULES) - 1)
            items.append({"name": "Resume where you left off", "first": m,
                          "resume": True, "count": 0, "done": 0})
        for i, m in enumerate(NET_MODULES):
            if m["name"] == "TODAY'S REVIEW":
                n_due = len(self._net_due_concepts())
                items.append({"name": m["name"], "first": i, "resume": False,
                              "count": m["count"],
                              "done": 1 if n_due == 0 else 0,
                              "due": n_due})
            else:
                done = self.p.get("net_done", {}).get(m["name"], 0)
                items.append({"name": m["name"], "first": i, "resume": False,
                              "count": m["count"], "done": done})
        return items

    def _net_enter_module(self):
        items = self._net_module_items()
        if 0 <= self.menu_sel < len(items):
            play_menu_blip(3)
            self._net_begin(items[self.menu_sel]["first"])

    def _render_net_module_list(self):
        t = Text()
        t.append("── NETWORK+ ", style="bold #ffa657")
        t.append(f"({len(NET_MODULES)} modules · {len(NET_QUESTIONS)} "
                 f"questions · 3 labs)", style="dim")
        t.append("\n\n")
        items = self._net_module_items()
        sel_line = 0
        line_no = 0
        for i, it in enumerate(items):
            sel = i == self.menu_sel
            line = Text()
            line.append("▶ " if sel else "  ")
            if it.get("resume"):
                line.append("⏵ ", style="bold yellow")
                line.append(it["name"], style="bold yellow" if sel else "#fbbf24")
            else:
                if "due" in it:
                    if it["due"]:
                        line.append("⏰ ", style="bold #ffa657")
                    else:
                        line.append("✓ ", style="green")
                elif it["done"] >= it["count"] and it["count"] > 0:
                    line.append("✓ ", style="green")
                else:
                    line.append("· ", style="dim")
                line.append(it["name"], style="bold" if sel else "#d5d5d5")
                if "due" in it:
                    if it["due"]:
                        line.append(f"   {it['due']} due today",
                                    style="bold #ffa657")
                    else:
                        line.append("   all clear", style="green")
                else:
                    line.append(f"   {it['done']}/{it['count']}", style="dim")
            if sel:
                line.stylize("reverse")
                sel_line = line_no
            t.append_text(line)
            t.append("\n")
            line_no += 1
        t.append("\nEnter — start · ← back to series · j/k — move", style="dim")
        self.query_one("#menu-list-inner", Static).update(t)
        self._snap_menu_scroll(sel_line)

    def _series_order(self) -> list:
        """The ordered list of series `si` values as they appear on screen —
        navigation follows THIS list, so every row (including PYTHON LAB and the
        conditional FIX THESE) is reachable with j/k."""
        order = []
        if self._failed_entries():
            order.append(-5)          # FIX THESE (only when there are misses)
        order += [-4, -3, -2, -1]     # NETWORK+, CLOUD, BUILD, VIM
        order.append(-7)              # INTERVIEW PREP
        order.append(-8)              # LINUX DRILLS
        order.append(-9)              # RECALL GYM
        order.append(-10)             # MINI PROJECTS
        order.append(-6)              # PYTHON LAB
        order += list(range(len(GROUPS)))
        order.append(len(GROUPS))     # PYTHON REVIEW
        return order

    def _render_series_list(self):
        """One line per series — every course visible at once, the selected
        row reverse-highlighted so the selection is impossible to miss. The
        long descriptions live in the PREVIEW panel next door."""
        t = Text()
        t.append("CHOOSE A SERIES", style="bold magenta")
        t.append("\n\n")
        net_done = bool(self.p.get("net_course_done"))
        dev_done = (isinstance(self.p.get("dev_step"), int)
                    and self.p["dev_step"] >= len(DEV_LESSONS))
        build_done = (isinstance(self.p.get("build_step"), int)
                      and self.p["build_step"] >= len(SHELL_LESSONS))
        failed = self._failed_entries()
        rows = []
        if failed:
            # the 'fix these' queue rides at the VERY top — mistakes first
            rows.append((-5, "FIX THESE", "#f87171", "re-practice what you missed",
                         f"{len(failed)} to fix"))
        rows += [
            (-4, "NETWORK+", "#ffa657", "noob → network engineer",
             "✓ done" if net_done else ""),
            (-3, "CLOUD & DEVOPS", "#7dd3fc", "noob → engineer",
             "✓ done" if dev_done else ""),
            (-2, "BUILD STUFF", "#7ee787", "bash → your programs",
             "✓ done" if build_done else ""),
            (-1, "VIM / NEOVIM", "#d8b4fe", "keyboard dojo", ""),
            (-7, "INTERVIEW PREP", "#7dd3fc", "AWS · Azure · Linux · k8s · TF · Ansible — MC + flashcards", ""),
            (-8, "LINUX DRILLS", "#7ee787", "TTS drills: make this / what is this · missions · hints when stuck", ""),
            (-9, "RECALL GYM", "#c084fc", "cross-track recall — build it from scratch, fresh instance each time", ""),
            (-10, "MINI PROJECTS", "#f9a8d4", "build & deploy: data plot · bootstrap · ssh login · stream · ansible", ""),
            (-6, "PYTHON LAB", "#a6e3a1", "playground — every example, edit & run", ""),
        ]
        for gi, g in enumerate(GROUPS):
            done, total = self._group_progress(gi)
            rows.append((gi, g["name"], "#f9a8d4",
                         f"python — {total} challenges", f"{done}/{total}"))
        # the spaced-repetition review queue rides at the very bottom
        n_due = len(self._py_due_topics())
        rows.append((len(GROUPS), "PYTHON REVIEW", "#a5f3fc",
                     "your due-today queue",
                     f"⏰ {n_due} due" if n_due else "✓ all clear"))
        sel_line = 0
        line_no = 2                       # header (line 0) + blank (line 1)
        self._series_line_map = {}         # rendered line → series `si` (mouse select)
        for i, (si, name, color, desc, status) in enumerate(rows):
            self._series_line_map[line_no] = si
            sel = self.series_sel == si
            if sel:
                # BOXED selection: a solid full-bar with ▐/▌ edges so the chosen
                # row reads as a distinct box, never wraps (desc clipped)
                line = Text()
                line.append("▐ ", style=f"bold black on {color}")
                line.append(name, style=f"bold black on {color}")
                line.append("  ")
                line.append(self._clip(desc, 32), style=f"black on {color}")
                if status:
                    line.append("  ")
                    line.append(status, style=f"bold black on {color}")
                line.append(" ▌", style=f"bold black on {color}")
                sel_line = line_no
            else:
                line = Text()
                line.append("▸ ", style="dim")
                line.append(name, style=f"bold {color}")
                line.append("  ")
                line.append(self._clip(desc, 24), style="dim")
                if status:
                    line.append("  ")
                    line.append(status,
                                style="bold #22c55e" if status.startswith("✓")
                                else ("bold #ffa657" if status.startswith("⏰")
                                      else "dim"))
            t.append_text(line)
            t.append("\n")
            line_no += 1
            # a clean divider between the non-Python paths and the Python
            # course stack, and again before the review queue
            if si == -10 or si == len(GROUPS) - 1:
                t.append("─" * 46, style="#3a3a3a")
                t.append("\n")
                line_no += 1
        # one context line for the selected series: where you'd resume
        t.append("\n")
        note = ""
        if self.series_sel == -5:
            failed = self._failed_entries()
            note = f"{len(failed)} challenges to fix · Enter to re-practice the first one"
        elif self.series_sel == -4:
            label = net_checkpoint_label(self.p)
            note = f"resume: {label}" if label else "new path — start from the top"
            n_due = len(self._net_due_concepts())
            if n_due:
                note += f" · ⏰ {n_due} reviews due today"
        elif self.series_sel == -3:
            label = self._dev_checkpoint_label()
            note = f"resume: {label}" if label else "new path — start from the top"
        elif self.series_sel == -2:
            label = self._shell_checkpoint_label()
            note = f"resume: {label}" if label else "new path — start from the top"
        elif self.series_sel == -1:
            label = self._vim_checkpoint_label()
            note = f"resume: {label}" if label else "new path — start from the top"
        elif self.series_sel == len(GROUPS):
            n = len(self._py_due_topics())
            note = (f"⏰ {n} topics due today — Enter to review them now"
                    if n else "all caught up — nothing due today")
        elif self.series_sel == -6:
            note = "playground — every example in the course, edit & run · Enter to open"
        elif self.series_sel == -7:
            n = len(INTERVIEW_QUESTIONS)
            weak = len(self.p.get("iv_weak", {}))
            note = (f"interview questions — {n} questions (2 wordings each), "
                    f"multiple choice + flashcards"
                    + (f" · {weak} weak concepts to revisit" if weak else ""))
        elif self.series_sel == -8:
            n = len(LINUX_DRILLS)
            note = (f"linux drills — {n} quick bash tasks + {len(LINUX_MISSIONS)} "
                    f"missions · graded by result, hints when stuck")
        elif self.series_sel == -9:
            due = len(_due_concepts(self.p))
            weak = len(_weak_concepts(self.p, 25))
            note = (f"recall gym — cross-track recall across all your skills · "
                    f"{due} due now" + (f", {weak} weak" if weak else ""))
        elif self.series_sel == -10:
            note = (f"mini projects — build & deploy {len(PROJECTS)} small things "
                    f"end-to-end in the simulation")
        else:
            g = GROUPS[self.series_sel]
            note = f"{g['name']} — Enter to browse its challenges"
        if note:
            t.append(note, style="bold yellow")
            t.append("\n")
        # "your skills" — what you're struggling with vs solid on (from mastery)
        weak = _weak_concepts(self.p, 3)
        strong = _strong_concepts(self.p, 3)
        if weak or strong:
            t.append("\n")
            if weak:
                t.append("struggling with: ", style="bold #f87171")
                t.append(", ".join(_skill_label(c) for c in weak), style="#fca5a5")
            if strong:
                if weak:
                    t.append("   ·   ", style="dim")
                t.append("solid on: ", style="bold #22c55e")
                t.append(", ".join(_skill_label(c) for c in strong), style="#86efac")
            t.append("\n")
        t.append("\nEnter — open a series   ·   j/k — move   ·   g — map   ·   q — quit",
                 style="dim")
        self.query_one("#menu-list-inner", Static).update(t)
        self._snap_menu_scroll(sel_line)

    def _render_challenge_list(self):
        g = GROUPS[self.series_sel]
        t = Text()
        t.append(f"── {g['name']} ", style="bold cyan")
        t.append(f"({len(g['challenges'])} challenges)", style="dim")
        t.append("\n\n")
        sel_line = 0
        line_no = 2                       # header (line 0) + blank (line 1)
        self._challenge_line_map = {}      # rendered line -> menu_sel (mouse select)
        # MASTERY CHECK rides at the top of every course: 3 no-help challenges
        sel = self.menu_sel == -1
        self._challenge_line_map[line_no] = -1
        line = Text()
        line.append("▶ " if sel else "  ")
        line.append("🏁 ", style="bold #c084fc")
        line.append("MASTERY CHECK", style="bold #c084fc")
        line.append("  — 3 no-help challenges · prove this course", style="dim")
        if sel:
            line.stylize("reverse")
            sel_line = line_no
        t.append_text(line)
        t.append("\n")
        line_no += 1
        for ci, c in enumerate(g["challenges"]):
            st = challenge_stat(self.p, c["title"])
            right, wrong = st["right"], st["wrong"]
            sel = ci == self.menu_sel
            self._challenge_line_map[line_no] = ci
            line = Text()
            line.append("▶ " if sel else "  ")
            if right > 0:
                line.append("✓ ", style="green")
            elif wrong > 0:
                line.append("✗ ", style="red")
            else:
                line.append("· ", style="dim")
            line.append(self._clip(c["title"], 40), style="bold" if sel else "")
            if sel:
                line.stylize("reverse")
                sel_line = line_no
            t.append_text(line)
            t.append("\n")
            line_no += 1
        t.append("\nEnter — start   ·   ← back to series   ·   j/k — move", style="dim")
        self.query_one("#menu-list-inner", Static).update(t)
        self._snap_menu_scroll(sel_line)

    def _preview_challenge(self):
        if self.series_sel in (-1, -2, -3, -4, -7, -8) or self.series_sel == len(GROUPS):
            return None   # courses / the review queue — handled separately
        if self.menu_level == "series":
            g = GROUPS[self.series_sel]
            return g["challenges"][0] if g["challenges"] else None
        g = GROUPS[self.series_sel]
        return g["challenges"][self.menu_sel] if 0 <= self.menu_sel < len(g["challenges"]) else None

